def load_weapon_definitions():
    definitions = {}
    for path in sorted((APP_DIR / "weapons").glob("*.json")):
        try:
            item = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(item, dict):
                continue
            weapon_id = str(item["id"])
            modifiers = {
                stat: int(item.get("modifiers", {}).get(stat, 0))
                for stat in ("strength", "defense", "magic", "agility")
            }
            definitions[weapon_id] = {
                "id": weapon_id,
                "name": str(item.get("name", weapon_id.replace("_", " ").title())),
                "modifiers": modifiers,
            }
        except (OSError, ValueError, TypeError, KeyError):
            continue
    if definitions:
        return definitions
    return {
        "rusty_sword": {
            "id": "rusty_sword",
            "name": "Rusty Sword",
            "modifiers": {stat: 0 for stat in ("strength", "defense", "magic", "agility")},
        }
    }


def load_mount_definitions():
    definitions = {}
    for path in sorted((APP_DIR / "mounts").glob("*.json")):
        try:
            item = json.loads(path.read_text(encoding="utf-8"))
            mount_id = str(item["id"])
            definitions[mount_id] = {
                **item,
                "id": mount_id,
                "name": str(item.get("name", mount_id.replace("_", " ").title())),
                "speed": max(1.0, float(item.get("speed", 280))),
                "seat_height": max(30.0, float(item.get("seat_height", 100))),
                "mount_radius": max(25.0, float(item.get("mount_radius", 55))),
                "abilities": dict(item.get("abilities", {})),
            }
        except (OSError, ValueError, TypeError, KeyError):
            continue
    return definitions


