@dataclass(frozen=True)
class Knight:
    key: str
    name: str
    title: str
    armor: tuple[int, int, int]
    accent: tuple[int, int, int]
    glow: tuple[int, int, int]
    emblem: str
    playable: bool = True
    roster_index: int = 0
    has_magic: bool = False
    starting_weapon: str = "rusty_sword"
    base_health: int = 100
    max_mana: int = 100
    magic: dict = field(default_factory=dict, compare=False)
    magic_element: str = ""
    texture_dir: str = ""
    magic_texture_dir: str = ""


def load_character_definitions():
    definitions = []
    folder = APP_DIR / "characters"
    for path in sorted(folder.glob("*.json")):
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            definitions.append(
                Knight(
                    key=str(data["id"]),
                    name=str(data["display_name"]),
                    title=str(data.get("title", data["display_name"])),
                    armor=tuple(data.get("armor", [100, 100, 100])),
                    accent=tuple(data.get("accent", [220, 220, 220])),
                    glow=tuple(data.get("glow", [255, 255, 255])),
                    emblem=str(data.get("emblem", "?")),
                    playable=bool(data.get("playable", False)),
                    roster_index=int(data.get("roster_index", 999)),
                    has_magic=bool(data.get("has_magic", False)),
                    starting_weapon=str(data.get("starting_weapon", "rusty_sword")),
                    base_health=max(1, int(data.get("base_health", 100))),
                    max_mana=max(0, int(data.get("max_mana", 100))),
                    magic=dict(data.get("magic", {}).get("abilities", data.get("magic", {}))),
                    magic_element=str(data.get("magic", {}).get("element", "")),
                    texture_dir=str(data.get("texture_dir", data["id"])),
                    magic_texture_dir=str(data.get("magic", {}).get("texture_dir", data["id"])),
                )
            )
        except (OSError, ValueError, TypeError, KeyError) as exc:
            raise ValueError(f"Invalid character definition: {path}") from exc
    if not definitions:
        raise ValueError("characters/*.json contains no character definitions")
    return tuple(sorted(definitions, key=lambda item: (item.roster_index, item.key)))


ALL_CHARACTERS = load_character_definitions()
CHARACTERS_BY_KEY = {character.key: character for character in ALL_CHARACTERS}
