class FrameInput:
    def __init__(self):
        self.up = self.down = self.left = self.right = False
        self.accept = self.back = self.start = self.attack = self.heavy = False
        self.jump = self.use_item = self.item_left = self.item_right = False
        self.magic_modifier = self.shield = False
        self.magic_a = self.magic_b = self.magic_x = self.magic_y = False
        self.axis_x = self.axis_y = 0.0


class SharedInput:
    """Keyboard and the combined all-controller facade for shared menus."""

    def __init__(self, controller):
        self.controller = controller
        self.previous = {}
        self.held = {}
        self.repeat_at = {}

    @staticmethod
    def value(device, name, default=False):
        try:
            return getattr(device, name)
        except Exception:
            return default

    def edge(self, name, active):
        was_active = self.previous.get(name, False)
        self.previous[name] = bool(active)
        return bool(active) and not was_active

    def repeat(self, name, active):
        now = time.monotonic()
        was_active = self.held.get(name, False)
        self.held[name] = bool(active)
        if active and not was_active:
            self.repeat_at[name] = now + 0.34
            return True
        if active and now >= self.repeat_at.get(name, float("inf")):
            self.repeat_at[name] = now + 0.11
            return True
        if not active:
            self.repeat_at.pop(name, None)
        return False

    def poll(self, events):
        result = FrameInput()
        pressed = pygame.key.get_pressed()
        keys = {event.key for event in events if event.type == pygame.KEYDOWN}
        stick = self.value(self.controller, "LS", None)
        try:
            sx, sy = float(stick.x), float(stick.y)
        except Exception:
            sx = sy = 0.0
        kx = float(pressed[pygame.K_RIGHT] or pressed[pygame.K_d]) - float(pressed[pygame.K_LEFT] or pressed[pygame.K_a])
        ky = float(pressed[pygame.K_DOWN] or pressed[pygame.K_s]) - float(pressed[pygame.K_UP] or pressed[pygame.K_w])
        result.axis_x = kx if kx else (sx if abs(sx) > 0.17 else 0.0)
        result.axis_y = ky if ky else (-sy if abs(sy) > 0.17 else 0.0)
        held = {
            "up": bool(self.value(self.controller, "DPAD_UP")) or sy > 0.52,
            "down": bool(self.value(self.controller, "DPAD_DOWN")) or sy < -0.52,
            "left": bool(self.value(self.controller, "DPAD_LEFT")) or sx < -0.52,
            "right": bool(self.value(self.controller, "DPAD_RIGHT")) or sx > 0.52,
        }
        keyboard = {
            "up": pygame.K_UP in keys or pygame.K_w in keys,
            "down": pygame.K_DOWN in keys or pygame.K_s in keys,
            "left": pygame.K_LEFT in keys or pygame.K_a in keys,
            "right": pygame.K_RIGHT in keys or pygame.K_d in keys,
        }
        for name in held:
            setattr(result, name, keyboard[name] or self.repeat(name, held[name]))
        result.accept = pygame.K_RETURN in keys or pygame.K_SPACE in keys or self.edge("A", bool(self.value(self.controller, "A")))
        result.back = pygame.K_ESCAPE in keys or pygame.K_BACKSPACE in keys or self.edge("B", bool(self.value(self.controller, "B")))
        result.start = pygame.K_p in keys or self.edge("START", bool(self.value(self.controller, "START")))
        result.attack = result.accept or pygame.K_z in keys or pygame.K_j in keys
        result.heavy = pygame.K_y in keys or pygame.K_k in keys or self.edge("Y", bool(self.value(self.controller, "Y")))
        result.item_left = pygame.K_q in keys or self.edge("LB", bool(self.value(self.controller, "LB")))
        result.item_right = pygame.K_e in keys or self.edge("RB", bool(self.value(self.controller, "RB")))
        return result


