class LocalInput:
    """Tracks join, character selection, and gameplay per physical controller."""

    def __init__(self):
        self.previous = {}
        self.held = {}
        self.repeat_at = {}

    @staticmethod
    def value(device, name, default=False):
        if device is None:
            return default
        try:
            return getattr(device, name)
        except Exception:
            return default

    def edge(self, key, name, active):
        state_key = (key, name)
        previous = self.previous.get(state_key, False)
        self.previous[state_key] = bool(active)
        return bool(active) and not previous

    def prime(self, key, name, active=True):
        self.previous[(key, name)] = bool(active)

    def repeat(self, key, name, active):
        now = time.monotonic()
        state_key = (key, name)
        previous = self.held.get(state_key, False)
        self.held[state_key] = bool(active)
        if active and not previous:
            self.repeat_at[state_key] = now + 0.34
            return True
        if active and now >= self.repeat_at.get(state_key, float("inf")):
            self.repeat_at[state_key] = now + 0.13
            return True
        if not active:
            self.repeat_at.pop(state_key, None)
        return False

    def devices(self, group):
        try:
            candidates = group.controllers
        except Exception:
            candidates = [group]
        if not isinstance(candidates, (list, tuple)):
            candidates = [group]
        connected = []
        for device in candidates:
            try:
                if bool(device.connected):
                    connected.append(device)
            except Exception:
                pass
        return connected[:MAX_PLAYERS]

    def join_pressed(self, device):
        key = ("pad", id(device))
        return key, self.edge(key, "join_a", bool(self.value(device, "A")))

    def lobby_actions(self, player, events):
        keys = {event.key for event in events if event.type == pygame.KEYDOWN}
        if player.device is None:
            return {
                "up": pygame.K_UP in keys or pygame.K_w in keys,
                "down": pygame.K_DOWN in keys or pygame.K_s in keys,
                "accept": pygame.K_RETURN in keys,
                "back": pygame.K_ESCAPE in keys or pygame.K_BACKSPACE in keys,
            }
        up = bool(self.value(player.device, "DPAD_UP"))
        down = bool(self.value(player.device, "DPAD_DOWN"))
        return {
            "up": self.repeat(player.key, "lobby_up", up),
            "down": self.repeat(player.key, "lobby_down", down),
            "accept": self.edge(player.key, "lobby_a", bool(self.value(player.device, "A"))),
            "back": self.edge(player.key, "lobby_b", bool(self.value(player.device, "B"))),
        }

    def gameplay(self, spec, events):
        frame = FrameInput()
        keys = {event.key for event in events if event.type == pygame.KEYDOWN}
        pressed = pygame.key.get_pressed()
        if spec.device is None:
            frame.axis_x = float(pressed[pygame.K_RIGHT] or pressed[pygame.K_d]) - float(pressed[pygame.K_LEFT] or pressed[pygame.K_a])
            frame.axis_y = float(pressed[pygame.K_DOWN] or pressed[pygame.K_s]) - float(pressed[pygame.K_UP] or pressed[pygame.K_w])
            frame.attack = pygame.K_x in keys or pygame.K_j in keys
            frame.heavy = pygame.K_y in keys or pygame.K_k in keys
            frame.jump = pygame.K_SPACE in keys
            frame.use_item = pygame.K_b in keys or pygame.K_f in keys
            frame.item_left = pygame.K_q in keys
            frame.item_right = pygame.K_e in keys
            frame.magic_modifier = bool(pressed[pygame.K_r])
            frame.shield = bool(pressed[pygame.K_l])
            frame.magic_a = frame.magic_modifier and frame.jump
            frame.magic_b = frame.magic_modifier and frame.use_item
            frame.magic_x = frame.magic_modifier and frame.attack
            frame.magic_y = frame.magic_modifier and frame.heavy
            if frame.magic_modifier:
                frame.attack = frame.heavy = frame.jump = frame.use_item = False
            frame.accept = pygame.K_RETURN in keys
            frame.back = pygame.K_ESCAPE in keys or pygame.K_BACKSPACE in keys
            frame.start = pygame.K_p in keys
            return frame
        stick = self.value(spec.device, "LS", None)
        try:
            sx, sy = float(stick.x), float(stick.y)
        except Exception:
            sx = sy = 0.0
        dx = float(bool(self.value(spec.device, "DPAD_RIGHT"))) - float(bool(self.value(spec.device, "DPAD_LEFT")))
        dy = float(bool(self.value(spec.device, "DPAD_DOWN"))) - float(bool(self.value(spec.device, "DPAD_UP")))
        frame.axis_x = dx if dx else (sx if abs(sx) > 0.18 else 0.0)
        frame.axis_y = dy if dy else (-sy if abs(sy) > 0.18 else 0.0)
        button_a = self.edge(spec.key, "game_a", bool(self.value(spec.device, "A")))
        button_b = self.edge(spec.key, "game_b", bool(self.value(spec.device, "B")))
        button_x = self.edge(spec.key, "game_x", bool(self.value(spec.device, "X")))
        button_y = self.edge(spec.key, "game_y", bool(self.value(spec.device, "Y")))
        frame.magic_modifier = float(self.value(spec.device, "RT", 0.0)) > .28
        frame.shield = float(self.value(spec.device, "LT", 0.0)) > .28
        frame.magic_a = frame.magic_modifier and button_a
        frame.magic_b = frame.magic_modifier and button_b
        frame.magic_x = frame.magic_modifier and button_x
        frame.magic_y = frame.magic_modifier and button_y
        frame.jump = button_a and not frame.magic_modifier
        frame.use_item = button_b and not frame.magic_modifier
        frame.attack = button_x and not frame.magic_modifier
        frame.heavy = button_y and not frame.magic_modifier
        frame.item_left = self.edge(spec.key, "game_lb", bool(self.value(spec.device, "LB")))
        frame.item_right = self.edge(spec.key, "game_rb", bool(self.value(spec.device, "RB")))
        frame.accept = button_x
        frame.back = False
        frame.start = self.edge(spec.key, "game_start", bool(self.value(spec.device, "START")))
        return frame


class Music:
    FALLBACKS = {
        "arena": "map", "blacksmith": "map", "frog": "map", "home_castle": "map",
        "castle_keep": "home_castle", "barbarian_war": "home_castle",
        "barbarian_boss": "barbarian_war", "forest_entrance": "map",
        "thieves_forest": "forest_entrance", "thieves_store": "forest_entrance",
        "abandoned_mill": "forest_entrance", "rapids_ride": "forest_entrance",
        "cat_fish": "rapids_ride", "tall_grass_field": "forest_entrance",
        "pipistrellos_cave": "tall_grass_field",
        "cyclops_gate": "cyclops_cave", "cyclops_fortress": "cyclops_cave",
        "lava_world": "cyclops_cave", "lava_store": "thieves_store",
        "wizard_castle_takeoff": "map", "wizard_castle_interior": "map",
        "wizard_castle_final": "map",
    }

    def __init__(self, enabled, volume=.75):
        self.enabled = enabled
        self.current = None
        self.volume = max(0.0, min(1.0, float(volume)))
        if enabled:
            try:
                if not pygame.mixer.get_init():
                    pygame.mixer.init()
                pygame.mixer.music.set_volume(self.volume)
            except pygame.error:
                self.enabled = False

    def set_volume(self, volume):
        self.volume = max(0.0, min(1.0, float(volume)))
        if self.enabled:
            try:
                pygame.mixer.music.set_volume(self.volume)
            except pygame.error:
                pass
        return self.volume

    @staticmethod
    def find(name):
        for suffix in (".mp3", ".ogg", ".wav"):
            path = APP_DIR / "audio" / f"{name}{suffix}"
            if path.is_file():
                return path
        return None

    def play(self, name):
        if not self.enabled or name == self.current:
            return
        path = self.find(name) or self.find(self.FALLBACKS.get(name, ""))
        try:
            pygame.mixer.music.fadeout(250)
            if path:
                pygame.mixer.music.load(str(path))
                pygame.mixer.music.play(-1, fade_ms=450)
            else:
                pygame.mixer.music.stop()
            self.current = name
        except (pygame.error, OSError):
            self.current = name

    def stop(self):
        if self.enabled:
            try:
                pygame.mixer.music.stop()
            except pygame.error:
                pass


class Carousel:
    EXTENSIONS = {".png", ".jpg", ".jpeg", ".webp", ".bmp"}

    def __init__(self):
        self.images = []
        self.index = 0
        folder = APP_DIR / "pictures" / "main_menu"
        paths = list(sorted(folder.glob("*"))) if folder.is_dir() else []
        generated_hall = APP_DIR / "assets" / "environments" / "home_castle_great_hall_v3.png"
        if generated_hall.is_file():
            paths.append(generated_hall)
        for path in paths:
            if path.suffix.lower() not in self.EXTENSIONS:
                continue
            try:
                self.images.append(self.cover(pygame.image.load(str(path)).convert()))
            except (pygame.error, OSError):
                pass

    @staticmethod
    def cover(image):
        width, height = image.get_size()
        factor = max(WIDTH / max(1, width), HEIGHT / max(1, height))
        size = (int(width * factor), int(height * factor))
        scaled = pygame.transform.smoothscale(image, size)
        return scaled.subsurface(((size[0] - WIDTH) // 2, (size[1] - HEIGHT) // 2, WIDTH, HEIGHT)).copy()

    def draw(self, target, elapsed):
        if not self.images:
            return False
        cycle, hold = 7.7, 6.5
        self.index = int(elapsed // cycle) % len(self.images)
        phase = elapsed % cycle
        target.blit(self.images[self.index], (0, 0))
        if len(self.images) > 1 and phase > hold:
            next_image = self.images[(self.index + 1) % len(self.images)]
            next_image.set_alpha(int(255 * (phase - hold) / (cycle - hold)))
            target.blit(next_image, (0, 0))
            next_image.set_alpha(255)
        return True


class Textures:
    PARTS = ("head", "body", "arm_left", "arm_right", "leg_left", "leg_right")
    PART_FILENAMES = {
        "head": ("head.png",),
        "body": ("body.png",),
        "arm_left": ("arm_left.png", "left_arm.png"),
        "arm_right": ("arm_right.png", "right_arm.png"),
        "leg_left": ("leg_left.png", "left_leg.png"),
        "leg_right": ("leg_right.png", "right_leg.png"),
    }
    FOLDER_ALIASES = {
        "electric": ("electric", "electricity", "ember"),
        "ice": ("ice", "tide"),
        "fire": ("fire", "storm"),
        "green": ("green", "grove"),
    }
    
    # Define exact target resolutions for specific parts
    EXACT_RESOLUTIONS = {
        "arm_left": (62, 104),
        "arm_right": (62, 104),
        "body": (120, 140),
        "head": (156, 140),
        "leg_left": (64, 105),
        "leg_right": (64, 105),
    }

    def __init__(self):
        self.parts = {}
        self.sprites = {}
        self.weapons = {}
        self.pets = {}
        self.mount_parts = {}
        self.boss_parts = {}
        self.environments = {}
        self.magic = {}
        self.items = {}
        self.story = {}
        self.level_images = {}
        self.art = {}
        self.background_paths = {}
        self.background_cache = {}
        self.rigs = {}
        self.cache = {}

        for knight in ALL_CHARACTERS:
            folders = tuple(dict.fromkeys((knight.texture_dir,) + self.FOLDER_ALIASES.get(knight.key, (knight.key,))))
            for part in self.PARTS:
                loaded = False
                for folder_name in folders:
                    folder = APP_DIR / "assets" / "characters" / folder_name
                    for filename in self.PART_FILENAMES[part]:
                        path = folder / filename
                        if not path.is_file():
                            continue
                        try:
                            image = pygame.image.load(str(path)).convert_alpha()
                            target_size = self.EXACT_RESOLUTIONS[part]
                            if image.get_size() != target_size:
                                image = pygame.transform.smoothscale(image, target_size)
                            self.parts[(knight.key, part)] = image
                            loaded = True
                            break
                        except (pygame.error, OSError):
                            continue
                    if loaded:
                        break

            for sprite_key in folders:
                try:
                    self.sprites[knight.key] = pygame.image.load(
                        str(APP_DIR / "assets" / "generated" / "cast" / f"{sprite_key}.png")
                    ).convert_alpha()
                    break
                except (pygame.error, OSError):
                    continue

        for key in WEAPON_NAMES:
            try:
                self.weapons[key] = pygame.image.load(
                    str(APP_DIR / "assets" / "weapons" / f"{key}.png")
                ).convert_alpha()
            except (pygame.error, OSError):
                pass

        for key in PET_NAMES:
            try:
                self.pets[key] = pygame.image.load(
                    str(APP_DIR / "assets" / "pets" / f"{key}.png")
                ).convert_alpha()
            except (pygame.error, OSError):
                pass

        for mount_id, definition in MOUNT_DATA.items():
            texture_dir = str(definition.get("texture_dir", mount_id))
            parts = definition.get("parts", {})
            if not isinstance(parts, dict):
                continue
            for part in parts:
                path = APP_DIR / "assets" / "mounts" / texture_dir / f"{part}.png"
                try:
                    image = pygame.image.load(str(path)).convert_alpha()
                    bounds = image.get_bounding_rect(min_alpha=1)
                    if bounds.width and bounds.height:
                        image = image.subsurface(bounds).copy()
                    self.mount_parts[(mount_id, part)] = image
                except (pygame.error, OSError):
                    pass

        for key, knight in CHARACTERS_BY_KEY.items():
            for ability in ("projectile", "splash", "jump", "infusion"):
                try:
                    self.magic[(key, ability)] = pygame.image.load(
                        str(APP_DIR / "assets" / "magic" / knight.magic_texture_dir / f"{ability}.png")
                    ).convert_alpha()
                except (pygame.error, OSError):
                    pass
        for key in ITEM_NAMES:
            try:
                self.items[key] = pygame.image.load(
                    str(APP_DIR / "assets" / "items" / f"{key}.png")
                ).convert_alpha()
            except (pygame.error, OSError):
                pass
        for path in (APP_DIR / "assets" / "story").glob("*.png"):
            try:
                self.story[path.stem] = pygame.image.load(str(path)).convert_alpha()
            except (pygame.error, OSError):
                pass

        # JSON rigs may deliberately live beside the normal character art so
        # every editable texture for that character is kept in one folder.
        character_root = APP_DIR / "assets" / "characters"
        for character_folder in character_root.glob("*"):
            if not character_folder.is_dir():
                continue
            for path in character_folder.glob("*.png"):
                try:
                    self.art[f"characters/{character_folder.name}/{path.stem}"] = pygame.image.load(
                        str(path)
                    ).convert_alpha()
                except (pygame.error, OSError):
                    pass

        for level_folder in (APP_DIR / "assets" / "levels").glob("*"):
            if not level_folder.is_dir():
                continue
            for path in level_folder.glob("*.png"):
                try:
                    self.level_images[(level_folder.name, path.stem)] = pygame.image.load(str(path)).convert_alpha()
                except (pygame.error, OSError):
                    pass

        art_root = APP_DIR / "assets" / "art"
        for path in art_root.rglob("*.png"):
            try:
                key = path.relative_to(art_root).with_suffix("").as_posix()
                if key.startswith("backgrounds/"):
                    # Full-screen source backdrops are intentionally lazy.
                    # Loading every stage at boot would consume hundreds of
                    # megabytes even though only one style is visible.
                    self.background_paths[key.removeprefix("backgrounds/")] = path
                    continue
                image = pygame.image.load(str(path)).convert_alpha()
                if key.startswith("rigs/"):
                    # Rig source files keep their pivot at the canvas center.
                    # Collapse unused transparent padding into the smallest
                    # pivot-centered square before animation transforms; this
                    # makes limb animation fast without changing its pivot.
                    bounds = image.get_bounding_rect(min_alpha=1)
                    if bounds.width and bounds.height:
                        pivot_x, pivot_y = image.get_width() // 2, image.get_height() // 2
                        radius = max(
                            pivot_x - bounds.left, bounds.right - pivot_x,
                            pivot_y - bounds.top, bounds.bottom - pivot_y,
                        ) + 3
                        centered = pygame.Surface((radius * 2, radius * 2), pygame.SRCALPHA)
                        centered.blit(image, (radius - pivot_x, radius - pivot_y))
                        image = centered
                self.art[key] = image
            except (pygame.error, OSError):
                pass
        for rig_path in (art_root / "rigs").glob("*/animation.json"):
            try:
                rig = json.loads(rig_path.read_text(encoding="utf-8"))
                rig_id = str(rig.get("id", rig_path.parent.name))
                rig["asset_prefix"] = str(
                    rig.get("asset_prefix", f"rigs/{rig_path.parent.name}/parts")
                )
                self.rigs[rig_id] = rig
            except (OSError, ValueError, TypeError):
                pass

        for boss_folder in (APP_DIR / "assets" / "bosses").glob("*"):
            if not boss_folder.is_dir():
                continue
            for path in boss_folder.glob("*.png"):
                try:
                    image = pygame.image.load(str(path)).convert_alpha()
                    bounds = image.get_bounding_rect(min_alpha=1)
                    if bounds.width and bounds.height:
                        image = image.subsurface(bounds).copy()
                    self.boss_parts[(boss_folder.name, path.stem)] = image
                except (pygame.error, OSError):
                    pass

        for path in (APP_DIR / "assets" / "environments").glob("*.png"):
            try:
                self.environments[path.stem] = pygame.image.load(str(path)).convert()
            except (pygame.error, OSError):
                pass

    def get(self, knight, part, scale, facing=1, angle=0):
        source = self.parts.get((knight.key, part))
        if source is None:
            return None
        key = (knight.key, part, int(scale * 100), 1 if facing >= 0 else -1, int(angle / 3) * 3)
        if key not in self.cache:
            image = pygame.transform.flip(source, True, False) if facing < 0 else source
            self.cache[key] = pygame.transform.rotozoom(image, -key[-1], key[2] / 100)
        return self.cache[key]

    def sprite(self, knight, scale, facing=1, attacking=False):
        source = self.sprites.get(knight.key)
        if source is None:
            return None
        target_height = max(24, int(232 * scale))
        factor = target_height / max(1, source.get_height())
        angle = -6 * facing if attacking else 0
        key = ("sprite", knight.key, target_height, 1 if facing >= 0 else -1, angle)
        if key not in self.cache:
            image = pygame.transform.flip(source, True, False) if facing < 0 else source
            self.cache[key] = pygame.transform.rotozoom(image, -angle, factor)
        return self.cache[key]

    def item(self, collection, key, target_height, facing=1, angle=0):
        sources = {"pets": self.pets, "weapons": self.weapons, "items": self.items}
        source = sources.get(collection, self.weapons).get(key)
        if source is None:
            return None
        cache_key = (collection, key, int(target_height), 1 if facing >= 0 else -1, int(angle / 2) * 2)
        if cache_key not in self.cache:
            factor = target_height / max(1, source.get_height())
            image = pygame.transform.flip(source, True, False) if facing < 0 else source
            self.cache[cache_key] = pygame.transform.rotozoom(image, -cache_key[-1], factor)
        return self.cache[cache_key]

    def mount_part(self, mount_id, part, target_height, facing=1, angle=0):
        source = self.mount_parts.get((mount_id, part))
        if source is None:
            return None
        cache_key = (
            "mount",
            mount_id,
            part,
            int(target_height),
            1 if facing >= 0 else -1,
            int(angle / 2) * 2,
        )
        if cache_key not in self.cache:
            factor = max(1, target_height) / max(1, source.get_height())
            image = pygame.transform.flip(source, True, False) if facing < 0 else source
            self.cache[cache_key] = pygame.transform.rotozoom(image, -cache_key[-1], factor)
        return self.cache[cache_key]

    def effect(self, collection, key, target_height, facing=1, angle=0):
        source = self.magic.get(key) if collection == "magic" else self.story.get(key)
        if source is None:
            return None
        cache_key = (collection, key, int(target_height), 1 if facing >= 0 else -1, int(angle / 2) * 2)
        if cache_key not in self.cache:
            factor = target_height / max(1, source.get_height())
            image = pygame.transform.flip(source, True, False) if facing < 0 else source
            self.cache[cache_key] = pygame.transform.rotozoom(image, -cache_key[-1], factor)
        return self.cache[cache_key]

    def level_image(self, level_id, key, target_height, facing=1, angle=0):
        source = self.level_images.get((str(level_id), str(key)))
        if source is None:
            return None
        cache_key = (
            "level_image", str(level_id), str(key), int(target_height),
            1 if facing >= 0 else -1, int(angle / 2) * 2,
        )
        if cache_key not in self.cache:
            factor = max(1, int(target_height)) / max(1, source.get_height())
            image = pygame.transform.flip(source, True, False) if facing < 0 else source
            self.cache[cache_key] = pygame.transform.rotozoom(image, -cache_key[-1], factor)
        return self.cache[cache_key]

    def art_image(self, key, target_height, facing=1, angle=0, target_width=None):
        source = self.art.get(str(key).replace("\\", "/"))
        if source is None:
            return None
        height = max(1, int(target_height))
        width = (
            max(1, int(target_width))
            if target_width is not None
            else max(1, int(source.get_width() * height / max(1, source.get_height())))
        )
        cache_key = (
            "art", str(key), width, height,
            1 if facing >= 0 else -1, int(angle / 2) * 2,
        )
        if cache_key not in self.cache:
            image = pygame.transform.smoothscale(source, (width, height))
            if facing < 0:
                image = pygame.transform.flip(image, True, False)
            if cache_key[-1]:
                image = pygame.transform.rotate(image, -cache_key[-1])
            self.cache[cache_key] = image
        return self.cache[cache_key]

    def background_image(self, style, target_size):
        """Load and scale one editable source backdrop with a tiny LRU cache."""
        size = (max(1, int(target_size[0])), max(1, int(target_size[1])))
        cache_key = (str(style), size)
        cached = self.background_cache.get(cache_key)
        if cached is not None:
            self.background_cache.pop(cache_key, None)
            self.background_cache[cache_key] = cached
            return cached
        path = self.background_paths.get(str(style))
        if path is None:
            return None
        try:
            source = pygame.image.load(str(path)).convert()
        except (pygame.error, OSError):
            return None
        image = pygame.transform.smoothscale(source, size)
        self.background_cache[cache_key] = image
        while len(self.background_cache) > 4:
            self.background_cache.pop(next(iter(self.background_cache)))
        return image

    def boss_part(self, boss_id, part, target_height, facing=1, angle=0):
        source = self.boss_parts.get((str(boss_id), str(part)))
        if source is None:
            return None
        cache_key = (
            "boss_part", str(boss_id), str(part), int(target_height),
            1 if facing >= 0 else -1, int(angle / 2) * 2,
        )
        if cache_key not in self.cache:
            factor = max(1, int(target_height)) / max(1, source.get_height())
            image = pygame.transform.flip(source, True, False) if facing < 0 else source
            self.cache[cache_key] = pygame.transform.rotozoom(image, -cache_key[-1], factor)
        return self.cache[cache_key]

    def animated_deer(self, target_height, facing=1, run_phase=0.0):
        """Return a cached deer frame with opposing hind/front leg motion."""
        source = self.story.get("wildlife_deer")
        if source is None:
            return None
        frame_count = 8
        frame = int((float(run_phase) % math.tau) / math.tau * frame_count) % frame_count
        cache_key = ("wildlife_deer_gait", int(target_height), 1 if facing >= 0 else -1, frame)
        if cache_key in self.cache:
            return self.cache[cache_key]

        factor = max(1, int(target_height)) / max(1, source.get_height())
        width = max(1, int(source.get_width() * factor))
        height = max(1, int(source.get_height() * factor))
        base = pygame.transform.smoothscale(source, (width, height))
        padding = max(4, int(width * .045))
        animated = pygame.Surface((width + padding * 2, height), pygame.SRCALPHA)
        # The source sprite's belly ends around 69% of its height.  Starting
        # below it keeps the torso intact and limits the gait to shin/hoof
        # motion.  A small overlap keeps both leg roots visibly attached.
        leg_top = int(height * .70)
        split_x = int(width * .50)
        root_overlap = max(2, int(height * .018))
        animated.blit(base, (padding, 0), (0, 0, width, min(height, leg_top + root_overlap)))
        swing = math.sin(frame * math.tau / frame_count)
        for row in range(leg_top, height):
            amount = (row - leg_top) / max(1, height - leg_top - 1)
            offset = int(swing * padding * amount)
            animated.blit(base, (padding + offset, row), (0, row, split_x, 1))
            animated.blit(
                base,
                (padding + split_x - offset, row),
                (split_x, row, width - split_x, 1),
            )
        if facing < 0:
            animated = pygame.transform.flip(animated, True, False)
        self.cache[cache_key] = animated
        return animated


class Player:
    def __init__(self, spec, x, y):
        self.spec, self.knight, self.slot = spec, spec.knight, spec.slot
        self.x, self.y, self.facing = float(x), float(y), 1
        self.attack_time = self.walk_time = 0.0
        self.attack_kind = "light"
        self.attributes = {name: 0 for name in STAT_NAMES}
        self.level = 1
        self.stat_points = 0
        self.max_health = self.knight.base_health
        self.health, self.score, self.hit_used = self.max_health, 0, False
        self.max_magic = float(self.knight.max_mana)
        self.magic_energy = self.max_magic
        self.magic_flash = 0.0
        self.infusion_time = 0.0
        self.infusion_ability = None
        self.sandwich_time = 0.0
        self.held_enemy = None
        self.mount = None
        self.pet_food_timer = 6.0
        self.jump_z = self.jump_velocity = 0.0
        self.shielding = False
        self.selected_item = "health_potion"
        self.items = {key: 0 for key in ITEM_ORDER}
        self.pet = None
        self.weapon = "rusty_sword"
        self.weapon_modifiers = {name: 0 for name in STAT_NAMES}
        self.dead = False
        self.revive_hits = 0
        self.pet_x, self.pet_y = float(x - 72), float(y - 30)
        self.knockback_time = 0.0
        self.knockback_vx = 0.0
        self.buried_hits = 0
        self.buried_last_direction = 0
        self.gold_earned = 0
        self.xp_earned = 0

    def update(self, frame, dt, bounds):
        if self.dead:
            return
        if self.buried_hits:
            direction = 1 if frame.axis_x > .45 else (-1 if frame.axis_x < -.45 else 0)
            if direction and direction != self.buried_last_direction:
                self.buried_hits += 1
                self.buried_last_direction = direction
            if self.buried_hits >= 8:
                self.buried_hits = 0
                self.buried_last_direction = 0
                self.jump_velocity = 360
            else:
                return
        if self.knockback_time > 0:
            self.knockback_time = max(0.0, self.knockback_time - dt)
            self.x = max(bounds[0], min(bounds[1], self.x + self.knockback_vx * dt))
            self.knockback_vx *= max(0.0, 1.0 - dt * 3.7)
        self.shielding = frame.shield and self.jump_z <= 1
        agility = self.stat("agility")
        move_scale = 1.0 + agility * .025
        if self.shielding:
            move_scale *= .42
        length = math.hypot(frame.axis_x, frame.axis_y)
        dx, dy = frame.axis_x, frame.axis_y
        if length > 1:
            dx, dy = dx / length, dy / length
        self.x = max(bounds[0], min(bounds[1], self.x + dx * 275 * move_scale * dt))
        self.y = max(bounds[2], min(bounds[3], self.y + dy * 198 * move_scale * dt))
        if abs(dx) > 0.08:
            self.facing = 1 if dx > 0 else -1
        if length > 0.08:
            self.walk_time += dt * 9
        if frame.jump and self.jump_z <= 0:
            self.jump_velocity = 560.0
        self.jump_velocity -= 1300 * dt
        self.jump_z = max(0.0, self.jump_z + self.jump_velocity * dt)
        if self.jump_z <= 0:
            self.jump_velocity = 0.0
        if frame.attack and self.attack_time <= 0 and not self.shielding:
            self.attack_kind, self.attack_time, self.hit_used = "light", 0.31, False
        elif frame.heavy and self.attack_time <= 0 and not self.shielding:
            self.attack_kind, self.attack_time, self.hit_used = "heavy", 0.48, False
        self.attack_time = max(0.0, self.attack_time - dt)
        self.magic_energy = min(self.max_magic, self.magic_energy + dt * (8 + self.stat("magic") * .45))
        self.magic_flash = max(0.0, self.magic_flash - dt)
        self.infusion_time = max(0.0, self.infusion_time - dt)
        if self.infusion_time <= 0:
            self.infusion_ability = None
        self.sandwich_time = max(0.0, self.sandwich_time - dt)

    def can_hit(self, x, y):
        forward = (x - self.x) * self.facing
        size = 2.0 if self.sandwich_time > 0 else 1.0
        if self.attack_kind == "heavy":
            active, reach = 0.13 < self.attack_time < 0.37, 128 * size
        else:
            active, reach = 0.08 < self.attack_time < 0.24, 108 * size
        return active and not self.hit_used and -10 * size < forward < reach and abs(y - self.y) < 74 * size

    def attack_damage(self):
        base = 2 if self.attack_kind == "heavy" else 1
        return base + self.stat("strength") // 3 + (1 if self.infusion_time > 0 else 0)

    def stat(self, name):
        pet_bonus = 2 if self.pet == "spiny" and name == "defense" else 0
        return max(0, int(self.attributes.get(name, 0)) + int(self.weapon_modifiers.get(name, 0)) + pet_bonus)


class Projectile:
    def __init__(self, owner, x, y, vx, damage, kind, texture_key, lifetime=1.6, ability=None):
        self.owner = owner
        self.x, self.y, self.vx = float(x), float(y), float(vx)
        self.damage, self.kind, self.texture_key = int(damage), kind, texture_key
        self.lifetime, self.hit = float(lifetime), set()
        self.ability = dict(ability or {})

    def update(self, dt):
        self.x += self.vx * dt
        self.lifetime -= dt


class EnemyArrow:
    def __init__(self, x, y, target_x, target_y, damage=6, kind="arrow"):
        dx, dy = target_x - x, target_y - y
        distance = max(1.0, math.hypot(dx, dy))
        speed = 430.0
        self.x, self.y = float(x), float(y)
        self.vx, self.vy = dx / distance * speed, dy / distance * speed
        self.damage, self.kind, self.lifetime = int(damage), kind, 2.4

    def update(self, dt):
        self.x += self.vx * dt
        self.y += self.vy * dt
        self.lifetime -= dt


class FallingBomb:
    def __init__(self, x, ground_y, delay=1.15, kind="bomb"):
        self.x, self.ground_y = float(x), float(ground_y)
        self.y = float(ground_y - 520)
        self.timer, self.duration, self.exploded = float(delay), float(delay), False
        self.kind = str(kind)

    def update(self, dt):
        self.timer = max(0.0, self.timer - dt)
        progress = 1.0 - self.timer / max(.01, self.duration)
        self.y = self.ground_y - 520 * (1.0 - progress * progress)
        if self.timer <= 0 and not self.exploded:
            self.exploded = True
            return True
        return False


class RollingBoulder:
    """A mountain boulder that rolls diagonally toward its marked impact point."""

    def __init__(self, x, ground_y, delay=.95, source_x=None):
        self.x, self.ground_y = float(x), float(ground_y)
        self.source_x = float(source_x if source_x is not None else x + 420)
        self.draw_x = self.source_x
        self.y = float(ground_y - 290)
        self.timer, self.duration, self.exploded = float(delay), float(delay), False
        self.kind = "boulder"
        self.rotation = 0.0

    def update(self, dt):
        self.timer = max(0.0, self.timer - dt)
        progress = 1.0 - self.timer / max(.01, self.duration)
        eased = progress * progress * (3.0 - 2.0 * progress)
        self.draw_x = self.source_x + (self.x - self.source_x) * eased
        self.y = self.ground_y - 290 * (1.0 - eased)
        self.rotation = progress * math.tau * 2.4
        if self.timer <= 0 and not self.exploded:
            self.exploded = True
            return True
        return False


class Ally:
    def __init__(self, x, y, pinned=False, name="GRAY KNIGHT", character_key="royal_guard"):
        self.x, self.y = float(x), float(y)
        self.pinned, self.name = bool(pinned), str(name)
        self.character_key = str(character_key)
        self.facing, self.cooldown, self.walk_time = 1, 0.0, 0.0

    def update(self, enemies, dt):
        if self.pinned or not enemies:
            return None
        target = min(enemies, key=lambda enemy: (enemy.x - self.x) ** 2 + (enemy.y - self.y) ** 2)
        dx, dy = target.x - self.x, target.y - self.y
        distance = max(1.0, math.hypot(dx, dy))
        self.facing = 1 if dx >= 0 else -1
        if distance > 70:
            self.x += dx / distance * 112 * dt
            self.y += dy / distance * 82 * dt
            self.walk_time += dt * 8
        self.cooldown = max(0.0, self.cooldown - dt)
        if distance <= 82 and self.cooldown <= 0:
            self.cooldown = .58
            target.health -= 1
            return target
        return None


class WarBoss:
    def __init__(self, kind, x, y, health):
        self.kind, self.x, self.y = str(kind), float(x), float(y)
        self.max_health = self.health = int(health)
        self.time = 0.0
        self.cooldown = 1.0
        self.event_marks = set()
        self.open = False
        self.facing = -1
        self.dead_time = 0.0

    @property
    def dead(self):
        return self.health <= 0

    def hit_multiplier(self):
        if self.kind == "siege_machine" and self.open:
            return 2
        if self.kind == "cat_fish" and self.open:
            return 3
        if self.kind == "wedding_guard" and self.open:
            return 0
        if self.kind == "ice_king" and not self.open:
            return 0
        return 1


class MagicEffect:
    def __init__(self, owner, x, y, kind, duration=.55, radius=140):
        self.owner, self.x, self.y, self.kind = owner, float(x), float(y), kind
        self.duration = self.remaining = float(duration)
        self.radius = float(radius)


class LightningEffect:
    def __init__(self, owner, kind, x, y, damage, ability, x2=None, duration=1.0, radius=110):
        self.owner, self.kind = owner, str(kind)
        self.facing = 1 if owner.facing >= 0 else -1
        self.x, self.y = float(x), float(y)
        self.x2 = float(x if x2 is None else x2)
        self.damage, self.ability = int(damage), dict(ability)
        self.duration = self.remaining = float(duration)
        self.radius = float(radius)
        self.hit = set()
        self.boss_hit = False


class Mount:
    def __init__(self, mount_id, x, y):
        definition = MOUNT_DATA[mount_id]
        self.key = str(mount_id)
        self.definition = definition
        self.x, self.y = float(x), float(y)
        self.facing = -1
        self.rider = None
        self.attack_time = 0.0
        self.cooldown = 0.0
        self.walk_time = 0.0
        self.remount_delay = 0.0

    @property
    def seat_height(self):
        return float(self.definition.get("seat_height", 100))

    @property
    def speed(self):
        return float(self.definition.get("speed", 280))

    def ability(self, button):
        return dict(self.definition.get("abilities", {}).get(button, {}))


class Enemy:
    def __init__(self, x, y, seed, enemy_type="barbarian"):
        health = {
            "thief": 5, "guard_beater": 7, "buff_barbarian": 15,
            "buff_thief": 18, "tiny_thief": 3, "troll": 7,
            "sheep_knight": 8, "buff_sheep_knight": 19,
            "black_slime": 7,
            "bee": 4, "beekeeper": 10,
            "conehead": 9, "buff_conehead": 22,
            "elite_conehead": 30, "fire_demon": 24, "skeleton": 11,
            "fencer": 12, "industrialist": 15, "buff_industrialist": 34,
            "pirate": 10,
            "scarab": 24, "chain_guard": 15, "buff_chain_guard": 34,
            "saracen": 10, "buff_saracen": 28, "saracen_archer": 8,
            "alien_hominid": 5,
            "snakey": 13, "peasant": 11,
            "buff_skeleton": 27, "buff_peasant": 30,
            "fishman": 16,
            "stoveface": 18, "buff_stoveface": 42,
            "ice_thief": 11, "ice_thief_snowball": 11, "ice_thief_archer": 12,
            "cult_minion": 26,
        }.get(enemy_type, 6)
        self.x, self.y, self.health = float(x), float(y), health
        self.max_health = health
        self.speed, self.cooldown = 68 + seed % 35, 0.0
        if enemy_type == "elite_conehead":
            self.speed *= 1.28
        elif enemy_type == "fire_demon":
            self.speed *= 1.12
        elif enemy_type == "fencer":
            self.speed *= 1.22
        elif enemy_type == "buff_industrialist":
            self.speed *= .82
        elif enemy_type in {"buff_saracen", "buff_chain_guard"}:
            self.speed *= .86
        elif enemy_type in {"buff_skeleton", "buff_peasant"}:
            self.speed *= .82
        elif enemy_type == "buff_stoveface":
            self.speed *= .78
        elif enemy_type in {"ice_thief", "ice_thief_snowball", "ice_thief_archer"}:
            self.speed *= 1.18
        elif enemy_type == "cult_minion":
            self.speed *= 1.08
        self.enemy_type = enemy_type
        self.facing = -1
        self.entry_kind = None
        self.entry_time = self.entry_duration = 0.0
        self.sleeping = False
        self.group = None
        self.knockback_time = 0.0
        self.knockback_vx = 0.0
        self.carried_by = None
        self.mount = None
        self.throw_time = self.throw_duration = 0.0
        self.statuses = {}
        self.latched_to = None
        self.special_cooldown = 1.2 + (seed % 9) * .23
        self.drop_weapon = None
        self.drop_item = None
        self.scarab_roll_time = 0.0
        self.scarab_roll_cooldown = 1.2 + (seed % 5) * .22
        self.scarab_roll_direction = 1
        self.scarab_wing_time = 0.0
        self.fish_special_count = 0
        self.fish_leap_from = (self.x, self.y)
        self.fish_leap_target = None
        self.fish_leap_hit = False

    def status_time(self, status):
        return max(0.0, float(self.statuses.get(status, {}).get("remaining", 0.0)))

    def immobilized(self):
        return self.status_time("freeze") > 0 or self.status_time("stun") > 0

    def enter_from(self, kind, duration=1.5):
        self.entry_kind = kind
        self.entry_time = self.entry_duration = float(duration)
        return self

    def display_y(self):
        if self.throw_time > 0:
            progress = 1.0 - self.throw_time / max(.01, self.throw_duration)
            return self.y - math.sin(progress * math.pi) * 145
        if self.entry_kind == "ladder" and self.entry_time > 0:
            # Only a short climb from behind the upper wall edge is visible.
            # Enemies never travel from the bottom of the screen.
            return self.y + 145 * (self.entry_time / max(.01, self.entry_duration))
        if self.entry_kind == "crate" and self.entry_time > 0:
            return self.y + 95 * (self.entry_time / max(.01, self.entry_duration))
        if self.entry_kind == "swing" and self.entry_time > 0:
            progress = 1.0 - self.entry_time / max(.01, self.entry_duration)
            return self.y - 320 * math.sin(progress * math.pi)
        if self.entry_kind in {"wake", "late_wake"} and self.entry_time > 0:
            progress = 1.0 - self.entry_time / max(.01, self.entry_duration)
            return self.y + (1.0 - progress) * 24
        if self.entry_kind == "slime_drop" and self.entry_time > 0:
            return self.y - 440 * (self.entry_time / max(.01, self.entry_duration))
        if self.entry_kind in {"bee_drop", "hall_drop", "sky_fall"} and self.entry_time > 0:
            return self.y - 470 * (self.entry_time / max(.01, self.entry_duration))
        if self.entry_kind == "lava_rise" and self.entry_time > 0:
            return self.y + 175 * (self.entry_time / max(.01, self.entry_duration))
        if self.entry_kind == "water_rise" and self.entry_time > 0:
            return self.y + 125 * (self.entry_time / max(.01, self.entry_duration))
        if self.entry_kind == "ice_rise" and self.entry_time > 0:
            return self.y + 115 * (self.entry_time / max(.01, self.entry_duration))
        if self.entry_kind == "ladder_down" and self.entry_time > 0:
            return self.y - 330 * (self.entry_time / max(.01, self.entry_duration))
        if self.entry_kind == "fish_leap" and self.entry_time > 0:
            progress = 1.0 - self.entry_time / max(.01, self.entry_duration)
            return self.y - math.sin(progress * math.pi) * 245
        if self.entry_kind == "stone_wake" and self.entry_time > 0:
            return self.y + 28 * (self.entry_time / max(.01, self.entry_duration))
        if self.entry_kind == "triangle_birth" and self.entry_time > 0:
            # Cult minions are expelled beneath the flying triangle and drop
            # the last short distance to the arena floor.
            return self.y - 155 * (self.entry_time / max(.01, self.entry_duration))
        if self.entry_kind == "cart_jump" and self.entry_time > 0:
            progress = 1.0 - self.entry_time / max(.01, self.entry_duration)
            return self.y - math.sin(progress * math.pi) * 185
        if self.entry_kind in {"window", "tower_door"} and self.entry_time > 0:
            return self.y - 85 * (self.entry_time / max(.01, self.entry_duration))
        return self.y

    def update(self, players, dt, damage_callback=None):
        if self.carried_by is not None or self.latched_to is not None:
            return None
        if self.mount is not None:
            return None
        if self.immobilized():
            self.cooldown = max(0.0, self.cooldown - dt)
            return None
        if self.knockback_time > 0:
            self.knockback_time = max(0.0, self.knockback_time - dt)
            self.throw_time = max(0.0, self.throw_time - dt)
            self.x += self.knockback_vx * dt
            self.knockback_vx *= max(0.0, 1.0 - dt * 4)
            return None
        if self.sleeping:
            return None
        if self.entry_time > 0:
            self.entry_time = max(0.0, self.entry_time - dt)
            if self.entry_kind == "fish_leap" and self.fish_leap_target is not None:
                progress = 1.0 - self.entry_time / max(.01, self.entry_duration)
                start_x, start_y = self.fish_leap_from
                target_x, target_y = self.fish_leap_target.x, self.fish_leap_target.y
                self.x = start_x + (target_x - start_x) * progress
                self.y = start_y + (target_y - start_y) * progress
                if progress >= .72 and not self.fish_leap_hit and not self.fish_leap_target.dead:
                    self.fish_leap_hit = True
                    if damage_callback:
                        damage_callback(self.fish_leap_target, 15, self.x, force=True)
            elif self.entry_kind == "swing":
                living = [player for player in players if not player.dead]
                if living:
                    target = min(living, key=lambda p: abs(p.x - self.x))
                    self.facing = 1 if target.x > self.x else -1
                    self.cooldown = max(0.0, self.cooldown - dt)
                    if self.cooldown <= 0:
                        self.cooldown = .85
                        return target
            elif self.entry_kind == "rush_left":
                self.x -= 360 * dt
                self.facing = -1
            elif self.entry_kind == "rush_right":
                self.x += 330 * dt
                self.facing = 1
            return None
        players = [player for player in players if not player.dead]
        if not players:
            return None
        target = min(players, key=lambda p: (p.x - self.x) ** 2 + (p.y - self.y) ** 2)
        dx, dy = target.x - self.x, target.y - self.y
        if abs(dx) > 2:
            self.facing = 1 if dx > 0 else -1
        distance = max(1, math.hypot(dx, dy))
        if self.enemy_type == "scarab":
            self.scarab_roll_time = max(0.0, self.scarab_roll_time - dt)
            self.scarab_roll_cooldown = max(0.0, self.scarab_roll_cooldown - dt)
            self.scarab_wing_time += dt * (8.0 if self.scarab_roll_time <= 0 else 15.0)
            self.cooldown = max(0.0, self.cooldown - dt)
            if self.scarab_roll_time > 0:
                self.x += self.scarab_roll_direction * 390 * dt
                self.y += max(-1.0, min(1.0, dy / 90.0)) * 115 * dt
                if abs(target.x - self.x) < 68 and abs(target.y - self.y) < 72 and self.cooldown <= 0:
                    if damage_callback:
                        damage_callback(target, 14, self.x, force=True)
                    self.cooldown = .72
                return None
            if self.scarab_roll_cooldown <= 0 and distance < 430:
                self.scarab_roll_time = 1.45
                self.scarab_roll_cooldown = 3.0
                self.scarab_roll_direction = 1 if dx >= 0 else -1
                return None
            if distance > 58:
                self.x += dx / distance * self.speed * 1.2 * dt
                self.y += dy / distance * self.speed * .8 * dt
            if distance < 60 and self.cooldown <= 0:
                if damage_callback:
                    damage_callback(target, 11, self.x)
                self.cooldown = .82
            return None
        if self.enemy_type == "bee":
            hover_y = target.y - 45 + math.sin(self.x * .013 + self.cooldown * 4) * 42
            dy = hover_y - self.y
            distance = max(1, math.hypot(dx, dy))
            if distance > 48:
                self.x += dx / distance * 205 * dt
                self.y += dy / distance * 155 * dt
            self.cooldown = max(0.0, self.cooldown - dt)
            if abs(target.x - self.x) < 58 and abs(target.y - self.y) < 82 and self.cooldown <= 0:
                if damage_callback:
                    damage_callback(target, 18, self.x, force=True)
                else:
                    target.health = max(0, target.health - 18)
                self.cooldown = .68
            return None
        if self.enemy_type in {"thief", "tiny_thief", "alien_hominid", "saracen_archer", "chain_guard", "buff_chain_guard", "ice_thief_snowball", "ice_thief_archer"} and 145 < distance < 520:
            self.cooldown = max(0, self.cooldown - dt)
            if self.cooldown <= 0:
                self.cooldown = 1.15
                return target
            return None
        if distance > 50:
            self.x += dx / distance * self.speed * dt
            self.y += dy / distance * self.speed * 0.7 * dt
        self.cooldown = max(0, self.cooldown - dt)
        if distance < 55 and self.cooldown <= 0:
            melee_damage = {
                "elite_conehead": 15, "fire_demon": 14,
                "fencer": 12, "industrialist": 11, "buff_industrialist": 18,
                "saracen": 10, "buff_saracen": 17, "chain_guard": 12, "buff_chain_guard": 18,
                "stoveface": 12, "buff_stoveface": 19,
                "ice_thief": 10, "ice_thief_snowball": 10, "ice_thief_archer": 10,
                "cult_minion": 14,
            }.get(self.enemy_type, 9)
            if damage_callback:
                damage_callback(target, melee_damage, self.x)
            else:
                target.health = max(0, target.health - melee_damage)
            self.cooldown = 0.75
        return None


