        self.lava_geyser_cooldowns = {}
        self.industrial_hazard_cooldowns = {}
        self.story_effect_marks.clear()
        if runtime.level_id == "tall_grass_field":
            self.tall_arrows = []
            self.tall_arrow_timer = 0.0
            for item in self.scene_breakables:
                if str(item.get("id")) in self.tall_arrow_destroyed:
                    item["broken"] = True
                    item["health"] = 0
                    self.scene_flags.add(f"breakable:{item['id']}")
            if runtime.scene_id == "field":
                if self.tall_field_return:
                    runtime.triggered_waves.update({"sleeping_sheep", "second_sheep", "buff_runners", "post_arrow_sheep"})
                    if (runtime.level_id, "princess_handoff") in self.story_events_seen:
                        runtime.triggered_waves.add("handoff_thieves")
                if self.tall_boss_defeated:
                    self.scene_flags.add("boss_defeated")
                    self.dynamic_pets.append({"id": "rammy", "name": "Rammy", "x": 6500, "y": 520})
            elif runtime.scene_id == "boulder_cave":
                for flag in self.tall_cave_flags:
                    self.scene_flags.add(flag)
                for item in self.scene_breakables:
                    if f"breakable:{item.get('id')}" in self.tall_cave_flags:
                        item["broken"] = True
                        item["health"] = 0
        if runtime.level_id == "pipistrellos_cave":
            self.pip_poops = []
