    def draw_barbarian_war_ending(self):
        if not self.war_ending:
            return
        if self.level_runtime.level_id == "ice_castle":
            self.draw_ice_castle_ending()
            return
        if self.level_runtime.level_id == "cyclops_fortress":
            self.draw_cyclops_fortress_ending()
            return
        camera = self.level_runtime.camera_x
        props = self.level_runtime.scene.get("props", {})
        princess_x = float(props.get("rescue_princess", props.get("princesses", 1840)))
        chest_x = princess_x - 300
        chest_screen_x = chest_x - camera
        if self.war_ending == "chest":
            # The other three princesses are carried away while the reward lands.
            carry = min(1.0, self.war_ending_time / 2.2)
            for index, key in enumerate(("princess_orange", "princess_blue", "princess_green")):
                x = princess_x + 140 + index * 115 + carry * 520 - camera
                y = 450 - math.sin(carry * math.pi) * (45 + index * 20)
                self.draw_knight((x, y), .57, CHARACTERS_BY_KEY["barbarian"], 1, False, carry * 8, weapon="barbarian_axe")
                self.draw_story_character(key, (x - 12, y - 105), 125)
            drop = min(1.0, self.war_ending_time / 1.4)
            chest_y = -100 + 630 * drop * drop
            pygame.draw.rect(self.canvas, INK, (chest_screen_x - 86, chest_y - 47, 172, 94), border_radius=14)
            pygame.draw.rect(self.canvas, (128, 77, 38), (chest_screen_x - 78, chest_y - 39, 156, 78), border_radius=10)
            pygame.draw.rect(self.canvas, GOLD, (chest_screen_x - 15, chest_y - 12, 30, 38), border_radius=5)
            arrow_y = chest_y - 125 + math.sin(self.elapsed * 7) * 12
            pygame.draw.polygon(self.canvas, GREEN, [(chest_screen_x, arrow_y + 45), (chest_screen_x - 42, arrow_y), (chest_screen_x - 15, arrow_y), (chest_screen_x - 15, arrow_y - 42), (chest_screen_x + 15, arrow_y - 42), (chest_screen_x + 15, arrow_y), (chest_screen_x + 42, arrow_y)])
            self.text("BREAK THE CHEST", 17, CREAM, (int(chest_screen_x), int(chest_y + 78)), True, 3)
        elif self.war_ending == "loot":
            shrink = max(0.0, 1.0 - self.war_ending_time / 4.0)
            if shrink > .03:
                width, height = int(172 * shrink), int(94 * shrink)
                pygame.draw.rect(self.canvas, INK, (chest_screen_x - width // 2, 530 - height // 2, width, height), border_radius=max(2, int(12 * shrink)))
                pygame.draw.rect(self.canvas, (128, 77, 38), (chest_screen_x - width // 2 + 5, 530 - height // 2 + 5, max(1, width - 10), max(1, height - 10)), border_radius=max(2, int(8 * shrink)))
            for loot in self.war_loot:
                if loot["picked"]:
                    continue
                x, y = int(loot["x"] - camera), int(loot["y"])
                if loot["kind"] == "coin":
                    pygame.draw.circle(self.canvas, INK, (x, y), 12)
                    pygame.draw.circle(self.canvas, GOLD, (x, y), 9)
                elif loot["kind"] == "gold_bag":
                    pygame.draw.circle(self.canvas, INK, (x, y), 19)
                    pygame.draw.circle(self.canvas, (187, 135, 50), (x, y + 2), 15)
                    pygame.draw.line(self.canvas, GOLD, (x - 11, y - 12), (x + 11, y - 12), 5)
                else:
                    pygame.draw.polygon(self.canvas, INK, [(x, y - 19), (x + 17, y - 5), (x + 10, y + 18), (x - 10, y + 18), (x - 17, y - 5)])
                    pygame.draw.polygon(self.canvas, TEAL, [(x, y - 14), (x + 11, y - 3), (x + 7, y + 12), (x - 7, y + 12), (x - 11, y - 3)])
        elif self.war_ending in {"princess", "duel", "kiss"}:
            x = princess_x - camera
            if self.war_ending == "princess":
                pygame.draw.line(self.canvas, CREAM, (x - 48, 405), (x + 48, 405), 5)
                # Scissors icon beside the cut line.
                pygame.draw.circle(self.canvas, CREAM, (int(x + 65), 392), 10, 4)
                pygame.draw.circle(self.canvas, CREAM, (int(x + 65), 414), 10, 4)
                pygame.draw.line(self.canvas, CREAM, (x + 70, 397), (x + 96, 377), 5)
                pygame.draw.line(self.canvas, CREAM, (x + 70, 409), (x + 96, 429), 5)
                self.text("JUMP + X TO CUT HER FREE", 18, CREAM, (int(x), 300), True, 3)
            elif self.war_ending == "duel":
                self.text("LAST KNIGHT STANDING GETS THE KISS!", 21, GOLD, (640, 205), True, 3)
            else:
                self.text("TOUCH THE PRINCESS", 21, GOLD, (int(x), 300), True, 3)
                for index in range(4):
                    hx = int(x - 42 + index * 28)
                    hy = 335 + int(math.sin(self.elapsed * 4 + index) * 12)
                    pygame.draw.circle(self.canvas, RED, (hx - 5, hy), 8)
                    pygame.draw.circle(self.canvas, RED, (hx + 5, hy), 8)
                    pygame.draw.polygon(self.canvas, RED, [(hx - 13, hy + 2), (hx + 13, hy + 2), (hx, hy + 18)])
        elif self.war_ending == "results":
            shade = pygame.Surface((WIDTH, 220), pygame.SRCALPHA)
            shade.fill((7, 12, 18, 225))
            self.canvas.blit(shade, (0, 0))
            progress = min(1.0, self.war_ending_time / 2.0)
            width = WIDTH // max(1, len(self.players))
            for index, player in enumerate(self.players):
                center_x = width * index + width // 2
                self.text(f"P{player.slot} {player.knight.name.upper()}", 19, CREAM, (center_x, 32), True, 2)
                self.text(f"KILLS  {int(player.score * progress)}", 17, ORANGE, (center_x, 78), True)
                self.text(f"GOLD  {int(player.gold_earned * progress)}", 17, GOLD, (center_x, 116), True)
                self.text(f"EXPERIENCE  {int(player.xp_earned * progress)}", 17, TEAL, (center_x, 154), True)
            if progress >= 1:
                self.text("VICTORY!", 26, CREAM, (640, 198), True, 3)

    def draw_following_pet(self, player, screen_x):
        if not player.pet:
            return
        pet_screen_x = screen_x + (player.pet_x - player.x)
        pet_screen_y = self.world_screen_y(player.pet_x, player.pet_y) if self.state == "level" else player.pet_y
        pygame.draw.ellipse(self.canvas, (5, 10, 15, 90), (int(pet_screen_x - 28), int(pet_screen_y + 23), 56, 13))
        self.draw_item_image("pets", player.pet, (pet_screen_x, pet_screen_y), 72, player.facing)

    def draw_pickup_bubble(self, player):
        bubble = self.pickup_bubbles.get(player.spec.key)
        if not bubble or self.elapsed >= bubble["until"]:
            return
        x = int(self.level_runtime.screen_x(player.x))
        y = int(self.world_screen_y(player.x, player.y - 228 - player.jump_z))
        pulse = int(math.sin(self.elapsed * 9) * 3)
        pygame.draw.circle(self.canvas, INK, (x, y), 49 + pulse)
        pygame.draw.circle(self.canvas, GOLD, (x, y), 43 + pulse)
        pygame.draw.circle(self.canvas, (255, 224, 111), (x - 8, y - 9), 28 + pulse)
        if bubble["collection"] == "food":
            self.draw_food_icon(bubble["id"], (x - 4, y - 5), 1.0)
        elif bubble["collection"] == "loot":
            self.draw_gold_bag((x - 4, y - 3), .72)
        elif not self.draw_item_image(bubble["collection"], bubble["id"], (x - 4, y - 5), 52):
            pygame.draw.circle(self.canvas, RED, (x - 4, y - 4), 17)
            pygame.draw.line(self.canvas, (54, 114, 52), (x - 4, y - 20), (x + 7, y - 32), 5)
        pygame.draw.circle(self.canvas, INK, (x + 31, y + 30), 20)
        self.text(f"x{bubble['count']}", 14, CREAM, (x + 31, y + 30), True)

