        self.text("FREE CASLTE", 70, CREAM, (870, 130), True, 4)
        self.text("CRASHERS REMAKE", 57, GOLD, (870, 195), True, 4)
        self.text("LOCAL CO-OP PROTOTYPE", 19, MUTED, (870, 241), True)
