    def render_world_map(self):
        nodes = self.level_library.nodes
        self.gradient(self.canvas, (47, 89, 107), (221, 177, 112))
        pygame.draw.circle(self.canvas, (255, 224, 156), (1090, 105), 70)
        def screen_point(position):
            return (
                int(float(position[0]) - self.map_camera_x),
                int(float(position[1]) - self.map_camera_y),
            )

        land = [
            (50, 530), (120, 340), (315, 280), (440, 350), (560, 175), (745, 190),
            (850, 315), (920, 220), (900, 40), (925, -170), (940, -330), (1040, -410),
            (1140, -335), (1160, -150), (1350, -100), (1430, 20), (1360, 210),
            (1210, 390), (1420, 285), (1640, 215), (1845, 330), (1880, 540),
            (1680, 625), (1380, 610), (1180, 600), (740, 655), (300, 620),
        ]
        inner_land = [(int(x + (760 - x) * .025), int(y + (180 - y) * .025)) for x, y in land]
        pygame.draw.polygon(self.canvas, INK, [screen_point(point) for point in land])
        pygame.draw.polygon(self.canvas, (104, 151, 89), [screen_point(point) for point in inner_land])
        nodes_by_key = {node.key: node for node in nodes}
        for node in nodes:
            for requirement in node.requires:
                parent = nodes_by_key.get(requirement)
                if not parent:
                    continue
                open_path = self.node_unlocked(node)
                parent_position = screen_point(parent.position)
                node_position = screen_point(node.position)
                pygame.draw.line(self.canvas, (226, 210, 149) if open_path else (96, 102, 96), parent_position, node_position, 19)
                pygame.draw.line(self.canvas, (129, 93, 61) if open_path else (53, 59, 61), parent_position, node_position, 5)
        self.text("WORLD MAP", 49, CREAM, (640, 58), True, 3)
        for index, level in enumerate(nodes):
            selected = index == self.world_selection
            unlocked = self.node_unlocked(level)
            pulse = int(math.sin(self.elapsed * 5) * 5) if selected else 0
            radius = 55 if selected else 42
            position = screen_point(level.position)
            pygame.draw.circle(self.canvas, INK, position, radius + 9 + pulse, 7)
            pygame.draw.circle(self.canvas, level.color if unlocked else (72, 79, 81), position, radius + pulse)
            if unlocked:
                self.text(index + 1, 29, INK, position, True)
            else:
                pygame.draw.rect(self.canvas, INK, (position[0] - 15, position[1] - 3, 30, 26), border_radius=5)
                pygame.draw.arc(self.canvas, INK, (position[0] - 13, position[1] - 24, 26, 32), math.pi, math.tau, 7)
            compact_label = len(level.name) >= 13
            label_size = (19 if selected else 14) if compact_label else (23 if selected else 18)
            self.text(level.name, label_size, CREAM if unlocked else MUTED, (position[0], position[1] + 79), True, 2)
            if selected:
                requirement = level.requires[-1] if level.requires else "PREVIOUS LEVEL"
                subtitle = level.subtitle if unlocked else (
                    "PERMANENTLY LOCKED" if level.permanently_locked
                    else f"LOCKED · COMPLETE {requirement.replace('_', ' ').upper()}"
                )
                self.text(subtitle, 16, CREAM if unlocked else GOLD, (position[0], position[1] + 107), True, 2)
        party_position = screen_point((self.map_party_x, self.map_party_y))
        for index, spec in enumerate(self.player_specs):
            self.draw_knight(
                (party_position[0] - 40 + index * 30, party_position[1]),
                .32,
                spec.knight,
                walk=self.elapsed * 2,
                number=spec.slot,
            )
        panel = pygame.Rect(370, 642, 540, 62)
        pygame.draw.rect(self.canvas, INK, panel, border_radius=16)
        pygame.draw.rect(self.canvas, PANEL, panel.inflate(-5, -5), border_radius=13)
        self.text("D-PAD PATHS    A ENTER    Y STATS    START MENU", 16, CREAM, panel.center, True)
        if self.elapsed < self.item_notice_until:
            self.text(self.item_notice, 18, GOLD, (640, 615), True, 2)
        self.render_pause()

