        pygame.draw.circle(self.canvas, ORANGE, (int(x - 14 * scale), int(y - 27 * scale)), max(2, int(5 * scale)))
        pygame.draw.circle(self.canvas, ORANGE, (int(x + 14 * scale), int(y - 27 * scale)), max(2, int(5 * scale)))

