        pygame.draw.rect(self.canvas, (112, 64, 119), (throne_x - 70, 313, 192, 28), border_radius=6)
        if show_king and -180 < throne_x < WIDTH + 180:
            king = next(knight for knight in KNIGHTS if knight.key == "king")
            self.draw_knight((throne_x + 25, 268), .47, king, 1, False, 0, weapon=None, show_shield=False)
