    def draw_home_castle_road(self):
        runtime, camera = self.level_runtime, self.level_runtime.camera_x
        lower_shift = int(-runtime.camera_y)
        self.gradient(self.canvas, (79, 128, 154), (235, 174, 101))
        pygame.draw.circle(self.canvas, (255, 229, 166), (1095, 92), 62)
        # Distant hills and the castle wall remain one continuous backdrop.
        for layer, color, speed, base in ((0, (73, 107, 83), .18, 365), (1, (77, 127, 76), .32, 425)):
            points = [(-80, HEIGHT)]
            for index in range(14):
                x = index * 190 - (camera * speed) % 190
                points.append((x, base - (index % 3) * 35))
            points.extend([(WIDTH + 80, HEIGHT)])
            pygame.draw.polygon(self.canvas, color, points)
        castle_right = int(1080 - camera * .78)
        pygame.draw.rect(self.canvas, (92, 109, 118), (-50 - int(camera * .78), lower_shift, castle_right + 70, 545))
        for x in range(-80, castle_right + 80, 112):
            for y in range(8, 520, 67):
                pygame.draw.rect(self.canvas, (128, 119, 111), (x - (56 if (y // 67) % 2 else 0), y + lower_shift, 99, 54), 4)
        for window_world in (690, 940):
            x = int(window_world - camera * .78)
            pygame.draw.ellipse(self.canvas, (49, 67, 78), (x - 48, 125 + lower_shift, 96, 250))
            pygame.draw.rect(self.canvas, (49, 67, 78), (x - 48, 235 + lower_shift, 96, 185))
            pygame.draw.ellipse(self.canvas, (206, 191, 150), (x - 34, 145 + lower_shift, 68, 210))
        throne_x = int(145 - camera)
        if -180 < throne_x < WIDTH + 180:
            pygame.draw.polygon(self.canvas, INK, [(throne_x - 165, 345 + lower_shift), (throne_x + 245, 345 + lower_shift), (throne_x + 300, 455 + lower_shift), (throne_x - 210, 455 + lower_shift)])
            pygame.draw.polygon(self.canvas, (98, 46, 154), [(throne_x - 150, 354 + lower_shift), (throne_x + 230, 354 + lower_shift), (throne_x + 275, 443 + lower_shift), (throne_x - 195, 443 + lower_shift)])
            pygame.draw.rect(self.canvas, INK, (throne_x - 68, 92 + lower_shift, 185, 255), border_radius=12)
            pygame.draw.rect(self.canvas, GOLD, (throne_x - 56, 104 + lower_shift, 161, 231), border_radius=8)
            pygame.draw.rect(self.canvas, (135, 82, 85), (throne_x - 43, 121 + lower_shift, 135, 200), border_radius=7)
            self.draw_knight((throne_x + 22, 270 + lower_shift), .46, CHARACTERS_BY_KEY["king"], 1, weapon=None, pointing=True, show_shield=False)

        # Stone becomes descending stairs, then dirt, then climbs back to stone.
        pygame.draw.rect(self.canvas, (87, 97, 98), (0, 420 + lower_shift, WIDTH, 300))
        for region in runtime.scene.get("terrain", []):
            left, right = runtime.screen_x(region["from"]), runtime.screen_x(region["to"])
            if right < 0 or left > WIDTH:
                continue
            kind = region["kind"]
            color = (93, 101, 102) if kind in {"stone", "stone_wall_top"} else (112, 80, 49)
            if kind == "stairs_up":
                steps = 18
                width = (right - left) / steps
                for index in range(steps):
                    world_x = float(region["from"]) + (index + .5) * (float(region["to"]) - float(region["from"])) / steps
                    top = 420 + self.world_elevation(world_x) - runtime.camera_y
                    pygame.draw.rect(self.canvas, (108, 105, 99), (int(left + index * width), int(top), int(width + 2), HEIGHT - int(top)))
                    pygame.draw.line(self.canvas, (55, 62, 65), (left + index * width, top), (left + (index + 1) * width, top), 4)
            else:
                top = 420 + self.world_elevation((float(region["from"]) + float(region["to"])) / 2) - runtime.camera_y
                pygame.draw.rect(self.canvas, color, (int(left), int(top), int(right - left + 2), HEIGHT - int(top)))
                if kind == "stairs_down":
                    steps = 8
                    width = (right - left) / steps
                    for index in range(steps):
                        step_top = top + index * 10
                        pygame.draw.rect(self.canvas, (108, 105, 99), (int(left + index * width), int(step_top), int(width + 2), HEIGHT - int(step_top)))
                        pygame.draw.line(self.canvas, (55, 62, 65), (left + index * width, step_top), (left + (index + 1) * width, step_top), 4)

        # The stairs arrive directly on the open top surface of the existing
        # castle wall.  Do not build another wall or parapet on that surface.
        upper_left, upper_right = int(runtime.screen_x(3650)), int(runtime.screen_x(5100))
        upper_ground = int(self.world_screen_y(3800, 420))
        if upper_right > -100 and upper_left < WIDTH + 100:
            # Broad perspective paving reads as a horizontal floor, not a
            # vertical brick wall.
            pygame.draw.rect(self.canvas, (79, 84, 86), (upper_left, upper_ground, upper_right - upper_left, HEIGHT - upper_ground))
            pygame.draw.line(self.canvas, (45, 52, 56), (upper_left, upper_ground), (upper_right, upper_ground), 7)
            for floor_y in (upper_ground + 52, upper_ground + 120, upper_ground + 205, upper_ground + 305):
                pygame.draw.line(self.canvas, (54, 61, 65), (upper_left, floor_y), (upper_right, floor_y), 4)
            vanishing_x = int(runtime.screen_x(4310))
            for floor_x in range(upper_left - 300, upper_right + 301, 210):
                pygame.draw.line(self.canvas, (54, 61, 65), (vanishing_x, upper_ground), (floor_x, HEIGHT), 4)
        props = runtime.scene.get("props", {})
        hay_x = int(runtime.screen_x(props.get("hay_pitchfork", -9999)))
        if -170 < hay_x < WIDTH + 170:
            for offset in range(-90, 91, 30):
                pygame.draw.line(self.canvas, GOLD, (hay_x + offset, 565 + lower_shift), (hay_x + offset + 28, 490 + lower_shift - abs(offset) // 5), 11)
            pygame.draw.ellipse(self.canvas, (206, 151, 54), (hay_x - 105, 515 + lower_shift, 210, 75))
        for house_x in props.get("burning_houses", []):
            sx = int(runtime.screen_x(house_x))
            if not -220 < sx < WIDTH + 220:
                continue
            pygame.draw.rect(self.canvas, INK, (sx - 130, 270 + lower_shift, 260, 250))
            pygame.draw.rect(self.canvas, (119, 75, 47), (sx - 118, 282 + lower_shift, 236, 226))
            pygame.draw.polygon(self.canvas, INK, [(sx - 160, 285 + lower_shift), (sx, 158 + lower_shift), (sx + 160, 285 + lower_shift)])
            pygame.draw.polygon(self.canvas, (67, 43, 38), [(sx - 141, 278 + lower_shift), (sx, 177 + lower_shift), (sx + 141, 278 + lower_shift)])
            pygame.draw.rect(self.canvas, (39, 31, 31), (sx - 34, 397 + lower_shift, 68, 112), border_radius=20)
            for fx, fy in ((-82, 256), (47, 244), (6, 195)):
                wobble = math.sin(self.elapsed * 10 + house_x + fx) * 8
                pygame.draw.polygon(self.canvas, ORANGE, [(sx + fx - 22, fy + 62 + lower_shift), (sx + fx + wobble, fy - 18 + lower_shift), (sx + fx + 24, fy + 62 + lower_shift)])
                pygame.draw.polygon(self.canvas, GOLD, [(sx + fx - 10, fy + 55 + lower_shift), (sx + fx + wobble, fy + 13 + lower_shift), (sx + fx + 11, fy + 55 + lower_shift)])
        crate_x = int(runtime.screen_x(props.get("crate", -9999)))
        if -120 < crate_x < WIDTH + 120:
            ground_y = int(self.world_screen_y(props.get("crate", 3810), 440))
            body_y = ground_y - 82
            # A compact plank crate, deliberately distinct from any wall.
            pygame.draw.rect(self.canvas, INK, (crate_x - 59, body_y, 118, 82), border_radius=4)
            pygame.draw.rect(self.canvas, (139, 86, 43), (crate_x - 51, body_y + 8, 102, 66), border_radius=2)
            for plank_x in (crate_x - 18, crate_x + 18):
                pygame.draw.line(self.canvas, (91, 54, 34), (plank_x, body_y + 9), (plank_x, body_y + 73), 5)
            pygame.draw.line(self.canvas, (76, 46, 31), (crate_x - 47, body_y + 12), (crate_x + 47, body_y + 70), 8)
            pygame.draw.line(self.canvas, (76, 46, 31), (crate_x + 47, body_y + 12), (crate_x - 47, body_y + 70), 8)
            open_amount = 0.0 if self.home_ambush_time is None else min(1.0, self.home_ambush_time / 1.05)
            smooth_open = open_amount * open_amount * (3 - 2 * open_amount)
            lid = pygame.Surface((126, 25), pygame.SRCALPHA)
            pygame.draw.rect(lid, INK, (0, 0, 126, 25), border_radius=4)
            pygame.draw.rect(lid, (145, 91, 46), (6, 5, 114, 14), border_radius=2)
            pygame.draw.line(lid, (188, 128, 67), (14, 9), (112, 9), 3)
            lid = pygame.transform.rotozoom(lid, smooth_open * 78, 1.0)
            lid_rect = lid.get_rect(bottomleft=(crate_x - 61, body_y + 3 - int(smooth_open * 4)))
            self.canvas.blit(lid, lid_rect)
        ladder_x = int(runtime.screen_x(props.get("ladder", -9999)))
        ladder_amount = 0.0 if self.home_ambush_time is None else max(0.0, min(1.0, (self.home_ambush_time - 3.0) / 1.25))
        if ladder_amount > 0 and -100 < ladder_x < WIDTH + 100:
            smooth_ladder = ladder_amount * ladder_amount * (3 - 2 * ladder_amount)
            upper_edge = int(self.world_screen_y(props.get("ladder", 4380), 420))
            # The ladder rises from below the existing wall top and is clipped
            # to a small slot inside the stone-facing area.  No ladder is
            # drawn in the sky or all the way to the bottom of the screen.
            ladder_top = int(upper_edge + 14 + (1.0 - smooth_ladder) * 132)
            ladder_bottom = ladder_top + 132
            old_clip = self.canvas.get_clip()
            self.canvas.set_clip(pygame.Rect(ladder_x - 52, upper_edge + 4, 104, 154))
            for offset in (-30, 30):
                pygame.draw.line(self.canvas, INK, (ladder_x + offset, ladder_top), (ladder_x + offset, ladder_bottom), 16)
                pygame.draw.line(self.canvas, (132, 83, 44), (ladder_x + offset, ladder_top), (ladder_x + offset, ladder_bottom), 8)
            for rung_y in (ladder_top + 29, ladder_top + 70, ladder_top + 111):
                pygame.draw.line(self.canvas, INK, (ladder_x - 33, rung_y), (ladder_x + 33, rung_y), 13)
                pygame.draw.line(self.canvas, (155, 99, 52), (ladder_x - 29, rung_y), (ladder_x + 29, rung_y), 6)
            pygame.draw.arc(self.canvas, (132, 83, 44), (ladder_x - 48, ladder_bottom - 22, 36, 42), 0, math.pi, 7)
            pygame.draw.arc(self.canvas, (132, 83, 44), (ladder_x + 12, ladder_bottom - 22, 36, 42), 0, math.pi, 7)
            self.canvas.set_clip(old_clip)

