    def draw_forest_story_props(self):
        runtime = self.level_runtime
        if runtime.level_id != "forest_entrance" or runtime.scene_id != "forest_road":
            return
        props = runtime.scene.get("props", {})
        dead = (
            (props.get("dead_barbarian"), CHARACTERS_BY_KEY["barbarian"], "barbarian_axe"),
            (props.get("dead_gray_knight"), CHARACTERS_BY_KEY["royal_guard"], "royal_spear"),
        )
        for world_x, knight, weapon in dead:
            if world_x is None:
                continue
            x = runtime.screen_x(float(world_x))
            if -160 < x < WIDTH + 160:
                y = self.world_screen_y(float(world_x), 550)
                self.draw_knight((x, y - 58), .62, knight, 1, weapon=weapon, dead=True)
        for world_x in props.get("decorative_money_bags", []):
            x = runtime.screen_x(float(world_x))
            y = self.world_screen_y(float(world_x), 535)
            if -90 < x < WIDTH + 90:
                self.draw_gold_bag((x, y), .82)

    def draw_princess_pole_group(self, princess_key, world_x, ground_y, carriers, facing=1):
        x = self.level_runtime.screen_x(world_x)
        y = self.world_screen_y(world_x, ground_y)
        pole_left, pole_right = x - 105, x + 105
        pygame.draw.line(self.canvas, INK, (pole_left, y - 118), (pole_right, y - 118), 13)
        pygame.draw.line(self.canvas, (114, 72, 39), (pole_left, y - 118), (pole_right, y - 118), 7)
        self.draw_story_character(princess_key, (x, y - 175), 128, facing)
        for index, carrier in enumerate(carriers):
            carrier_x = pole_left if index == 0 else pole_right
            if carrier == "fencer":
                knight = CHARACTERS_BY_KEY["royal_guard"]
                self.draw_knight((carrier_x, y - 58), .52, knight, facing, False, self.elapsed * 8, weapon=None, show_shield=False)
                pygame.draw.line(self.canvas, INK, (carrier_x + facing * 30, y - 80), (carrier_x + facing * 105, y - 118), 7)
                pygame.draw.line(self.canvas, (202, 207, 203), (carrier_x + facing * 31, y - 80), (carrier_x + facing * 105, y - 118), 3)
            else:
                self.draw_knight((carrier_x, y - 58), .56, CHARACTERS_BY_KEY["thief"], facing, False, self.elapsed * 8, weapon=None)
                self.draw_bag_head(int(carrier_x), int(y), 1.0)

    def draw_forest_cutscene(self):
        if not self.story_event or self.story_event.get("id") != "forest_princess_escape":
            return
        t = self.story_event_time
        runtime = self.level_runtime

        orange_move = max(0.0, min(1.0, (t - .4) / 2.8))
        blue_move = max(0.0, min(1.0, (t - 3.0) / 2.8))
        green_move = max(0.0, min(1.0, (t - 5.7) / 2.8))
        if orange_move < 1:
            self.draw_princess_pole_group("princess_orange", 2020 + orange_move * 1150, 540, ("fencer", "fencer"))
        if blue_move < 1:
            self.draw_princess_pole_group("princess_blue", 1820 + blue_move * 1200, 520, ("thief",), 1)
        if green_move < 1:
            self.draw_princess_pole_group("princess_green", 1620 + green_move * 1250, 570, ("thief",), 1)

        owner_world_x = 2190
        owner_x = runtime.screen_x(owner_world_x) + math.sin(t * 19) * 4
        owner_y = self.world_screen_y(owner_world_x, 545)
        self.draw_knight((owner_x, owner_y - 58), .53, CHARACTERS_BY_KEY["royal_guard"], -1, weapon=None, show_shield=False)
        pygame.draw.circle(self.canvas, CREAM, (int(owner_x), int(owner_y - 125)), 16)
        pygame.draw.circle(self.canvas, INK, (int(owner_x - 2), int(owner_y - 125)), 6)
        self.draw_gold_bag((owner_x + 75, owner_y - 2), .78)

        buff_world_x = 2320
        buff_x = runtime.screen_x(buff_world_x)
        buff_y = self.world_screen_y(buff_world_x, 555)
        self.draw_knight((buff_x, buff_y - 82), 1.28, CHARACTERS_BY_KEY["buff_thief"], -1, weapon="rusty_sword")
        self.draw_bag_head(int(buff_x), int(buff_y), 1.68)

        if 3.1 < t < 8.7:
            for index in range(5):
                jump_phase = max(0.0, min(1.0, (t - 3.1 - index * .42) / 1.55))
                if jump_phase <= 0:
                    continue
                world_x = 2220 + index * 115 + jump_phase * 260
                x = runtime.screen_x(world_x)
                landing_y = self.world_screen_y(world_x, 545 + (index % 2) * 35)
                y = landing_y - math.sin(jump_phase * math.pi) * 220 - (1 - jump_phase) * 125
                self.draw_knight((x, y - 58), .58, CHARACTERS_BY_KEY["barbarian"], -1, False, t * 9, weapon="barbarian_axe")

    def draw_pipistrello_background(self):
        runtime = self.level_runtime
        if runtime.scene_id == "treasure_room":
            self.gradient(self.canvas, (20, 17, 25), (78, 55, 43))
            for index in range(11):
                x = int(index * 170 - (runtime.camera_x * .22) % 170)
                pygame.draw.polygon(self.canvas, (55, 47, 53), [(x - 90, 220), (x, 80 + index % 3 * 35), (x + 105, 220)])
            pygame.draw.rect(self.canvas, (71, 57, 48), (0, 410, WIDTH, 310))
            pygame.draw.rect(self.canvas, (105, 79, 52), (0, 410, WIDTH, 14))
            for index in range(55):
                x = (index * 83 - int(runtime.camera_x * .73)) % (WIDTH + 100) - 50
                y = 435 + (index * 47) % 250
                pygame.draw.circle(self.canvas, GOLD if index % 3 else (222, 148, 42), (x, y), 5 + index % 4)
            return
        self.gradient(self.canvas, (12, 14, 22), (60, 43, 52))
        camera = runtime.camera_x
        for layer, color, speed in ((0, (34, 31, 40), .18), (1, (48, 39, 47), .36)):
            for index in range(12):
                x = int(index * 190 - (camera * speed) % 190)
                peak = 38 + (index * 53 + layer * 41) % 105
                pygame.draw.polygon(self.canvas, color, [(x - 120, 0), (x, peak + 105), (x + 110, 0)])
        for index in range(16):
            x = int(index * 103 - (camera * .45) % 103)
            length = 34 + (index * 29) % 78
            pygame.draw.polygon(self.canvas, INK, [(x - 22, 0), (x + 24, 0), (x + 3, length + 8)])
            pygame.draw.polygon(self.canvas, (64, 53, 61), [(x - 15, 0), (x + 16, 0), (x + 2, length)])
        floor_points = [(-80, HEIGHT)]
        for screen_x in range(-80, WIDTH + 161, 80):
            world_x = runtime.camera_x + screen_x
            floor_points.append((screen_x, self.world_screen_y(world_x, 625)))
        floor_points.extend([(WIDTH + 160, HEIGHT), (-80, HEIGHT)])
        pygame.draw.polygon(self.canvas, (50, 43, 47), floor_points)
        surface_points = []
        for screen_x in range(-80, WIDTH + 161, 40):
            world_x = runtime.camera_x + screen_x
            surface_points.append((screen_x, self.world_screen_y(world_x, 625)))
        pygame.draw.lines(self.canvas, (117, 92, 82), False, surface_points, 13)
        pygame.draw.lines(self.canvas, (77, 62, 62), False, surface_points, 6)
        for index in range(18):
            world_x = math.floor(camera / 150) * 150 + index * 150
            x = int(runtime.screen_x(world_x))
            y = int(self.world_screen_y(world_x, 655 + (index % 3) * 26))
            pygame.draw.ellipse(self.canvas, (34, 31, 35), (x - 52, y - 25, 104, 50))

