    def draw_skeleton_body(self, world_x, world_y):
        x = int(self.level_runtime.screen_x(world_x))
        y = int(self.world_screen_y(world_x, world_y))
        if x < -180 or x > WIDTH + 180:
            return
        if self.draw_art_image("props/skeleton_body", (x, y), 640):
            return
        bone = (211, 207, 184)
        pygame.draw.ellipse(self.canvas, INK, (x - 89, y - 48, 81, 62))
        pygame.draw.ellipse(self.canvas, bone, (x - 82, y - 41, 67, 48))
        pygame.draw.circle(self.canvas, INK, (x - 60, y - 22), 8)
        pygame.draw.circle(self.canvas, INK, (x - 36, y - 22), 8)
        pygame.draw.line(self.canvas, INK, (x - 11, y - 2), (x + 95, y + 4), 18)
        pygame.draw.line(self.canvas, bone, (x - 8, y - 2), (x + 92, y + 4), 10)
        for offset in (12, 36, 60):
            pygame.draw.arc(self.canvas, bone, (x + offset, y - 24, 40, 48), .2, math.pi - .2, 6)
        pygame.draw.line(self.canvas, INK, (x + 92, y + 3), (x + 143, y - 22), 16)
        pygame.draw.line(self.canvas, bone, (x + 92, y + 3), (x + 143, y - 22), 8)
        pygame.draw.line(self.canvas, INK, (x + 86, y + 8), (x + 139, y + 35), 16)
        pygame.draw.line(self.canvas, bone, (x + 86, y + 8), (x + 139, y + 35), 8)

    def draw_pipistrello_props(self):
        runtime = self.level_runtime
        if runtime.level_id != "pipistrellos_cave":
            return
        props = runtime.scene.get("props", {})
        if runtime.scene_id == "blood_tunnel":
            skeleton_x = props.get("skeleton")
            if skeleton_x is not None:
                self.draw_skeleton_body(float(skeleton_x), 555)
            for index, world_x in enumerate(props.get("blood_drips", [])):
                x = int(runtime.screen_x(float(world_x)))
                if -40 < x < WIDTH + 40:
                    length = 42 + index * 20
                    pygame.draw.line(self.canvas, (112, 9, 20), (x, 0), (x, length), 7)
                    phase = (self.elapsed * (105 + index * 18) + index * 47) % 250
                    drop_y = length + phase
                    if drop_y < 390:
                        pygame.draw.circle(self.canvas, (151, 13, 25), (x, int(drop_y)), 7)
                        pygame.draw.polygon(self.canvas, (151, 13, 25), [(x - 6, drop_y), (x + 6, drop_y), (x, drop_y - 13)])
            self.draw_pip_procession()
        else:
            for index, world_x in enumerate(props.get("gold_piles", [])):
                x = int(runtime.screen_x(float(world_x)))
                y = int(self.world_screen_y(float(world_x), 610))
                if -150 < x < WIDTH + 150:
                    for coin in range(19):
                        cx = x - 72 + (coin * 29) % 144
                        cy = y - 8 - (coin * 17) % 55
                        pygame.draw.circle(self.canvas, INK, (cx, cy), 9)
                        pygame.draw.circle(self.canvas, GOLD, (cx, cy), 6)

    def draw_pip_poops(self):
        for poop in self.pip_poops:
            x = int(self.level_runtime.screen_x(poop["x"]))
            y = int(self.world_screen_y(poop["x"], poop["y"]))
            if x < -120 or x > WIDTH + 120:
                continue
            if poop["landed"]:
                fade = max(45, min(175, int(poop["remaining"] / 10 * 175)))
                puddle = pygame.Surface((190, 92), pygame.SRCALPHA)
                pygame.draw.ellipse(puddle, (26, 12, 20, fade), (4, 30, 182, 55))
                pygame.draw.ellipse(puddle, (100, 132, 42, fade), (16, 38, 158, 37), 5)
                for offset in (35, 77, 128, 158):
                    pygame.draw.circle(puddle, (139, 183, 59, fade), (offset, 40 + offset % 13), 5, 2)
                self.canvas.blit(puddle, (x - 95, y - 48))
            else:
                pygame.draw.circle(self.canvas, INK, (x, y), 24)
                pygame.draw.circle(self.canvas, (75, 43, 28), (x, y), 18)
                pygame.draw.circle(self.canvas, (130, 164, 56), (x - 6, y - 7), 5)

    def draw_pip_procession(self):
        if not self.pip_boss_defeated:
            return
        progress = max(0.0, min(1.0, self.pip_procession_time / 5.6))
        world_x = 6660 + progress * 1690
        y = self.world_screen_y(world_x, 540)
        x = self.level_runtime.screen_x(world_x)
        self.draw_horse_actor((x, y), .92, 1, self.pip_procession_time * 10)
        king = CHARACTERS_BY_KEY.get("king", CHARACTERS_BY_KEY["royal_guard"])
        self.draw_knight((x, y - 126), .55, king, 1, False, self.pip_procession_time * 7, weapon=None, pointing=True, show_shield=False)
        guard = CHARACTERS_BY_KEY.get("royal_guard", CHARACTERS_BY_KEY["barbarian"])
        for index in range(3):
            guard_world_x = world_x - 175 - index * 112
            gx = self.level_runtime.screen_x(guard_world_x)
            gy = self.world_screen_y(guard_world_x, 510 + index % 2 * 45)
            self.draw_knight((gx, gy - 58), .62, guard, 1, False, self.pip_procession_time * 9 + index, weapon="royal_spear")

    def draw_pipistrello_cutscene(self):
        if not self.story_event or self.story_event.get("id") != "pipistrello_arrival":
            return
        t = self.story_event_time
        for index in range(6):
            phase = max(0.0, min(1.0, (t - .45 - index * .28) / 2.2))
            if phase <= 0:
                continue
            world_x = 8380 - phase * (1180 + index * 65)
            y = 235 + index % 3 * 77 + math.sin(t * 8 + index) * 34
            self.draw_small_bat_actor((self.level_runtime.screen_x(world_x), y), .85, -1, t * 10 + index)
        emerge = max(0.0, min(1.0, (t - 3.65) / 2.0))
        if emerge > 0:
            world_x = 8420 - emerge * 1040
            y = 260 + (1 - emerge) * 210
            self.draw_pipistrello_actor((self.level_runtime.screen_x(world_x), y), .9, -1, True)
            if emerge > .55:
                self.text("PIPISTRELLO", 25, ORANGE, (640, 225), True, 3)

    def draw_pip_results(self):
        if (
            not self.pip_results_active
            or self.state != "level"
            or self.level_runtime.level_id != "pipistrellos_cave"
            or self.level_runtime.scene_id != "treasure_room"
        ):
            return
        shade = pygame.Surface((WIDTH, 236), pygame.SRCALPHA)
        shade.fill((7, 10, 16, 232))
        self.canvas.blit(shade, (0, 0))
        count_progress = min(1.0, self.pip_results_time / 2.1)
        width = WIDTH // max(1, len(self.players))
        for index, player in enumerate(self.players):
            center_x = width * index + width // 2
            self.text(f"P{player.slot} {player.knight.name.upper()}", 19, CREAM, (center_x, 36), True, 2)
            self.text(f"KILLS  {int(player.score * count_progress)}", 17, ORANGE, (center_x, 84), True)
            self.text(f"GOLD  {int(player.gold_earned * count_progress)}", 17, GOLD, (center_x, 126), True)
            self.text(f"EXPERIENCE  {int(player.xp_earned * count_progress)}", 17, TEAL, (center_x, 168), True)
        if count_progress >= 1:
            text_value = "EXIT OPEN" if "pip_results_done" in self.scene_flags else "TREASURE CLEARED"
            self.text(text_value, 25, CREAM, (640, 214), True, 3)

    def draw_flower(self, x, y, scale=1.0, color=(239, 115, 177)):
        palette = {
            (247, 207, 65): "yellow", (242, 208, 70): "yellow",
            (221, 237, 243): "white", (116, 180, 244): "blue",
            (151, 102, 205): "purple", (238, 128, 78): "orange",
        }
        color_key = palette.get(tuple(color), "pink")
        if self.draw_art_image(f"props/flower_{color_key}", (x, y), 640 * scale):
            return
        stem = max(3, int(6 * scale))
        pygame.draw.line(self.canvas, (43, 107, 50), (int(x), int(y)), (int(x), int(y - 42 * scale)), stem)
        for angle in range(0, 360, 60):
            dx = math.cos(math.radians(angle)) * 15 * scale
            dy = math.sin(math.radians(angle)) * 15 * scale
            pygame.draw.circle(self.canvas, INK, (int(x + dx), int(y - 43 * scale + dy)), max(5, int(11 * scale)))
            pygame.draw.circle(self.canvas, color, (int(x + dx), int(y - 43 * scale + dy)), max(3, int(8 * scale)))
        pygame.draw.circle(self.canvas, GOLD, (int(x), int(y - 43 * scale)), max(4, int(8 * scale)))

