    def draw_parade_placeholder_background(self):
        self.gradient(self.canvas, (98, 166, 206), (241, 184, 119))
        pygame.draw.rect(self.canvas, (97, 136, 78), (0, 430, WIDTH, 290))
        for index in range(11):
            x = index * 140 - int(self.level_runtime.camera_x * .3) % 140
            pygame.draw.line(self.canvas, (87, 55, 40), (x, 220), (x, 520), 11)
            color = (225, 68, 66) if index % 2 else (244, 209, 67)
            pygame.draw.polygon(self.canvas, color, [(x, 225), (x + 80, 252), (x, 284)])
        self.text("PARADE · PLACEHOLDER", 30, CREAM, (640, 330), True, 3)

    def draw_parade_background(self):
        """Scrolling village, wall, forest, and cave backdrops for the cart ride."""
        phase, timer, scroll = self.parade_phase, self.parade_time, self.parade_scroll
        self.gradient(self.canvas, (93, 166, 211), (247, 195, 133))
        pygame.draw.circle(self.canvas, (255, 226, 145), (1100, 82), 53)

        if phase == "intro":
            # The church is one huge fixed facade behind the procession.  Only
            # its features slide during the upward camera reveal; the solid
            # masonry still fills the screen, so the road and cart never look
            # as though they have lifted into the sky with the camera.
            rise = max(0.0, min(1.0, (timer - 6.0) / 2.0))
            rise = rise * rise * (3.0 - 2.0 * rise)
            feature_y = int(rise * 260)
            pygame.draw.rect(self.canvas, (151, 139, 128), (0, 46, WIDTH, HEIGHT - 46))
            pygame.draw.rect(self.canvas, (105, 95, 92), (0, 46, WIDTH, HEIGHT - 46), 8)

            # Offset stone courses make this unmistakably a church wall rather
            # than a separate freestanding barricade.
            for row, y in enumerate(range(-130 + feature_y, HEIGHT + 130, 72)):
                offset = -82 if row % 2 else -15
                for x in range(offset, WIDTH + 170, 164):
                    pygame.draw.rect(self.canvas, (181, 168, 150), (x, y, 156, 65), border_radius=4)
                    pygame.draw.rect(self.canvas, (112, 103, 99), (x, y, 156, 65), 4, border_radius=4)

            # Heavy buttresses frame the exit and carry the church upward past
            # the cannon window.
            for buttress_x in (245, 920):
                pygame.draw.polygon(
                    self.canvas,
                    INK,
                    [(buttress_x - 34, 44), (buttress_x + 74, 44), (buttress_x + 116, HEIGHT), (buttress_x - 76, HEIGHT)],
                )
                pygame.draw.polygon(
                    self.canvas,
                    (132, 120, 112),
                    [(buttress_x - 24, 52), (buttress_x + 64, 52), (buttress_x + 101, HEIGHT), (buttress_x - 61, HEIGHT)],
                )

            tunnel = pygame.Rect(-105, 250 + feature_y, 360, 380)
            pygame.draw.ellipse(self.canvas, INK, tunnel)
            pygame.draw.ellipse(self.canvas, (35, 37, 42), tunnel.inflate(-28, -28))
            for ring in range(3):
                pygame.draw.arc(self.canvas, (197, 184, 161), tunnel.inflate(35 + ring * 24, 24 + ring * 18), math.pi, math.tau, 8)
            # Celebration bushes are bound with bright white ribbons.
            for bush_x in (290, 430, 570, 710):
                bush_y = 515 + feature_y
                pygame.draw.circle(self.canvas, INK, (bush_x, bush_y), 70)
                pygame.draw.circle(self.canvas, (61, 130, 64), (bush_x, bush_y), 61)
                pygame.draw.line(self.canvas, CREAM, (bush_x - 45, bush_y - 44), (bush_x + 45, bush_y + 45), 9)
                pygame.draw.line(self.canvas, CREAM, (bush_x + 45, bush_y - 44), (bush_x - 45, bush_y + 45), 9)

            window_x, window_y = 250, -138 + feature_y
            pygame.draw.rect(self.canvas, INK, (window_x - 142, window_y - 104, 284, 218), border_radius=16)
            pygame.draw.rect(self.canvas, (49, 55, 64), (window_x - 127, window_y - 89, 254, 188), border_radius=11)
            pygame.draw.line(self.canvas, CREAM, (window_x, window_y - 87), (window_x, window_y + 97), 7)
            pygame.draw.line(self.canvas, CREAM, (window_x - 125, window_y), (window_x + 125, window_y), 7)

            # Road is screen-anchored.  It must not inherit the church camera
            # offset or the cart appears to fly during the cannon reveal.
            pygame.draw.rect(self.canvas, (91, 68, 53), (0, 612, WIDTH, 108))
            pygame.draw.line(self.canvas, (54, 47, 44), (0, 612), (WIDTH, 612), 9)
        else:
            forest = phase in {"thieves", "boss", "victory", "cave"}
            wall_mix = 0.0
            if phase == "guards":
                wall_mix = max(0.0, min(1.0, (timer - 24.0) / 18.0))
            pygame.draw.rect(self.canvas, (89, 145, 75) if forest else (118, 137, 101), (0, 405, WIDTH, 315))
            shift = int(scroll * (.32 if forest else .23)) % 210
            if forest:
                for index, x in enumerate(range(-250 - shift, WIDTH + 300, 210)):
                    trunk_y = 430 + index % 2 * 34
                    pygame.draw.rect(self.canvas, INK, (x - 21, trunk_y - 195, 42, 245))
                    pygame.draw.rect(self.canvas, (83, 61, 39), (x - 14, trunk_y - 188, 28, 232))
                    for dx, dy, radius in ((-50, -200, 62), (5, -240, 72), (62, -198, 58)):
                        pygame.draw.circle(self.canvas, INK, (x + dx, trunk_y + dy), radius + 7)
                        pygame.draw.circle(self.canvas, (45, 110, 56), (x + dx, trunk_y + dy), radius)
            else:
                for index, x in enumerate(range(-250 - shift, WIDTH + 300, 210)):
                    house_color = (139, 105, 94) if index % 2 else (164, 126, 101)
                    pygame.draw.rect(self.canvas, house_color, (x, 205, 175, 245))
                    pygame.draw.polygon(self.canvas, (83, 62, 65), [(x - 18, 215), (x + 88, 125), (x + 193, 215)])
                    pygame.draw.rect(self.canvas, (45, 61, 69), (x + 30, 275, 42, 70))
                    pygame.draw.rect(self.canvas, (45, 61, 69), (x + 112, 275, 42, 70))
                if wall_mix > 0:
                    wall_top = int(395 - wall_mix * 245)
                    pygame.draw.rect(self.canvas, (100, 96, 96), (0, wall_top, WIDTH, 330))
                    for x in range(-80 - int(scroll * .45) % 120, WIDTH + 120, 120):
                        pygame.draw.rect(self.canvas, (139, 133, 124), (x, wall_top, 110, 300), 5)
                    for x in range(-30, WIDTH + 100, 170):
                        pygame.draw.rect(self.canvas, (82, 79, 83), (x, wall_top - 50, 90, 55))
            pygame.draw.rect(self.canvas, (87, 65, 51), (0, 585, WIDTH, 135))
            for x in range(-180 - int(scroll) % 180, WIDTH + 180, 180):
                pygame.draw.line(self.canvas, (57, 47, 42), (x, 590), (x + 90, HEIGHT), 8)

        # Deterministic confetti keeps the celebration alive without allocating particles.
        for index in range(36):
            x = int((index * 149 - scroll * (1.1 + index % 3 * .13)) % (WIDTH + 100) - 50)
            y = 85 + (index * 67 + int(self.elapsed * (35 + index % 4 * 9))) % 265
            color = (244, 83, 91) if index % 3 == 0 else (247, 211, 67) if index % 3 == 1 else (239, 238, 218)
            pygame.draw.rect(self.canvas, color, (x, y, 9, 5), border_radius=2)

        if phase == "cave":
            cave_progress = max(0.0, min(1.0, timer / 1.8))
            cave_left = int(WIDTH - cave_progress * 420)
            for ring in range(8):
                shade = 47 + ring * 5
                pygame.draw.ellipse(self.canvas, (shade, shade, shade + 5), (cave_left - ring * 20, 70 - ring * 15, 590 + ring * 40, 710 + ring * 30), 22)
            pygame.draw.ellipse(self.canvas, INK, (cave_left + 42, 105, 470, 650))
            self.text("CYCLOPS' CAVE", 19, CREAM, (cave_left + 275, 170), True, 2)

    def draw_cyclops_gate_background(self):
        """Rising blackstone path above a broad lava ocean."""
        runtime = self.level_runtime
        camera = runtime.camera_x
        self.gradient(self.canvas, (31, 17, 27), (164, 53, 25))
        pygame.draw.circle(self.canvas, (240, 93, 28), (1050, 112), 72)
        for layer, color, speed, base in (
            (0, (50, 32, 39), .12, 345), (1, (66, 37, 39), .28, 405),
        ):
            points = [(-100, HEIGHT)]
            shift = int(camera * speed) % 260
            for index in range(-1, 8):
                x = index * 260 - shift
                peak = base - 85 - (index % 3) * 70
                points.extend([(x - 90, base), (x, peak), (x + 120, base)])
            points.extend([(WIDTH + 100, HEIGHT)])
            pygame.draw.polygon(self.canvas, color, points)

        # The distant ocean is never walkable; bright moving bands make its
        # scale unambiguous behind the raised blackstone road.
        pygame.draw.rect(self.canvas, (154, 45, 18), (0, 352, WIDTH, 368))
        for band in range(9):
            y = 375 + band * 40
            shift = int((self.elapsed * (55 + band * 5) + band * 97) % 210)
            for x in range(-220 + shift, WIDTH + 220, 210):
                pygame.draw.arc(self.canvas, GOLD if band % 2 else ORANGE, (x, y, 170, 36), 0, math.pi, 7)

        ground = [(-100, HEIGHT)]
        for screen_x in range(-100, WIDTH + 181, 55):
            world_x = camera + screen_x
            ground_y = 420 + self.world_elevation(world_x) - runtime.camera_y
            ground.append((screen_x, int(ground_y)))
        ground.extend([(WIDTH + 180, HEIGHT)])
        pygame.draw.polygon(self.canvas, (31, 29, 34), ground)
        pygame.draw.lines(self.canvas, (91, 75, 67), False, ground[1:-1], 9)
        for index in range(22):
            world_x = math.floor(camera / 150) * 150 + index * 150
            x = runtime.screen_x(world_x)
            y = self.world_screen_y(world_x, 488 + (index * 59) % 175)
            pygame.draw.ellipse(self.canvas, (18, 19, 23), (x - 54, y - 13, 108, 27))

        props = runtime.scene.get("props", {})
        cave_world = float(props.get("cave_exit", 180))
        cave_x = runtime.screen_x(cave_world)
        cave_y = self.world_screen_y(cave_world, 535)
        if -240 < cave_x < WIDTH + 240:
            pygame.draw.ellipse(self.canvas, INK, (cave_x - 190, cave_y - 330, 380, 360))
            pygame.draw.ellipse(self.canvas, (20, 19, 27), (cave_x - 155, cave_y - 295, 310, 315))
            self.text("CYCLOPS' CAVE", 15, CREAM, (int(cave_x), int(cave_y - 355)), True, 2)

        arch_world = float(props.get("fortress_arch", 4740))
        arch_x = runtime.screen_x(arch_world)
        arch_y = self.world_screen_y(arch_world, 535)
        if -300 < arch_x < WIDTH + 300:
            pygame.draw.ellipse(self.canvas, INK, (arch_x - 220, arch_y - 430, 440, 450))
            pygame.draw.rect(self.canvas, INK, (arch_x - 220, arch_y - 215, 440, 245))
            pygame.draw.ellipse(self.canvas, (83, 77, 76), (arch_x - 205, arch_y - 415, 410, 420))
            pygame.draw.rect(self.canvas, (83, 77, 76), (arch_x - 205, arch_y - 210, 410, 225))
            pygame.draw.ellipse(self.canvas, (22, 20, 27), (arch_x - 130, arch_y - 335, 260, 350))
            pygame.draw.rect(self.canvas, (22, 20, 27), (arch_x - 130, arch_y - 170, 260, 190))
            self.text("CYCLOP'S FORTRESS", 18, GOLD, (int(arch_x), int(arch_y - 458)), True, 3)

    def draw_cyclops_gate_hazards(self):
        if self.level_runtime.level_id not in {"cyclops_gate", "lava_world"}:
            return
        runtime = self.level_runtime
        for index, wall in enumerate(runtime.scene.get("props", {}).get("lava_walls", [])):
            world_x = float(wall.get("x", 0))
            x = runtime.screen_x(world_x)
            if not -140 < x < WIDTH + 140:
                continue
            floor_y = self.world_screen_y(world_x, 420)
            active = self.lava_wall_active(wall)
            if not active:
                pygame.draw.line(self.canvas, INK, (x, floor_y - 6), (x, HEIGHT + 15), 28)
                pygame.draw.line(self.canvas, ORANGE, (x, floor_y - 6), (x, HEIGHT + 15), 13)
                pygame.draw.line(self.canvas, GOLD, (x, floor_y - 6), (x, HEIGHT + 15), 4)
                self.text("3s SAFE", 12, CREAM, (int(x), int(floor_y - 35)), True, 2)
                continue
            glow = pygame.Surface((210, HEIGHT), pygame.SRCALPHA)
            pygame.draw.rect(glow, (255, 71, 20, 40), (0, 0, 210, HEIGHT))
            self.canvas.blit(glow, (int(x - 105), 0))
            points = [(int(x - 58), int(floor_y + 25))]
            for step in range(9):
                y = int(floor_y - step * 77)
                wobble = int(math.sin(self.elapsed * 12 + step * 1.7 + index) * 31)
                points.append((int(x + wobble), y))
            points.append((int(x + 58), int(floor_y + 25)))
            pygame.draw.polygon(self.canvas, INK, points)
            pygame.draw.lines(self.canvas, ORANGE, False, points[1:-1], 52)
            pygame.draw.lines(self.canvas, GOLD, False, points[1:-1], 24)
            pygame.draw.lines(self.canvas, (255, 225, 104), False, points[1:-1], 8)

        if runtime.level_id != "lava_world" or runtime.scene_id != "lava_road":
            return
        for index, geyser in enumerate(runtime.scene.get("props", {}).get("geysers", [])):
            world_x = float(geyser.get("x", 0))
            x = runtime.screen_x(world_x)
            if not -120 < x < WIDTH + 120:
                continue
            ground_y = self.world_screen_y(world_x, 570)
            phase = (self.elapsed - self.scene_started_at + float(geyser.get("phase", 0))) % 5.4
            active = phase >= 3.4
            pygame.draw.ellipse(self.canvas, INK, (x - 48, ground_y - 17, 96, 35))
            pygame.draw.ellipse(self.canvas, (161, 48, 24), (x - 40, ground_y - 11, 80, 23))
            if not active:
                for bubble in range(3):
                    by = ground_y - 20 - ((int(self.elapsed * 35) + bubble * 27) % 58)
                    pygame.draw.circle(self.canvas, ORANGE, (int(x - 20 + bubble * 20), int(by)), 5 + bubble)
                continue
            height = 270 + int(math.sin(self.elapsed * 9 + index) * 45)
            flame_points = [(x - 42, ground_y), (x - 26, ground_y - height * .5), (x - 9, ground_y - height), (x + 8, ground_y - height * .72), (x + 34, ground_y - height * .35), (x + 42, ground_y)]
            pygame.draw.polygon(self.canvas, INK, flame_points)
            pygame.draw.lines(self.canvas, ORANGE, False, flame_points[1:-1], 34)
            pygame.draw.lines(self.canvas, GOLD, False, flame_points[1:-1], 15)

    def draw_industrial_castle_background(self):
        style = str(self.level_runtime.scene.get("background", "industrial_factory"))
        key = {
            "industrial_exterior": "exterior_backdrop",
            "industrial_factory": "factory_backdrop",
            "industrial_elevator": "elevator_backdrop",
            "industrial_upper": "upper_backdrop",
            "industrial_boss": "boss_backdrop",
            "industrial_balcony": "balcony_backdrop",
        }.get(style, "factory_backdrop")
        if self.level_runtime.scene_id == "factory_elevator" and self.industrial_elevator_active:
            offset = int(self.industrial_elevator_time * 205) % HEIGHT
            self.draw_level_image("industrial_castle", key, (WIDTH // 2, offset - HEIGHT // 2), HEIGHT)
            self.draw_level_image("industrial_castle", key, (WIDTH // 2, offset + HEIGHT // 2), HEIGHT)
        else:
            self.draw_level_image("industrial_castle", key, (WIDTH // 2, HEIGHT // 2), HEIGHT)

    def draw_industrial_king_rig(self, world_x, world_y=520, animation="idle", scale=.72, facing=-1, timeline=None):
        x = self.level_runtime.screen_x(float(world_x))
        y = self.world_screen_y(float(world_x), float(world_y))
        if not -220 < x < WIDTH + 220:
            return
        timeline = self.elapsed if timeline is None else float(timeline)
        if not self.draw_rig("industrial_king", animation, (x, y - 90), scale, facing, timeline):
            knight = CHARACTERS_BY_KEY.get("industrial_king", CHARACTERS_BY_KEY["conehead"])
            self.draw_knight((x, y - 60), scale, knight, facing, False, timeline * 6, weapon=None, show_shield=False)

    def draw_industrial_machine_boss(self):
        if not self.boss or self.boss.kind != "industrial_machine":
            return
        runtime = self.level_runtime
        for part in self.industrial_boss_parts.values():
            if part.get("destroyed"):
                continue
            world_x, world_y = float(part["x"]), float(part["y"])
            x, y = runtime.screen_x(world_x), self.world_screen_y(world_x, world_y)
            kind = str(part.get("kind"))
            extended = self.industrial_part_extended(part)
            if kind == "turret":
                self.draw_level_image("industrial_castle", "boss_turret", (x, y - 95), 270)
            elif kind == "hand":
                phase = self.boss.time % 7.0
                if 2.25 <= phase <= 3.5:
                    self.draw_rig("industrial_hand", "slam", (x - 105, y - 90), .72, 1, phase - 2.25)
                else:
                    self.draw_rig("industrial_hand", "idle", (x - 105, y - 90), .72, 1, self.boss.time)
            else:
                color_key = "green" if kind == "green_pole" else "blue"
                if extended:
                    self.draw_level_image(
                        "industrial_castle", f"pole_{color_key}", (x, y - 122), 265,
                    )
                else:
                    self.draw_level_image(
                        "industrial_castle", f"pole_orb_{color_key}", (x, y - 32), 112,
                    )
                if kind == "green_pole" and extended:
                    phase = (self.boss.time + float(part.get("phase", 0))) % 7.0
                    progress = max(0.0, min(1.0, (phase - 2.0) / 3.65))
                    bar = pygame.Rect(int(x - 72), int(y - 285), 144, 16)
                    pygame.draw.rect(self.canvas, INK, bar, border_radius=6)
                    pygame.draw.rect(self.canvas, GREEN, (bar.x + 4, bar.y + 4, int(136 * progress), 8), border_radius=4)
                    self.text("CHARGE", 11, CREAM, (int(x), int(y - 304)), True, 2)
            ratio = max(0.0, float(part.get("health", 0)) / max(1.0, float(part.get("max_health", 1))))
            if kind in {"blue_pole", "green_pole"}:
                bar_y = int(y - (245 if extended else 112))
            else:
                bar_y = int(y - 185)
            pygame.draw.rect(self.canvas, INK, (int(x - 48), bar_y, 96, 11), border_radius=5)
            pygame.draw.rect(self.canvas, ORANGE, (int(x - 45), bar_y + 3, int(90 * ratio), 5), border_radius=3)

    def draw_industrial_defeat_sequence(self):
        if self.industrial_phase != "boss_defeat":
            return
        t = self.industrial_phase_time
        runtime = self.level_runtime
        king_world = 1730 + max(0.0, min(1.0, (t - 1.3) / 2.2)) * 300
        animation = "scared" if t < 1.3 or t >= 4.8 else "run"
        self.draw_industrial_king_rig(king_world, 520, animation, .76, 1, t)
        princess_world = 1810 + max(0.0, min(1.0, (t - 2.0) / 2.1)) * 100
        princess_x = runtime.screen_x(princess_world)
        if t < 4.35:
            self.draw_story_character("princess_orange", (princess_x, 455), 170, -1)

        if t >= 3.0:
            arrival = max(0.0, min(1.0, (t - 3.0) / 1.5))
            crystal_x = WIDTH + 260 - arrival * 600
            crystal_y = 330 - math.sin(arrival * math.pi) * 55
            self.draw_effect_image("story", "crystal", (crystal_x, crystal_y), 280)
            cheese = CHARACTERS_BY_KEY.get("cheese_boss", CHARACTERS_BY_KEY["barbarian"])
            self.draw_knight((crystal_x, crystal_y - 104), .58, cheese, -1, False, t * 5, weapon=None, show_shield=False)
            if t >= 4.35:
                carry = max(0.0, min(1.0, (t - 4.35) / .65))
                self.draw_story_character("princess_orange", (princess_x + (crystal_x - princess_x) * carry, 455 - 75 * carry), 165, -1)
            if 5.0 <= t <= 6.25:
                jump = math.sin(max(0.0, min(1.0, (t - 5.0) / 1.25)) * math.pi)
                king_x = runtime.screen_x(2030) + jump * 160
                king_y = 500 - jump * 150
                self.draw_industrial_king_rig(runtime.camera_x + king_x, king_y + 90, "scared", .72, 1, t)
                if t >= 5.55:
                    points = self.lightning_points((int(crystal_x - 45), int(crystal_y)), (int(king_x), int(king_y - 50)), 73, 9, 24)
                    pygame.draw.lines(self.canvas, BLUE, False, points, 9)
                    pygame.draw.lines(self.canvas, CREAM, False, points, 3)

    def draw_industrial_castle_props(self):
        runtime = self.level_runtime
        if runtime.level_id != "industrial_castle":
            return
        scene_id = runtime.scene_id
        props = runtime.scene.get("props", {})
        if scene_id == "factory_exterior":
            for world_x in props.get("bushes", []):
                self.draw_level_image("industrial_castle", "bush", (runtime.screen_x(world_x), self.world_screen_y(world_x, 540)), 250)
            wall_start = float(props.get("brick_wall_start", 920))
            for world_x in range(int(wall_start), int(runtime.scene.get("world_width", 4200)) + 500, 560):
                self.draw_level_image("industrial_castle", "brick_wall", (runtime.screen_x(world_x), 315), 520)
            for index, point in enumerate(props.get("dead_guards", [])):
                self.draw_level_image("industrial_castle", "dead_guard", (runtime.screen_x(point[0]), self.world_screen_y(point[0], point[1])), 180, -1 if index % 2 else 1, -8 + index * 7)
            for index, world_x in enumerate(props.get("bounty_posters", []), 1):
                self.draw_level_image("industrial_castle", f"bounty_poster_{index}", (runtime.screen_x(world_x), 275), 235)
            balcony_range = props.get("balcony", [2650, 3690])
            if len(balcony_range) >= 2:
                balcony_center = (float(balcony_range[0]) + float(balcony_range[1])) * .5
                self.draw_level_image(
                    "industrial_castle", "exterior_balcony",
                    (runtime.screen_x(balcony_center), 340), 330,
                )
            princess_world = float(props.get("princess", 2980))
            plate_world = float(props.get("metal_plate", princess_world))
            self.draw_level_image("industrial_castle", "metal_plate", (runtime.screen_x(plate_world), 405), 105)
            broken_escape = bool(self.story_event and self.story_event.get("id") == "door_broken_escape")
            door_broken = "breakable:beefy_door" in self.scene_flags
            king_world = float(props.get("industrial_king", 3430))
            king_screen_x = runtime.screen_x(king_world)
            taunt_loop = bool(
                not door_broken
                and -180 < king_screen_x < WIDTH - 40
            )
            if not broken_escape:
                self.draw_story_character("princess_orange", (runtime.screen_x(princess_world), 320), 170, -1)
                princess_sx = runtime.screen_x(princess_world)
                for tear in range(3):
                    pygame.draw.circle(self.canvas, BLUE, (int(princess_sx + 27), 259 + tear * 15), 5)
                animation = "laugh" if taunt_loop else "idle"
                self.draw_industrial_king_rig(king_world, 405, animation, .75, -1, self.elapsed)
            if taunt_loop:
                taunt_time = self.elapsed
                segment = int(taunt_time // 2.0)
                phrase = "YOU AREN'T BEEFY ENOUGH TO BREAK THIS DOOR!" if segment % 2 == 0 else "HAHAHA   HAHAHA   HAHAHA"
                panel_x = max(20, min(WIDTH - 660, int(king_screen_x - 320)))
                panel = pygame.Rect(panel_x, 132, 640, 70)
                pygame.draw.rect(self.canvas, INK, panel, border_radius=24)
                pygame.draw.rect(self.canvas, CREAM, panel.inflate(-8, -8), border_radius=19)
                self.text(phrase, 18 if segment % 2 == 0 else 24, INK, panel.center, True)
            if broken_escape:
                t = self.story_event_time
                progress = max(0.0, min(1.0, (t - .7) / 3.45))
                king_world = 3430 + progress * 690
                princess_world = 2980 + progress * 1030
                self.draw_industrial_king_rig(king_world, 405, "scared" if t < 1.0 else "run", .75, 1, t)
                self.draw_story_character("princess_orange", (runtime.screen_x(princess_world), 320), 170, 1, -8 * progress)
        elif scene_id == "factory_floor":
            entrance = float(props.get("entrance", 100))
            self.draw_level_image("industrial_castle", "industrial_door", (runtime.screen_x(entrance), 355), 410)
            self.draw_level_image("industrial_castle", "exit_sign", (runtime.screen_x(props.get("exit_sign", 180)), 125), 115)
            for world_x in props.get("portraits", []):
                self.draw_level_image("industrial_castle", "industrial_king_portrait", (runtime.screen_x(world_x), 290 if world_x == props.get("portraits", [world_x])[0] else 215), 260)
            for world_x in props.get("tube_machines", []):
                self.draw_level_image("industrial_castle", "tube_machine", (runtime.screen_x(world_x), 395), 360)
            diagram_x = float(props.get("factory_diagram", -9999))
            self.draw_level_image("industrial_castle", "factory_diagram", (runtime.screen_x(diagram_x), 330), 410)
            for index, world_x in enumerate(props.get("poison_cannons", [])):
                self.draw_level_image("industrial_castle", "poison_cannon", (runtime.screen_x(world_x), 350 + index * 22), 220)
            pool = props.get("poison_pool", [])
            if len(pool) >= 2:
                center = (float(pool[0]) + float(pool[1])) * .5
                width = float(pool[1]) - float(pool[0])
                self.draw_level_image("industrial_castle", "poison_pool", (runtime.screen_x(center), 535), 330)
                bridge_tiles = max(1, int(width // 430))
                for index in range(bridge_tiles + 1):
                    tile_x = float(pool[0]) + index * width / bridge_tiles
                    self.draw_level_image("industrial_castle", "poison_bridge", (runtime.screen_x(tile_x), 535), 175)
            for index, world_x in enumerate(props.get("spike_bricks", [])):
                spike_y = 520 + math.sin((self.elapsed - self.scene_started_at) * 2.2 + index * math.pi) * 82
                self.draw_level_image("industrial_castle", "spike_block", (runtime.screen_x(world_x), spike_y), 170)
            for wall in props.get("electric_walls", []):
                wall_x = float(wall.get("x", 0))
                sx = runtime.screen_x(wall_x)
                self.draw_level_image("industrial_castle", "electric_post", (sx, 285), 235)
                self.draw_level_image("industrial_castle", "electric_post", (sx, 662), 235, 1, 180)
                if self.industrial_electric_active(wall):
                    points = self.lightning_points((int(sx), 280), (int(sx), 640), hash(str(wall.get("id"))) & 255, 14, 34)
                    pygame.draw.lines(self.canvas, (30, 91, 130), False, points, 16)
                    pygame.draw.lines(self.canvas, BLUE, False, points, 8)
                    pygame.draw.lines(self.canvas, CREAM, False, points, 3)
        elif scene_id == "factory_elevator":
            platform = props.get("platform", [280, 1000])
            center = (float(platform[0]) + float(platform[1])) * .5
            self.draw_level_image("industrial_castle", "elevator_platform", (runtime.screen_x(center), 590), 235)
            if not self.industrial_elevator_active:
                self.text("ALL PLAYERS ON PLATFORM", 18, GOLD, (640, 330), True, 3)
            elif "elevator_arrived" not in self.scene_flags:
                progress = min(1.0, self.industrial_elevator_time / max(.1, float(props.get("travel_time", 10.5))))
                self.text(f"RISING  {int(progress * 100)}%", 18, CREAM, (640, 330), True, 3)
        elif scene_id == "upper_factory":
            sheets_x = float(props.get("metal_sheets", 1560))
            self.draw_level_image("industrial_castle", "metal_sheets", (runtime.screen_x(sheets_x), 520), 275)
            for index, world_x in enumerate(props.get("glass_tanks", [])):
                key = ("glass_tank_red", "glass_tank_green", "glass_tank_blue")[index % 3]
                self.draw_level_image("industrial_castle", key, (runtime.screen_x(world_x), 340), 390)
        elif scene_id == "machine_core":
            for world_x in (580, 1110, 1635):
                color_key = "angry_eye"
                if self.industrial_phase == "boss_defeat" and int(self.industrial_phase_time * 7) % 2:
                    continue
                self.draw_level_image("industrial_castle", color_key, (runtime.screen_x(world_x), 235), 150)
                if self.industrial_phase == "boss_defeat":
                    gray = pygame.Surface((190, 95), pygame.SRCALPHA)
                    gray.fill((105, 108, 111, 175))
                    self.canvas.blit(gray, gray.get_rect(center=(int(runtime.screen_x(world_x)), 235)))
            glass_x = float(props.get("glass_panel", 1710))
            self.draw_level_image("industrial_castle", "arena_glass", (runtime.screen_x(glass_x), 350), 420)
            if self.industrial_phase == "boss_defeat":
                glass_sx = runtime.screen_x(glass_x)
                for offset in (-115, -30, 78):
                    pygame.draw.line(self.canvas, CREAM, (glass_sx + offset, 185), (glass_sx + offset + 55, 335), 5)
                    pygame.draw.line(self.canvas, CREAM, (glass_sx + offset + 55, 335), (glass_sx + offset + 12, 470), 4)
                    pygame.draw.line(self.canvas, (95, 210, 229), (glass_sx + offset + 52, 330), (glass_sx + offset + 108, 294), 3)
            fight_active = self.industrial_phase == "machine_fight"
            intro_active = bool(self.story_event and self.story_event.get("id") == "machine_intro")
            if intro_active and not self.boss:
                intro_t = self.story_event_time
                for raw in props.get("boss_parts", []):
                    world_x, world_y = float(raw["x"]), float(raw["y"])
                    x, y = runtime.screen_x(world_x), self.world_screen_y(world_x, world_y)
                    kind = str(raw.get("kind"))
                    rise = max(0.0, min(1.0, (intro_t - 2.0 - float(raw.get("phase", 0)) * .06) / 1.45))
                    if kind == "turret":
                        self.draw_level_image("industrial_castle", "boss_turret", (x, y + 165 - rise * 260), 270)
                    elif kind == "hand":
                        self.draw_rig("industrial_hand", "idle", (x - 105, y + 80 - rise * 170), .72, 1, intro_t)
                    else:
                        color_key = "green" if kind == "green_pole" else "blue"
                        if rise <= .02:
                            self.draw_level_image(
                                "industrial_castle", f"pole_orb_{color_key}", (x, y - 32), 112,
                            )
                        else:
                            self.draw_level_image(
                                "industrial_castle", f"pole_{color_key}",
                                (x, y + 125 - rise * 247), 265,
                            )
            for block_x in props.get("side_blocks", []):
                intro_on = intro_active and self.story_event_time >= 1.35
                if fight_active or intro_on or (self.industrial_phase == "boss_defeat" and int(self.industrial_phase_time * 8) % 2 == 0):
                    self.draw_level_image("industrial_castle", "side_damage_block", (runtime.screen_x(block_x), 430), 330)
            if self.industrial_phase not in {"boss_defeat"}:
                self.draw_industrial_king_rig(float(props.get("industrial_king", 1730)), 500, "laugh" if fight_active else "idle", .65, -1)
            self.draw_industrial_defeat_sequence()
        elif scene_id == "spyglass_balcony":
            king_world = float(props.get("industrial_king", 1030))
            if not self.industrial_king_knocked:
                self.draw_industrial_king_rig(king_world, 520, "scared", .76, -1)
                self.text("X / Y: KNOCK HIM OFF   ·   OR WALK PAST", 15, GOLD, (int(runtime.screen_x(king_world)), 300), True, 3)
            elif self.industrial_king_fall_time < 2.2:
                fall = self.industrial_king_fall_time
                self.draw_industrial_king_rig(king_world + fall * 125, 520 + fall * fall * 170, "scared", .76, 1, fall)
            if not self.industrial_spyglass_taken:
                spyglass_x = float(props.get("golden_spyglass", 1780))
                self.draw_level_image("industrial_castle", "golden_spyglass", (runtime.screen_x(spyglass_x), 465), 205)
                self.text("TOUCH THE GOLDEN SPYGLASS", 17, GOLD, (int(runtime.screen_x(spyglass_x)), 280), True, 3)

    def draw_industrial_spyglass_cutscene(self):
        if (
            self.state != "level"
            or self.level_runtime.level_id != "industrial_castle"
            or self.level_runtime.scene_id != "spyglass_balcony"
            or self.industrial_phase != "spyglass_cutscene"
            or self.industrial_phase_time >= 12.5
        ):
            return
        t = self.industrial_phase_time
        if t < 2.0:
            shade = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
            shade.fill((4, 9, 16, 150))
            self.canvas.blit(shade, (0, 0))
            self.draw_level_image("industrial_castle", "golden_spyglass", (640, 335), 330)
            self.text("GOLDEN SPYGLASS SECURED", 31, GOLD, (640, 105), True, 4)
            return
        if t < 5.0:
            pan = (t - 2.0) / 3.0
            self.draw_level_image("industrial_castle", "forest_pan", (640 - pan * 150, 360), WIDTH)
            self.text("THE VIEW SWEEPS ACROSS THE FOREST...", 22, CREAM, (640, 80), True, 3)
            return
        if t < 9.5:
            local = t - 5.0
            self.draw_level_image("industrial_castle", "ice_castle_view", (640, 360), WIDTH)
            princess_x = 640
            happy = local >= 1.0
            self.draw_story_character("princess_blue", (princess_x, 390), 165, -1)
            if not happy:
                for index in range(3):
                    pygame.draw.circle(self.canvas, BLUE, (princess_x + 28, 352 + index * 18), 5)
            else:
                self.text("!", 31, GOLD, (princess_x, 260), True, 4)
            if local >= 2.0:
                king_x = 745 - max(0.0, min(1.0, (local - 3.4) / .8)) * 75
                king = CHARACTERS_BY_KEY.get("ice", CHARACTERS_BY_KEY["barbarian"])
                self.draw_knight((king_x, 393), .66, king, -1, False, local * 4, weapon=None, show_shield=False)
                self.text("ANGRY" if local < 3.1 else "...DISAPPOINTED", 15, BLUE, (int(king_x), 255), True, 2)
                if local >= 3.4:
                    pull = max(0.0, min(1.0, (local - 3.4) / .8))
                    self.draw_story_character("princess_blue", (princess_x + pull * 105, 390), 165, 1)
            return
        shade = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
        shade.fill((5, 10, 18, 225))
        self.canvas.blit(shade, (0, 0))
        progress = min(1.0, (t - 9.5) / 1.6)
        self.text("INDUSTRIAL CASTLE COMPLETE", 31, GOLD, (640, 80), True, 4)
        width = WIDTH // max(1, len(self.players))
        for index, player in enumerate(self.players):
            center_x = width * index + width // 2
            self.text(f"P{player.slot} {player.knight.name.upper()}", 20, CREAM, (center_x, 190), True, 2)
            self.text(f"KILLS  {int(player.score * progress)}", 18, ORANGE, (center_x, 270), True)
            self.text(f"GOLD  {int(player.gold_earned * progress)}", 18, GOLD, (center_x, 325), True)
            self.text(f"EXPERIENCE  {int(player.xp_earned * progress)}", 18, TEAL, (center_x, 380), True)
        self.draw_level_image("industrial_castle", "golden_spyglass", (640, 545), 180)

    def draw_lava_world_background(self):
        runtime = self.level_runtime
        if runtime.scene_id == "wheel_chamber":
            self.draw_level_image("lava_world", "wheel_chamber_background", (WIDTH // 2, HEIGHT // 2), HEIGHT)
            return
        camera = runtime.camera_x
        self.draw_level_image("lava_world", "backdrop", (WIDTH // 2, HEIGHT // 2), HEIGHT)
        for band in range(7):
            y = 438 + band * 42
            shift = int((self.elapsed * (30 + band * 3) + band * 97) % 230)
            for x in range(-230 + shift, WIDTH + 230, 230):
                pygame.draw.arc(self.canvas, GOLD if band % 2 else ORANGE, (x, y, 185, 36), 0, math.pi, 6)
        surface = []
        bottom = []
        for sx in range(-80, WIDTH + 161, 40):
            world_x = camera + sx
            top = int(408 + self.world_elevation(world_x) - runtime.camera_y)
            surface.append((sx, top))
            bottom.append((sx, HEIGHT + 30))
        pygame.draw.polygon(self.canvas, (21, 20, 25), surface + list(reversed(bottom)))
        pygame.draw.lines(self.canvas, (77, 61, 57), False, surface, 11)
        pygame.draw.lines(self.canvas, (123, 72, 53), False, [(x, y + 10) for x, y in surface], 5)

    def draw_lava_store_background(self):
        runtime = self.level_runtime
        self.gradient(self.canvas, (38, 18, 29), (172, 58, 26))
        pygame.draw.rect(self.canvas, (52, 44, 46), (0, 135, WIDTH, 460))
        for row in range(6):
            for column in range(12):
                x = column * 122 - int(runtime.camera_x * .22) % 122 - (61 if row % 2 else 0)
                pygame.draw.rect(self.canvas, (86, 64, 59), (x, 145 + row * 70, 112, 59), 4)
        pygame.draw.rect(self.canvas, (27, 25, 29), (0, 525, WIDTH, 195))
        for offer in runtime.scene.get("shop", []):
            x = int(runtime.screen_x(float(offer["x"])))
            if not -130 < x < WIDTH + 130:
                continue
            pygame.draw.rect(self.canvas, INK, (x - 104, 345, 208, 174), border_radius=14)
            pygame.draw.rect(self.canvas, (104, 58, 42), (x - 96, 354, 192, 156), border_radius=10)
            collection = str(offer.get("collection", "items" if offer["id"] in ITEM_NAMES else "weapons"))
            self.draw_item_image(collection, offer["id"], (x, 415), 92)
            self.text(f"{offer['cost']} GOLD", 15, GOLD, (x, 492), True, 2)
        keeper_x = runtime.screen_x(float(runtime.scene.get("props", {}).get("shopkeeper", 1180)))
        if -150 < keeper_x < WIDTH + 150:
            self.draw_knight((keeper_x, 500), .72, CHARACTERS_BY_KEY.get("fire_demon", CHARACTERS_BY_KEY["barbarian"]), -1, False, self.elapsed * 4, weapon=None)

    def party_completed(self, level_id):
        return bool(self.current_characters()) and all(
            str(level_id) in self.saves.load(character).get("completed_levels", [])
            for character in self.current_characters()
        )

    def draw_dock_background(self):
        runtime = self.level_runtime
        self.gradient(self.canvas, (80, 155, 195), (238, 190, 121))
        pygame.draw.circle(self.canvas, (255, 230, 155), (1060, 90), 62)
        pygame.draw.rect(self.canvas, (42, 127, 161), (0, 355, WIDTH, 365))
        for index in range(9):
            x = (index * 180 - int(runtime.camera_x * .28)) % (WIDTH + 180) - 90
            y = 410 + int(math.sin(self.elapsed * 2 + index) * 17)
            pygame.draw.arc(self.canvas, CREAM, (x, y, 145, 32), 0, math.pi, 4)
        deck_y = 530
        pygame.draw.rect(self.canvas, INK, (0, deck_y, WIDTH, 190))
        pygame.draw.rect(self.canvas, (120, 78, 44), (0, deck_y + 8, WIDTH, 182))
        plank_shift = int(runtime.camera_x) % 150
        for x in range(-100 - plank_shift, WIDTH + 150, 150):
            pygame.draw.line(self.canvas, (73, 47, 35), (x, deck_y), (x + 35, HEIGHT), 8)
            pygame.draw.circle(self.canvas, (52, 42, 35), (x + 20, deck_y + 27), 6)
        post_shift = int(runtime.camera_x) % 420
        for x in range(-120 - post_shift, WIDTH + 300, 420):
            pygame.draw.rect(self.canvas, INK, (x, 430, 34, 290), border_radius=7)
            pygame.draw.rect(self.canvas, (91, 59, 39), (x + 7, 437, 20, 283), border_radius=5)
            pygame.draw.line(self.canvas, (177, 137, 82), (x + 17, 455), (x + 437, 455), 8)
        props = runtime.scene.get("props", {})
        for world_x, level_id, label, detail in (
            (float(props.get("golden_wheel_bubble", -9999)), "lava_world", "GOLDEN WHEEL", "LAVA WORLD"),
            (float(props.get("spyglass_bubble", -9999)), "industrial_castle", "GOLDEN SPYGLASS", "INDUSTRIAL CASTLE"),
        ):
            x = runtime.screen_x(world_x)
            if not -300 < x < WIDTH + 300:
                continue
            acquired = self.party_completed(level_id)
            bubble = pygame.Rect(int(x - 260), 100, 520, 205)
            pygame.draw.rect(self.canvas, INK, bubble, border_radius=36)
            pygame.draw.rect(self.canvas, CREAM, bubble.inflate(-10, -10), border_radius=30)
            pygame.draw.polygon(self.canvas, INK, [(x - 32, 295), (x + 26, 295), (x - 3, 353)])
            pygame.draw.polygon(self.canvas, CREAM, [(x - 23, 289), (x + 17, 289), (x - 3, 333)])
            icon_x, icon_y = x - 165, 203
            if label == "GOLDEN WHEEL":
                # This is the same editable reward texture collected at the
                # end of Lava World, not a procedural stand-in.
                self.draw_level_image("lava_world", "golden_wheel", (icon_x, icon_y), 124)
            else:
                self.draw_level_image("industrial_castle", "golden_spyglass", (icon_x, icon_y), 128)
            text_x = int(x + 65)
            self.text(label, 21, INK, (text_x, 145), True)
            status_color = GREEN if acquired else RED
            self.text("READY" if acquired else "MISSING", 20, status_color, (text_x, 198), True)
            detail_text = f"{detail} COMPLETE" if acquired else f"COMPLETE {detail}"
            self.text(detail_text, 14, status_color, (text_x, 241), True)
            self.text("REQUIREMENT CHECK", 12, (91, 91, 88), (text_x, 274), True)

        gate_world = float(props.get("requirement_gate", -9999))
        gate_x = runtime.screen_x(gate_world)
        if -220 < gate_x < WIDTH + 220:
            ready = self.party_completed("lava_world") and self.party_completed("industrial_castle")
            for side in (-1, 1):
                post_x = gate_x + side * 128
                pygame.draw.rect(self.canvas, INK, (post_x - 30, 265, 60, 270), border_radius=10)
                pygame.draw.rect(self.canvas, (105, 70, 47), (post_x - 21, 274, 42, 252), border_radius=7)
            if not ready:
                for offset in range(-105, 106, 42):
                    pygame.draw.circle(self.canvas, INK, (int(gate_x + offset), 420 + abs(offset) // 5), 18, 7)
                    if offset < 105:
                        pygame.draw.line(self.canvas, (132, 137, 137), (gate_x + offset + 12, 425 + abs(offset) // 5), (gate_x + offset + 38, 425 + abs(offset + 42) // 5), 8)
                self.text("GOLDEN WHEEL + GOLDEN SPYGLASS REQUIRED", 16, GOLD, (int(gate_x), 235), True, 3)
            else:
                pygame.draw.polygon(self.canvas, GREEN, [(gate_x, 300), (gate_x - 70, 390), (gate_x - 25, 390), (gate_x - 25, 470), (gate_x + 25, 470), (gate_x + 25, 390), (gate_x + 70, 390)])
                self.text("BOTH FOUND · CONTINUE TO THE SHIP", 16, CREAM, (int(gate_x), 235), True, 3)
        ship_x = runtime.screen_x(float(props.get("ship", 1850)))
        if -480 < ship_x < WIDTH + 480:
            pygame.draw.polygon(self.canvas, INK, [(ship_x - 340, 500), (ship_x + 350, 500), (ship_x + 245, 650), (ship_x - 245, 650)])
            pygame.draw.polygon(self.canvas, (102, 62, 38), [(ship_x - 320, 511), (ship_x + 330, 511), (ship_x + 225, 630), (ship_x - 225, 630)])
            pygame.draw.line(self.canvas, INK, (ship_x, 505), (ship_x, 160), 25)
            pygame.draw.polygon(self.canvas, (225, 220, 195), [(ship_x + 12, 180), (ship_x + 12, 430), (ship_x + 250, 370)])
            if props.get("placeholder"):
                self.text("PIRATE SHIP · COMING NEXT", 25, GOLD, (int(ship_x), 300), True, 3)

    def draw_cyclops_fortress_background(self):
        """Blackstone fortress hall that opens directly into the dirt boss yard."""
        runtime = self.level_runtime
        camera = runtime.camera_x
        props = runtime.scene.get("props", {})
        hall_end = float(props.get("fortress_end", 9650))
        self.gradient(self.canvas, (24, 16, 24), (137, 48, 26))
        pygame.draw.rect(self.canvas, (142, 42, 19), (0, 345, WIDTH, 375))
        for band in range(7):
            y = 370 + band * 47
            shift = int((self.elapsed * 38 + band * 111) % 240)
            for x in range(-240 + shift, WIDTH + 240, 240):
                pygame.draw.arc(self.canvas, ORANGE if band % 2 else GOLD, (x, y, 190, 40), 0, math.pi, 6)

        end_x = runtime.screen_x(hall_end)
        hall_right = int(max(0, min(WIDTH, end_x)))
        if hall_right > 0:
            pygame.draw.rect(self.canvas, (48, 42, 47), (0, 72, hall_right, 355))
            pygame.draw.rect(self.canvas, (27, 25, 30), (0, 0, hall_right, 102))
            row_shift = int(camera * .68) % 122
            for row in range(5):
                for x in range(-150 - row_shift - (61 if row % 2 else 0), hall_right + 140, 122):
                    pygame.draw.rect(self.canvas, (78, 68, 68), (x, 86 + row * 68, 112, 57), 4)
            pygame.draw.line(self.canvas, (112, 81, 67), (0, 422), (hall_right, 422), 10)
            pygame.draw.rect(self.canvas, (37, 35, 40), (0, 422, hall_right, HEIGHT - 422))
        if hall_right < WIDTH:
            pygame.draw.rect(self.canvas, (103, 65, 42), (hall_right, 422, WIDTH - hall_right, HEIGHT - 422))
            for index in range(14):
                x = hall_right + (index * 97 - int(camera)) % max(120, WIDTH - hall_right + 100)
                y = 465 + (index * 67) % 190
                pygame.draw.circle(self.canvas, (70, 47, 36), (int(x), y), 5 + index % 3)

        lava_world = float(props.get("lava_pool", 11930))
        lava_x = runtime.screen_x(lava_world)
        if -350 < lava_x < WIDTH + 350:
            pygame.draw.ellipse(self.canvas, INK, (lava_x - 300, 468, 600, 230))
            pygame.draw.ellipse(self.canvas, (187, 49, 20), (lava_x - 280, 487, 560, 193))
            pygame.draw.ellipse(self.canvas, ORANGE, (lava_x - 230, 518, 460, 125))
            for bubble in range(8):
                bx = lava_x - 210 + bubble * 59
                by = 553 + int(math.sin(self.elapsed * 4 + bubble) * 25)
                pygame.draw.circle(self.canvas, GOLD, (int(bx), by), 9 + bubble % 3 * 3)

    def draw_cyclops_cave_background(self):
        """Long, readable cave road used by the cart and slime encounters."""
        runtime = self.level_runtime
        camera = runtime.camera_x
        self.gradient(self.canvas, (19, 18, 29), (61, 49, 57))

        # Layered rock shelves provide motion and depth without covering the
        # playable floor in fog.
        for layer, color, speed in ((0, (48, 42, 56), .20), (1, (66, 54, 65), .42)):
            points = [(-100, 420 + layer * 35)]
            shift = int(camera * speed) % 260
            for index in range(-1, 8):
                x = index * 260 - shift
                height = 105 + ((index + layer) % 3) * 62
                points.append((x, 420 - height))
                points.append((x + 150, 375 - height // 3))
            points.extend([(WIDTH + 120, 470), (WIDTH + 120, HEIGHT), (-100, HEIGHT)])
            pygame.draw.polygon(self.canvas, color, points)

        ceiling_shift = int(camera * .35) % 310
        pygame.draw.rect(self.canvas, (36, 32, 43), (0, 0, WIDTH, 88))
        for index in range(-1, 6):
            x = index * 310 - ceiling_shift
            length = 105 + (index % 3) * 48
            pygame.draw.polygon(self.canvas, INK, [(x - 44, 52), (x + 55, 52), (x + 8, 52 + length)])
            pygame.draw.polygon(self.canvas, (63, 55, 67), [(x - 31, 57), (x + 39, 57), (x + 7, 43 + length)])

        volcano_world = float(runtime.scene.get("props", {}).get("volcano", -9999))
        # Keep the volcano in world order between the ambush and the arch; a
        # strong parallax offset made it incorrectly appear behind the exit.
        volcano_x = runtime.screen_x(volcano_world)
        if -280 < volcano_x < WIDTH + 280:
            pygame.draw.polygon(self.canvas, INK, [(volcano_x - 180, 420), (volcano_x, 236), (volcano_x + 185, 420)])
            pygame.draw.polygon(self.canvas, (87, 61, 61), [(volcano_x - 159, 420), (volcano_x, 256), (volcano_x + 163, 420)])
            pygame.draw.ellipse(self.canvas, INK, (volcano_x - 50, 238, 100, 42))
            pygame.draw.ellipse(self.canvas, ORANGE, (volcano_x - 39, 246, 78, 25))
            for ember in range(5):
                ex = int(volcano_x - 34 + ember * 17)
                ey = 225 - (ember % 3) * 25 + int(math.sin(self.elapsed * 5 + ember) * 8)
                pygame.draw.circle(self.canvas, GOLD if ember % 2 else ORANGE, (ex, ey), 5)

        pygame.draw.rect(self.canvas, (46, 39, 45), (0, 420, WIDTH, 300))
        pygame.draw.line(self.canvas, (112, 89, 78), (0, 420), (WIDTH, 420), 12)
        for index in range(18):
            world_x = math.floor(camera / 145) * 145 + index * 145
            x = int(runtime.screen_x(world_x))
            y = 475 + (index * 67) % 210
            pygame.draw.ellipse(self.canvas, (31, 29, 35), (x - 48, y - 17, 96, 34))
            pygame.draw.line(self.canvas, (79, 65, 65), (x - 25, y - 4), (x + 19, y + 5), 4)

    def draw_cyclops_cave_props(self):
        runtime = self.level_runtime
        if runtime.level_id != "cyclops_cave" or runtime.scene_id != "cave_road":
            return
        props = runtime.scene.get("props", {})

        entrance_world = float(props.get("entrance", 80))
        entrance_x = runtime.screen_x(entrance_world)
        if -220 < entrance_x < WIDTH + 220:
            pygame.draw.ellipse(self.canvas, INK, (entrance_x - 190, 178, 380, 390))
            pygame.draw.ellipse(self.canvas, (19, 19, 26), (entrance_x - 158, 207, 316, 332))
            for side in (-1, 1):
                pygame.draw.polygon(self.canvas, (83, 69, 70), [(entrance_x + side * 130, 195), (entrance_x + side * 205, 420), (entrance_x + side * 105, 420)])

        for index, world_x in enumerate(props.get("lights", [])):
            x = runtime.screen_x(float(world_x))
            if not -170 < x < WIDTH + 170:
                continue
            ground_y = self.world_screen_y(float(world_x), 535)
            glow = pygame.Surface((260, 300), pygame.SRCALPHA)
            pygame.draw.ellipse(glow, (255, 206, 76, 32), (20, 5, 220, 285))
