    def draw_winged_necromancer(self, center, scale=1.0, facing=1, casting=False):
        x, y = float(center[0]), float(center[1])
        flap = math.sin(self.elapsed * 8) * 18 * scale
        if not self.draw_level_image(
            "wizard_castle_interior", "necromancer_wings",
            (x - facing * 34 * scale, y - 78 * scale), int((310 + abs(flap)) * scale), facing,
        ):
            wing_color = (48, 37, 61)
            for side in (-1, 1):
                root_x = x - facing * 34 * scale
                tip_x = root_x + side * (125 + flap) * scale
                points = [
                    (root_x, y - 95 * scale),
                    (tip_x, y - 165 * scale),
                    (root_x + side * 92 * scale, y - 65 * scale),
                    (tip_x * .28 + root_x * .72, y + 15 * scale),
                ]
                pygame.draw.polygon(self.canvas, INK, points)
                inner = [((px * .9 + root_x * .1), (py * .9 + (y - 70 * scale) * .1)) for px, py in points]
                pygame.draw.polygon(self.canvas, wing_color, inner)
        knight = CHARACTERS_BY_KEY.get("necromancer", CHARACTERS_BY_KEY["cheese_boss"])
        self.draw_knight((x, y), .72 * scale, knight, facing, casting, self.elapsed * 7, weapon=None, show_shield=False)
        if casting:
            hand_x, hand_y = x + facing * 72 * scale, y - 82 * scale
            for radius in (52, 35, 18):
                color = (67, 25, 91) if radius == 52 else (159, 70, 202) if radius == 35 else CREAM
                pygame.draw.circle(self.canvas, color, (int(hand_x), int(hand_y)), int(radius * scale), max(3, int(7 * scale)))

    def draw_volcano_actor(self, x, y, active=True, defeated=False):
        if defeated:
            return
        if self.draw_level_image("lava_world", "volcano", (x, y - 115), 310):
            return
        points = [(x - 205, y + 40), (x - 145, y - 90), (x - 70, y - 230), (x + 66, y - 230), (x + 145, y - 90), (x + 210, y + 40)]
        pygame.draw.polygon(self.canvas, INK, points)
        inner = [(px * .94 + x * .06, py * .94 + y * .06) for px, py in points]
        pygame.draw.polygon(self.canvas, (73, 58, 55), inner)
        pygame.draw.ellipse(self.canvas, INK, (x - 80, y - 259, 160, 74))
        pygame.draw.ellipse(self.canvas, ORANGE if active else (93, 58, 47), (x - 69, y - 248, 138, 51))
        for eye_x in (x - 58, x + 58):
            pygame.draw.ellipse(self.canvas, INK, (eye_x - 24, y - 126, 48, 34))
            pygame.draw.ellipse(self.canvas, GOLD, (eye_x - 16, y - 120, 32, 22))
        pygame.draw.arc(self.canvas, INK, (x - 64, y - 82, 128, 72), 0, math.pi, 13)
        if active:
            for index in range(5):
                lava_x = x - 82 + index * 41
                lava_h = 45 + (index * 37) % 75
                pygame.draw.line(self.canvas, ORANGE, (lava_x, y - 207), (lava_x - 8, y - 207 + lava_h), 13)
                pygame.draw.line(self.canvas, GOLD, (lava_x, y - 207), (lava_x - 8, y - 207 + lava_h), 5)

    def draw_lava_world_props(self):
        runtime = self.level_runtime
        if runtime.level_id != "lava_world":
            return
        props = runtime.scene.get("props", {})
        if runtime.scene_id == "wheel_chamber":
            wheel_world = float(props.get("golden_wheel", 640))
            wheel_x = runtime.screen_x(wheel_world)
            wheel_y = self.world_screen_y(wheel_world, 450)
            finale_active = bool(self.story_event and self.story_event.get("id") == "lava_world_finale")
            if not finale_active or self.story_event_time < .35:
                self.draw_level_image("lava_world", "golden_wheel", (wheel_x, wheel_y), 240)
            return

        sign_world = float(props.get("town_sign", -9999))
        sign_x = runtime.screen_x(sign_world)
        sign_y = self.world_screen_y(sign_world, 535)
        if -260 < sign_x < WIDTH + 260:
            self.draw_level_image("lava_world", "town_sign", (sign_x, sign_y - 170), 340)

        village = props.get("village", [])
        if len(village) >= 2:
            for index, world_x in enumerate(range(int(village[0]), int(village[1]) + 1, 520)):
                x = runtime.screen_x(world_x)
                if not -210 < x < WIDTH + 210:
                    continue
                y = self.world_screen_y(world_x, 535)
                self.draw_level_image("lava_world", "town_house", (x, y - 145), 310)

        revival_seen = ("lava_world", "necromancer_revival") in self.story_events_seen
        if not revival_seen:
            for index, world_x in enumerate(props.get("revival_statues", [])):
                x = runtime.screen_x(float(world_x))
                y = self.world_screen_y(float(world_x), 535)
                if -80 < x < WIDTH + 80:
                    self.draw_level_image("lava_world", "revival_statue", (x, y - 90), 205)

        volcano = props.get("volcano", {})
        volcano_x = float(volcano.get("x", -9999))
        sx = runtime.screen_x(volcano_x)
        sy = self.world_screen_y(volcano_x, 535)
        if -280 < sx < WIDTH + 280 and not self.lava_volcano_defeated and not (self.boss and self.boss.kind == "volcano"):
            self.draw_volcano_actor(sx, sy, active=False)
        fire_sign_x = runtime.screen_x(volcano_x - 520)
        if -100 < fire_sign_x < WIDTH + 100:
            self.draw_level_image("lava_world", "fire_sign", (fire_sign_x, sy - 115), 230)

        mountain = props.get("dragon_mountain", {})
        mountain_x = float(mountain.get("x", -9999))
        mx = runtime.screen_x(mountain_x)
        my = self.world_screen_y(mountain_x, 535)
        if -760 < mx < WIDTH + 760:
            door_open = self.lava_dragon_defeated or "dragon_defeated" in self.scene_flags
            mountain_key = "dragon_mountain_open" if door_open else "dragon_mountain_closed"
            self.draw_level_image("lava_world", mountain_key, (mx, my - 345), 850)
            wheel_x = runtime.screen_x(float(mountain.get("wheel_x", mountain_x - 330)))
            wheel_y = self.world_screen_y(float(mountain.get("wheel_x", mountain_x - 330)), 130)
            self.draw_level_image("lava_world", "golden_wheel", (wheel_x, wheel_y), 160)
            if self.lava_dragon_defeated:
                head_world = float(mountain.get("head_x", mountain_x))
                head_x = runtime.screen_x(head_world)
                head_y = self.world_screen_y(head_world, 570)
                self.draw_dragon_head((head_x, head_y), .9, dead=True)

        reveal_seen = ("lava_world", "dragon_reveal") in self.story_events_seen
        reveal_playing = bool(self.story_event and self.story_event.get("id") == "dragon_reveal")
        if reveal_seen and not reveal_playing and not self.lava_dragon_defeated:
            fist_world = float(mountain.get("fist_x", mountain_x + 530))
            fist_x = runtime.screen_x(fist_world)
            fist_y = self.world_screen_y(fist_world, 515)
            raised = bool(self.boss and self.boss.kind == "dragon_head" and self.boss.open)
            if -360 < fist_x < WIDTH + 360:
                self.draw_dragon_fist((fist_x, fist_y - (165 if raised else 0)), .92, raised)

        warning_world = float(props.get("falling_rock_sign", -9999))
        warning_x = runtime.screen_x(warning_world)
        warning_y = self.world_screen_y(warning_world, 535)
        if -160 < warning_x < WIDTH + 160:
            board_x = warning_x - 205
            self.draw_level_image("lava_world", "falling_rocks_sign", (board_x, warning_y - 185), 370)

    def draw_dragon_fist(self, center, scale=1.0, raised=False):
        """Draw the red dragon's planted gate-blocking fist and attached forearm."""
        x, y = float(center[0]), float(center[1])
        if self.draw_level_image(
            "lava_world", "dragon_fist",
            (x + 120 * scale, y - 40 * scale), int(320 * scale),
        ):
            return
        red, light_red, shadow = (154, 35, 31), (207, 55, 42), (105, 25, 28)
        # The forearm visibly connects the fist back into the mountain.
        arm = [
            (x + 48 * scale, y - 30 * scale), (x + 290 * scale, y - 205 * scale),
            (x + 345 * scale, y - 105 * scale), (x + 98 * scale, y + 58 * scale),
        ]
        pygame.draw.polygon(self.canvas, INK, arm)
        inner_arm = [
            (x + 61 * scale, y - 22 * scale), (x + 286 * scale, y - 184 * scale),
            (x + 325 * scale, y - 111 * scale), (x + 91 * scale, y + 43 * scale),
        ]
        pygame.draw.polygon(self.canvas, red, inner_arm)
        pygame.draw.ellipse(self.canvas, INK, (x - 116 * scale, y - 91 * scale, 232 * scale, 180 * scale))
        pygame.draw.ellipse(self.canvas, red, (x - 104 * scale, y - 79 * scale, 208 * scale, 156 * scale))
        for index, knuckle_x in enumerate((-79, -29, 24, 75)):
            knuckle_y = y - (88 + (index in (1, 2)) * 8) * scale
            pygame.draw.circle(self.canvas, INK, (int(x + knuckle_x * scale), int(knuckle_y)), int(35 * scale))
            pygame.draw.circle(self.canvas, light_red, (int(x + knuckle_x * scale), int(knuckle_y)), int(26 * scale))
            pygame.draw.arc(
                self.canvas, shadow,
                (x + (knuckle_x - 18) * scale, knuckle_y - 13 * scale, 36 * scale, 29 * scale),
                math.pi, math.tau, max(2, int(5 * scale)),
            )
        # A curled thumb makes this read as a clenched fist rather than a blob.
        pygame.draw.ellipse(self.canvas, INK, (x - 105 * scale, y - 19 * scale, 105 * scale, 82 * scale))
        pygame.draw.ellipse(self.canvas, light_red, (x - 93 * scale, y - 8 * scale, 82 * scale, 60 * scale))
        if not raised:
            pygame.draw.ellipse(self.canvas, (77, 53, 47), (x - 132 * scale, y + 61 * scale, 264 * scale, 31 * scale))

    def draw_dragon_head(self, center, scale=1.0, dead=False):
        """Draw a red, horned dragon with a long muzzle, scales, and a toothed jaw."""
        x, y = float(center[0]), float(center[1])
        texture_key = "dragon_head_dead" if dead else "dragon_head"
        if self.draw_level_image(
            "lava_world", texture_key,
            (x, y - 140 * scale), int(420 * scale),
        ):
            return
        red = (112, 48, 43) if dead else (178, 39, 32)
        light_red = (133, 61, 52) if dead else (225, 62, 42)
        dark_red = (79, 39, 39) if dead else (107, 24, 29)

        # Neck plates and side spikes attach the head visually to the mountain.
        pygame.draw.polygon(self.canvas, INK, [
            (x - 142 * scale, y - 47 * scale), (x - 205 * scale, y + 58 * scale),
            (x + 205 * scale, y + 58 * scale), (x + 142 * scale, y - 47 * scale),
        ])
        pygame.draw.polygon(self.canvas, dark_red, [
            (x - 130 * scale, y - 48 * scale), (x - 184 * scale, y + 43 * scale),
            (x + 184 * scale, y + 43 * scale), (x + 130 * scale, y - 48 * scale),
        ])
        for side in (-1, 1):
            pygame.draw.polygon(self.canvas, INK, [
                (x + side * 145 * scale, y - 157 * scale),
                (x + side * 238 * scale, y - 205 * scale),
                (x + side * 164 * scale, y - 91 * scale),
            ])
            pygame.draw.polygon(self.canvas, (222, 176, 104), [
                (x + side * 151 * scale, y - 153 * scale),
                (x + side * 218 * scale, y - 190 * scale),
                (x + side * 163 * scale, y - 105 * scale),
            ])
            pygame.draw.polygon(self.canvas, INK, [
                (x + side * 91 * scale, y - 222 * scale),
                (x + side * 141 * scale, y - 340 * scale),
                (x + side * 51 * scale, y - 245 * scale),
            ])
            pygame.draw.polygon(self.canvas, (232, 190, 118), [
                (x + side * 91 * scale, y - 232 * scale),
                (x + side * 131 * scale, y - 316 * scale),
                (x + side * 61 * scale, y - 245 * scale),
            ])

        face_points = [
            (x - 154 * scale, y - 104 * scale), (x - 139 * scale, y - 213 * scale),
            (x - 66 * scale, y - 270 * scale), (x, y - 247 * scale),
            (x + 66 * scale, y - 270 * scale), (x + 139 * scale, y - 213 * scale),
            (x + 154 * scale, y - 104 * scale), (x + 109 * scale, y - 35 * scale),
            (x - 109 * scale, y - 35 * scale),
        ]
        pygame.draw.polygon(self.canvas, INK, face_points)
        inner_face = [(px * .94 + x * .06, py * .94 + (y - 140 * scale) * .06) for px, py in face_points]
        pygame.draw.polygon(self.canvas, red, inner_face)

        # Heavy brows, yellow slit pupils, and cheek scales.
        for side in (-1, 1):
            eye_x = x + side * 67 * scale
            pygame.draw.polygon(self.canvas, INK, [
                (eye_x - 46 * scale, y - 186 * scale), (eye_x + 40 * scale, y - 207 * scale),
                (eye_x + 31 * scale, y - 139 * scale), (eye_x - 34 * scale, y - 135 * scale),
            ])
            if not dead:
                pygame.draw.ellipse(self.canvas, GOLD, (eye_x - 29 * scale, y - 179 * scale, 58 * scale, 38 * scale))
                pygame.draw.line(self.canvas, INK, (eye_x, y - 175 * scale), (eye_x, y - 143 * scale), max(3, int(8 * scale)))
            for row in range(2):
                scale_x = eye_x + side * (38 + row * 18) * scale
                pygame.draw.arc(self.canvas, dark_red, (scale_x - 16 * scale, y + (-126 + row * 29) * scale, 32 * scale, 22 * scale), 0, math.pi, max(2, int(4 * scale)))

        # Long dragon muzzle with nostrils, open jaw, fangs, and lower chin.
        pygame.draw.ellipse(self.canvas, INK, (x - 127 * scale, y - 127 * scale, 254 * scale, 105 * scale))
        pygame.draw.ellipse(self.canvas, light_red, (x - 115 * scale, y - 117 * scale, 230 * scale, 83 * scale))
        for nostril_x in (-52, 52):
            pygame.draw.ellipse(self.canvas, INK, (x + (nostril_x - 14) * scale, y - 95 * scale, 28 * scale, 18 * scale))
        pygame.draw.ellipse(self.canvas, INK, (x - 139 * scale, y - 69 * scale, 278 * scale, 124 * scale))
        pygame.draw.ellipse(self.canvas, (35, 15, 21), (x - 126 * scale, y - 57 * scale, 252 * scale, 96 * scale))
        for tooth in range(7):
            tx = x - 101 * scale + tooth * 34 * scale
            pygame.draw.polygon(self.canvas, CREAM, [(tx, y - 51 * scale), (tx + 25 * scale, y - 51 * scale), (tx + 12 * scale, y - 10 * scale)])
        pygame.draw.arc(self.canvas, light_red, (x - 139 * scale, y - 36 * scale, 278 * scale, 104 * scale), 0, math.pi, max(8, int(21 * scale)))

    def draw_lava_world_cutscene(self):
        if not self.story_event or self.level_runtime.level_id != "lava_world":
            return
        runtime, t = self.level_runtime, self.story_event_time
        event_id = str(self.story_event.get("id"))
        if event_id == "necromancer_revival":
            travel = min(1.0, t / 3.2)
            cheese_world = 9820 + travel * 1850
            crystal_x = runtime.screen_x(cheese_world)
            crystal_y = self.world_screen_y(cheese_world, 330 - math.sin(t * 3) * 28)
            self.draw_effect_image("story", "crystal", (crystal_x, crystal_y), 310)
            cheese = CHARACTERS_BY_KEY.get("cheese_boss", CHARACTERS_BY_KEY["barbarian"])
            self.draw_knight((crystal_x, crystal_y - 105), .62, cheese, 1, False, t * 5, weapon=None, show_shield=False)
            necro_world = 9550 + min(1.0, t / 3.4) * 1400
            if t >= 3.4:
                necro_world = 10320 + min(1.0, (t - 3.4) / 1.5) * 470
            if t >= 6.6:
                necro_world = 10790 - min(1.0, (t - 6.6) / 2.2) * 1800
            nx = runtime.screen_x(necro_world)
            ny = self.world_screen_y(necro_world, 340 - math.sin(t * 4) * 25)
            casting = 4.5 <= t <= 6.8
            self.draw_winged_necromancer((nx, ny), .9, 1 if t < 6.6 else -1, casting)
            if casting:
                for index, statue_world in enumerate(runtime.scene.get("props", {}).get("revival_statues", [])):
                    sx = runtime.screen_x(float(statue_world))
                    sy = self.world_screen_y(float(statue_world), 430)
                    pygame.draw.line(self.canvas, (191, 77, 232), (nx, ny - 70), (sx, sy), 7)
                    pygame.draw.circle(self.canvas, CREAM, (int(sx), int(sy)), 8 + index % 3)
        elif event_id == "dragon_reveal":
            mountain = runtime.scene.get("props", {}).get("dragon_mountain", {})
            head_world = float(mountain.get("head_x", mountain.get("x", 24250)))
            fist_world = float(mountain.get("fist_x", mountain.get("x", 24250) + 530))
            head_x = runtime.screen_x(head_world)
            final_head_y = self.world_screen_y(head_world, 480)
            fist_x = runtime.screen_x(fist_world)
            final_fist_y = self.world_screen_y(fist_world, 515)
            if t >= 2.6:
                slam = min(1.0, (t - 2.6) / .9)
                fist_y = final_fist_y - (1.0 - slam) * 520
                self.draw_dragon_fist((fist_x, fist_y), .92, False)
            if t >= 5.2:
                rise = min(1.0, (t - 5.2) / 1.55)
                self.draw_dragon_head((head_x, final_head_y + (1.0 - rise) * 390), 1.0)
        elif event_id == "lava_world_finale":
            # First the party actually receives the Golden Wheel in its chamber.
            if t < 3.4:
                lift = min(1.0, t / 1.25)
                wheel_y = 440 - lift * 165
                wheel_height = 240 + int(math.sin(min(1.0, t / 1.6) * math.pi) * 58)
                self.draw_level_image("lava_world", "golden_wheel", (640, wheel_y), wheel_height)
                for ring in range(3):
                    radius = 125 + ring * 28 + int(math.sin(t * 7 + ring) * 8)
                    pygame.draw.circle(self.canvas, (*GOLD, max(45, 145 - ring * 35)), (640, int(wheel_y)), radius, 5)
                self.text("GOLDEN WHEEL SECURED", 25, GOLD, (640, 118), True, 3)
                if t >= 2.15:
                    fade_amount = min(255, int((t - 2.15) / 1.15 * 255))
                    fade = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
                    fade.fill((0, 0, 0, fade_amount))
                    self.canvas.blit(fade, (0, 0))
                return

            # The screen is black when this separate Cyclops area replaces the
            # wheel chamber, then fades in before either villain arrives.
            self.draw_level_image("lava_world", "cyclops_revival_background", (WIDTH // 2, HEIGHT // 2), HEIGHT)
            phase = t - 4.75
            pool_x, chair_x = 900.0, 1055.0
            if phase >= 0:
                arrival = min(1.0, phase / 2.6)
                smooth = arrival * arrival * (3.0 - 2.0 * arrival)
                crystal_x = -210 + smooth * 990
                crystal_y = 280 - math.sin(min(1.0, arrival) * math.pi) * 105 + math.sin(t * 3.2) * 12
                self.draw_effect_image("story", "crystal", (crystal_x, crystal_y), 270)
                cheese = CHARACTERS_BY_KEY.get("cheese_boss", CHARACTERS_BY_KEY["barbarian"])
                self.draw_knight((crystal_x, crystal_y - 97), .58, cheese, 1, False, phase * 5, weapon=None, show_shield=False)
                necro_x = -390 + smooth * 1015
                necro_y = 315 - math.sin(min(1.0, arrival) * math.pi) * 125 + math.sin(t * 4) * 15
                self.draw_winged_necromancer((necro_x, necro_y), .86, 1, phase >= 3.0)

            # The Necromancer breaks the lava seal only after both villains have
            # reached the pool. Purple magic gathers before the Cyclops rises.
            if phase >= 3.0:
                magic = min(1.0, (phase - 3.0) / 2.15)
                radius = 24 + int(magic * 112)
                pygame.draw.circle(self.canvas, (69, 20, 86), (int(pool_x), 548), radius, 15)
                pygame.draw.circle(self.canvas, (171, 67, 209), (int(pool_x), 548), max(9, radius // 2), 7)
                for spark in range(9):
                    angle = spark / 9 * math.tau + t * 2.7
                    spark_x = pool_x + math.cos(angle) * radius
                    spark_y = 548 + math.sin(angle) * radius * .43
                    pygame.draw.circle(self.canvas, CREAM, (int(spark_x), int(spark_y)), 5)

            if phase >= 5.45:
                # This is deliberately a full emergence, not an actor silently
                # appearing beside the pool: the hands break the lava first,
                # the body claws upward, and the dead eye ignites last.
                self.draw_cyclops_lava_revival(pool_x, pool_x, phase - 5.45)

            # Fade in from the wheel chamber transition, then fade out only
            # after the lava-eyed Cyclops is completely revived.
            if t < 4.75:
                fade_amount = max(0, int((4.75 - t) / 1.35 * 255))
                fade = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
                fade.fill((0, 0, 0, min(255, fade_amount)))
                self.canvas.blit(fade, (0, 0))
            if t >= 15.7:
                fade_amount = min(255, int((t - 15.7) / 2.1 * 255))
                fade = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
                fade.fill((0, 0, 0, fade_amount))
                self.canvas.blit(fade, (0, 0))

