        coffin_x = runtime.screen_x(coffin_world)
        if -190 < coffin_x < WIDTH + 190:
            points = [(coffin_x - 66, 520), (coffin_x - 49, 447), (coffin_x, 422), (coffin_x + 49, 447), (coffin_x + 66, 520), (coffin_x + 47, 612), (coffin_x - 47, 612)]
            pygame.draw.polygon(self.canvas, INK, points)
            inner = [(coffin_x - 53, 517), (coffin_x - 38, 457), (coffin_x, 438), (coffin_x + 38, 457), (coffin_x + 53, 517), (coffin_x + 37, 598), (coffin_x - 37, 598)]
            pygame.draw.polygon(self.canvas, (74, 48, 43), inner)
