    def draw_cyclops_knives(self, x, y, facing, scale=1.0):
        for side in (-1, 1):
            hand_x = x + side * 130 * scale
            tip_x = hand_x + facing * 92 * scale
            tip_y = y - (82 + side * 22) * scale
            pygame.draw.line(self.canvas, INK, (hand_x, y - 20 * scale), (tip_x, tip_y), max(12, int(20 * scale)))
            pygame.draw.line(self.canvas, (194, 198, 191), (hand_x, y - 20 * scale), (tip_x, tip_y), max(6, int(11 * scale)))
            pygame.draw.polygon(self.canvas, CREAM, [(tip_x + facing * 20 * scale, tip_y), (tip_x - facing * 5 * scale, tip_y - 12 * scale), (tip_x - facing * 5 * scale, tip_y + 12 * scale)])

    def draw_cyclops_cave_cutscene(self):
        if (
            not self.story_event
            or self.level_runtime.level_id != "cyclops_cave"
            or self.story_event.get("id") != "damaged_cart_repair"
        ):
            return
        runtime = self.level_runtime
        t = self.story_event_time
        cart_world = float(runtime.scene.get("props", {}).get("damaged_cart", 1740))
        notice = t >= 2.15
        thief_positions = ((-145, 500), (-45, 580), (70, 490), (155, 570))
        for index, (offset, ground_y) in enumerate(thief_positions):
            world_x = cart_world + offset
            x = runtime.screen_x(world_x)
            y = self.world_screen_y(world_x, ground_y)
            facing = -1 if notice else (1 if offset < 0 else -1)
            self.draw_knight((x, y - 58), .57, CHARACTERS_BY_KEY["thief"], facing, False, t * 2.5 + index, weapon=None, show_shield=False)
            self.draw_bag_head(int(x), int(y), 1.0)
            if not notice:
                pygame.draw.line(self.canvas, INK, (x + facing * 24, y - 54), (x + facing * 63, y - 10), 8)
                pygame.draw.line(self.canvas, (158, 160, 151), (x + facing * 24, y - 54), (x + facing * 63, y - 10), 4)
            else:
                self.text("!", 26, GOLD, (int(x), int(y - 205)), True, 3)

        if 3.05 <= t <= 7.15:
            for index in range(7):
                progress = max(0.0, min(1.0, (t - 3.1 - index * .18) / 2.15))
                progress = progress * progress * (3.0 - 2.0 * progress)
                world_x = -120 + progress * (430 + index * 42)
                world_y = 445 + (index % 3) * 62
                x = runtime.screen_x(world_x)
                y = self.world_screen_y(world_x, world_y)
                self.draw_knight((x, y - 58), .62, CHARACTERS_BY_KEY["conehead"], 1, False, t * 10 + index, weapon="lightsaber", show_shield=False)

    def draw_parade_cart(self, offset_x=0.0, show_team=False):
        xoff = int(offset_x)
        wheel_turn = self.parade_scroll * .08
        # Twenty horses: ten advancing pairs with royal guards in their saddles.
        if show_team:
            for column in range(10):
                for row in range(2):
                    horse_x = xoff + 760 + column * 112
                    horse_y = 500 + row * 92
                    self.draw_horse_actor((horse_x, horse_y), .53, 1, wheel_turn + column * .7 + row)
                    self.draw_knight(
                        (horse_x, horse_y - 72), .34, CHARACTERS_BY_KEY["conehead"], 1,
                        False, wheel_turn + column, weapon="lightsaber", show_shield=False,
                    )
            for row in range(2):
                pygame.draw.line(self.canvas, (91, 60, 38), (xoff + 735, 515 + row * 70), (xoff + 1030, 545 + row * 20), 7)

        # Static cart art comes from a generated PNG; animated wheels, riders,
        # horses, and balloons remain separate runtime layers.
        cart_texture = self.textures.story.get("parade_cart")
        if cart_texture:
            self.canvas.blit(cart_texture, (xoff, 410))
        else:
            pygame.draw.rect(self.canvas, INK, (xoff + 30, 411, 1080, 227), border_radius=15)
            pygame.draw.rect(self.canvas, (179, 105, 63), (xoff + 41, 420, 1058, 209), border_radius=11)

        # Front passenger deck: the one-eyed Cyclops who escaped the wedding
        # rides beside the white princess. The dead Conehead groom is not here.
        self.draw_cyclops_actor((xoff + 825, 525), .48, 1)
        pygame.draw.line(self.canvas, (91, 190, 239), (xoff + 843, 426), (xoff + 850, 452), 6)
        self.draw_white_princess((xoff + 1000, 490), .56, False, -1, True)

        for wheel_x in (120, 425, 760, 1045):
            pygame.draw.circle(self.canvas, INK, (xoff + wheel_x, 637), 48)
            pygame.draw.circle(self.canvas, (102, 61, 40), (xoff + wheel_x, 637), 38)
            for spoke in range(6):
                angle = wheel_turn + spoke * math.tau / 6
                pygame.draw.line(self.canvas, GOLD, (xoff + wheel_x, 637), (xoff + wheel_x + int(math.cos(angle) * 31), 637 + int(math.sin(angle) * 31)), 5)

        # Balloon bundle is tied to the mirrored rear on the left.
        knot = (xoff + 68, 476)
        for dx, dy, color in (
            (-18, -165, (237, 76, 87)), (22, -205, (243, 198, 57)), (60, -153, (95, 188, 218)),
            (95, -213, (211, 101, 184)), (132, -160, (240, 135, 67)),
        ):
            pygame.draw.line(self.canvas, CREAM, knot, (xoff + 68 + dx, 476 + dy), 2)
            pygame.draw.ellipse(self.canvas, INK, (xoff + 38 + dx, 425 + dy, 60, 77))
            pygame.draw.ellipse(self.canvas, color, (xoff + 46 + dx, 433 + dy, 44, 61))

    def draw_parade_intro(self):
        t = self.parade_time
        cart_offset = -1500 + min(t, 6.5) * 240
        self.draw_parade_cart(cart_offset, show_team=True)
        if t < 7.7:
            return
        window_x, window_y = 250, 122
        # Four cannons push through the newly shattered church window.
        for index in range(4):
            cannon_x = window_x - 108 + index * 72
            pygame.draw.line(self.canvas, INK, (cannon_x, window_y + 32), (cannon_x - 48, window_y + 112), 26)
            pygame.draw.line(self.canvas, (79, 84, 91), (cannon_x, window_y + 32), (cannon_x - 48, window_y + 112), 16)
        for index in range(14):
            angle = index * math.tau / 14
            distance = min(150, max(0, int((t - 7.7) * 170)))
            shard_x = window_x + math.cos(angle) * distance
            shard_y = window_y + math.sin(angle) * distance
            pygame.draw.polygon(self.canvas, (190, 235, 242), [(shard_x, shard_y - 8), (shard_x + 10, shard_y + 5), (shard_x - 6, shard_y + 10)])
        for index, player in enumerate(self.players):
            progress = max(0.0, min(1.0, (t - 8.15 - index * .16) / 2.4))
            if progress <= 0:
                continue
            start_x = window_x - 105 + index * 70
            target_x = 330 + index * 92
            x = start_x + (target_x - start_x) * progress
            y = window_y + 95 + (410 - (window_y + 95)) * progress - math.sin(progress * math.pi) * 270
            self.draw_knight((x, y), .58, player.knight, -1, False, t * 10, player.slot, player.weapon)

    def draw_parade_swinger(self):
        x = int(self.level_runtime.screen_x(self.parade_swing_x))
        y = 225 + int(math.sin(self.parade_scroll * .015) * 52)
        pygame.draw.line(self.canvas, INK, (x - 75, -20), (x, y - 80), 7)
        pygame.draw.line(self.canvas, (111, 74, 42), (x - 75, -20), (x, y - 80), 3)
        self.draw_knight((x, y), .48, CHARACTERS_BY_KEY["thief"], -1, False, self.elapsed * 8, weapon=None, show_shield=False)
        self.draw_bag_head(x, y + 58, .7)
        pygame.draw.circle(self.canvas, INK, (x + 48, y - 20), 19)
        pygame.draw.circle(self.canvas, (57, 59, 62), (x + 48, y - 20), 13)
        pygame.draw.line(self.canvas, ORANGE, (x + 56, y - 35), (x + 65, y - 52), 4)

    def draw_parade_boss(self):
        if not self.boss:
            return
        defeated = self.parade_phase == "victory" or self.boss.dead
        x, y = int(self.level_runtime.screen_x(self.boss.x)), 520
        self.draw_troll_mother((x, y), .78, self.boss.time * 4.0, .25, defeated=defeated)
        if not defeated and self.parade_laser_time > 0:
            charge = min(1.0, self.parade_laser_time / .82)
            head_x, eye_y = x + 33, 394
            beam_color = (255, 224, 104) if self.parade_laser_time < .82 else (255, 61, 57)
            width = max(3, int(5 + charge * 15))
            for eye_x, target_y in ((head_x - 36, 455), (head_x + 36, 535)):
                pygame.draw.line(self.canvas, INK, (eye_x, eye_y), (WIDTH - 30, target_y), width + 9)
                pygame.draw.line(self.canvas, beam_color, (eye_x, eye_y), (WIDTH - 30, target_y), width)
                pygame.draw.line(self.canvas, CREAM, (eye_x, eye_y), (WIDTH - 30, target_y), max(2, width // 4))
            self.text("HIT IT NOW!", 18, RED, (350, 165), True, 3)
        if not defeated:
            bar = pygame.Rect(300, 628, 680, 30)
            pygame.draw.rect(self.canvas, INK, bar, border_radius=12)
            pygame.draw.rect(self.canvas, (77, 33, 31), bar.inflate(-6, -6), border_radius=9)
            ratio = max(0.0, self.boss.health / max(1, self.boss.max_health))
            pygame.draw.rect(self.canvas, ORANGE, (bar.x + 5, bar.y + 5, int((bar.width - 10) * ratio), bar.height - 10), border_radius=8)
            self.text("TROLL MOTHER", 15, CREAM, bar.center, True, 2)

    def draw_parade_action(self):
        if self.parade_phase == "intro":
            self.draw_parade_intro()
            return
        camera_offset = -float(self.level_runtime.camera_x)
        cart_offset = min(1500.0, self.parade_time * 1800.0) if self.parade_phase == "cave" else camera_offset
        if self.parade_phase != "cave" or cart_offset < 1250:
            self.draw_parade_cart(cart_offset)
        for rider in self.parade_horse_guards:
            x, y = self.level_runtime.screen_x(rider["x"]), rider["y"]
            self.draw_horse_actor((x, y), .65, 1, rider["time"] * 11)
            self.draw_knight((x, y - 88), .42, CHARACTERS_BY_KEY["conehead"], 1, False, rider["time"] * 10, weapon="lightsaber", show_shield=False)
        if self.parade_phase in {"thieves", "boss"}:
            self.draw_parade_swinger()
        for enemy in sorted(self.enemies, key=lambda item: item.y):
            self.draw_enemy(enemy, self.level_runtime.screen_x(enemy.x), enemy.display_y())
        self.draw_parade_boss()
        self.draw_combat_effects()
        self.draw_level_players()
        if self.parade_phase == "guards":
            remaining = max(0, int(float(self.level_runtime.scene.get("guard_duration", 60)) - self.parade_time) + 1)
            self.text(f"DEFEND THE CART · {remaining}s", 17, GOLD, (640, 86), True, 2)
        elif self.parade_phase == "boss":
            self.text("RANGED ATTACKS ONLY · BOW OR PROJECTILE MAGIC", 15, GOLD, (640, 88), True, 2)

    def pirate_view_shift(self):
        if self.pirate_phase != "intro":
            return 0.0
        duration = max(.01, float(self.level_runtime.scene.get("intro_duration", 7.5)))
        progress = max(0.0, min(1.0, self.pirate_time / duration))
        smooth = progress * progress * (3.0 - 2.0 * progress)
        return 165.0 * (1.0 - smooth)

    def pirate_deck_offset(self, x):
        return math.tan(math.radians(self.pirate_roll)) * (float(x) - WIDTH * .5)

    def pirate_enemy_ship_pose(self):
        phase, t = self.pirate_phase, self.pirate_time
        if phase == "intro":
            return None
        if phase == "approach":
            duration = max(.01, float(self.level_runtime.scene.get("approach_duration", 9.0)))
            progress = max(0.0, min(1.0, t / duration))
            smooth = progress * progress * (3.0 - 2.0 * progress)
            return 1180.0 - smooth * 320.0, 358.0, .48 + smooth * .34, math.sin(t * 1.4) * 2.0
        if phase == "evasive":
            duration = max(.01, float(self.level_runtime.scene.get("evasive_duration", 4.5)))
            progress = max(0.0, min(1.0, t / duration))
            return 860.0 - progress * 1580.0, 355.0, .82, -progress * 5.0
        if phase == "parallel":
            duration = max(.01, float(self.level_runtime.scene.get("parallel_duration", 5.0)))
            progress = max(0.0, min(1.0, t / duration))
            smooth = progress * progress * (3.0 - 2.0 * progress)
            return -620.0 + smooth * 1560.0, 352.0, .82, math.sin(t * 1.3) * 2.0
        if phase == "battle":
            return 940.0 + math.sin(self.pirate_total_time * .7) * 18.0, 352.0, .82, math.sin(self.pirate_total_time * 1.3) * 2.0
        if phase == "sinking":
            if t < 2.1:
                progress = t / 2.1
                angle, sink = -22.0 * progress, 0.0
            elif t < 4.25:
                progress = (t - 2.1) / 2.15
                angle, sink = -22.0 - 68.0 * progress, 0.0
            else:
                progress = (t - 4.25) / max(.01, float(self.level_runtime.scene.get("sinking_duration", 7.5)) - 4.25)
                angle, sink = -90.0, progress * 620.0
            return 940.0, 352.0 + sink, .82, angle
        return None

    def draw_pirate_enemy_ship(self):
        pose = self.pirate_enemy_ship_pose()
        if pose is None:
            return
        x, y, scale, angle = pose
        mast_height = int(480 * scale)
        self.draw_level_image("pirate_ship", "mast", (x, y - 225 * scale), mast_height, angle=angle)
        self.draw_level_image("pirate_ship", "pirate_sail", (x + 28 * scale, y - 245 * scale), int(340 * scale), angle=angle)
        self.draw_level_image("pirate_ship", "enemy_ship_hull", (x, y), int(255 * scale), angle=angle)

        if self.pirate_phase in {"parallel", "battle"}:
            pirate = CHARACTERS_BY_KEY.get("pirate", CHARACTERS_BY_KEY["thief"])
            for index in range(5):
                px = x - 205 * scale + index * 102 * scale
                py = y - 78 * scale + abs(math.sin(self.pirate_total_time * 7 + index)) * 13
                self.draw_knight(
                    (px, py), .34 * scale, pirate, 1 if index % 2 else -1,
                    False, self.pirate_total_time * 9 + index, weapon="rusty_sword", show_shield=False,
                )

        if self.pirate_phase == "approach" and self.pirate_time >= 2.1:
            burst = int(self.pirate_time / .58)
            for index in range(3):
                bx = x + ((burst * 83 + index * 177) % 460 - 230) * scale
                by = y - (35 + ((burst + index) % 3) * 52) * scale
                pulse = .72 + abs(math.sin(self.pirate_time * 8 + index)) * .42
                self.draw_level_image("pirate_ship", "explosion", (bx, by), int(125 * scale * pulse), angle=index * 31)

    def draw_pirate_ship_background(self):
        self.draw_level_image("pirate_ship", "sea_backdrop", (WIDTH // 2, HEIGHT // 2), HEIGHT)
        for index in range(6):
            wave_x = ((index * 270 - self.pirate_total_time * (55 + index % 2 * 28)) % 1640) - 180
            wave_y = 330 + (index % 3) * 54 + math.sin(self.pirate_total_time * 2 + index) * 9
            self.draw_level_image("pirate_ship", "wave", (wave_x, wave_y), 80 + (index % 2) * 20)

        self.draw_pirate_enemy_ship()
        shift = self.pirate_view_shift()
        roll = self.pirate_roll
        sail_bob = math.sin(self.pirate_total_time * 1.9) * 7.0
        self.draw_level_image("pirate_ship", "mast", (640, 280 + shift), 650, angle=roll)
        self.draw_level_image("pirate_ship", "rope", (410, 285 + shift), 520, angle=roll - 4)
        self.draw_level_image("pirate_ship", "rope", (870, 285 + shift), 520, angle=roll + 4)
        self.draw_level_image("pirate_ship", "sail", (640, 235 + shift + sail_bob), 350, angle=roll + math.sin(self.pirate_total_time * 2.4) * 1.2)
        self.draw_level_image("pirate_ship", "crow_nest", (640, 76 + shift), 100, angle=roll)
        self.draw_level_image("pirate_ship", "back_cabin", (185, 485 + shift), 250, angle=roll)
        self.draw_level_image("pirate_ship", "raised_deck", (1080, 500 + shift), 225, angle=roll)
        self.draw_level_image("pirate_ship", "player_ship_hull", (640, 655 + shift), 335, angle=roll)

        guard = CHARACTERS_BY_KEY.get("royal_guard", CHARACTERS_BY_KEY["barbarian"])
        guard_y = 47 + shift + self.pirate_deck_offset(640)
        self.draw_knight((640, guard_y), .44, guard, 1, False, self.pirate_total_time * 2.2, weapon=None, show_shield=False)
        self.draw_level_image("pirate_ship", "spyglass", (690, guard_y - 55), 52, facing=1, angle=-16)

        for index in range(6):
            wave_x = ((index * 245 + self.pirate_total_time * (85 + index % 2 * 18)) % 1590) - 155
            wave_y = 650 + (index % 2) * 34 + math.sin(self.pirate_total_time * 2.5 + index) * 11
            self.draw_level_image("pirate_ship", "wave", (wave_x, wave_y), 105 + (index % 2) * 22)

    def draw_pirate_ship_action(self):
        shift = self.pirate_view_shift()
        if self.pirate_phase == "intro" and self.pirate_time < 3.9:
            return
        for enemy in sorted(self.enemies, key=lambda item: item.y):
            y = enemy.display_y() + self.pirate_deck_offset(enemy.x) + shift
            self.draw_enemy(enemy, enemy.x, y)
        self.draw_combat_effects()
        for player in sorted(self.players, key=lambda item: item.y):
            x = self.level_runtime.screen_x(player.x)
            self.draw_following_pet(player, x)
            rider_height = player.mount.seat_height if player.mount is not None else 0
            y = player.y - rider_height + self.pirate_deck_offset(player.x) + shift
            self.draw_player_character(player, x, y, 58 if player.buried_hits else 0)
            self.draw_pickup_bubble(player)
        if self.pirate_phase == "battle":
            remaining = max(0, math.ceil(float(self.level_runtime.scene.get("battle_duration", 60.0)) - self.pirate_time))
            caption = f"PIRATE RAID · {remaining}s" if remaining else "DEFEAT THE LAST BOARDERS"
            self.text(caption, 18, GOLD, (640, 186), True, 3)
        elif self.pirate_phase == "sinking":
            self.text("PIRATE SHIP DEFEATED", 20, GOLD, (640, 190), True, 3)

    def draw_wizard_particles(self, vertical_speed=0.0):
        for index in range(22):
            speed = 16 + index % 5 * 7
            x = (index * 149 + self.elapsed * speed) % (WIDTH + 120) - 60
            y = (index * 97 + self.elapsed * vertical_speed) % (HEIGHT + 140) - 70
            size = 20 + index % 4 * 7
            self.draw_level_image("wizard_castle_takeoff", "purple_particle", (x, y), size)

    def wizard_island_offset(self):
        if self.wizard_phase != "cutscene":
            return 0.0
        progress = max(0.0, min(1.0, (self.wizard_time - 3.1) / 3.4))
        smooth = progress * progress * (3.0 - 2.0 * progress)
        return -900.0 * smooth

    def draw_wizard_takeoff_background(self):
        runtime, scene = self.level_runtime, self.level_runtime.scene
        if runtime.level_id == "wizard_castle_interior":
            self.draw_level_image("wizard_castle_takeoff", "interior_backdrop", (WIDTH // 2, HEIGHT // 2), HEIGHT)
            return
        if runtime.scene_id == "castle_landing":
            self.draw_level_image("wizard_castle_takeoff", "landing_backdrop", (WIDTH // 2, HEIGHT // 2), HEIGHT)
            self.draw_wizard_particles(-9.0)
            entrance_x = runtime.screen_x(float(scene.get("props", {}).get("castle_entrance", 1510)))
            self.draw_level_image("wizard_castle_takeoff", "castle_entrance", (entrance_x, 370), 535)
            return
        if self.wizard_phase == "flight":
            self.draw_level_image("wizard_castle_takeoff", "flight_backdrop", (WIDTH // 2, HEIGHT // 2), HEIGHT)
            self.draw_wizard_particles(175.0)
            duration = float(scene.get("flight_duration", 30.0))
            reveal = max(0.0, min(1.0, (self.wizard_time - duration + 4.0) / 4.0))
            if reveal > 0:
                smooth = reveal * reveal * (3.0 - 2.0 * reveal)
                island_y = -330 + smooth * 450
                self.draw_level_image("wizard_castle_takeoff", "floating_island_bottom", (640, island_y), 345)
                self.draw_level_image("wizard_castle_takeoff", "castle_entrance", (640, island_y - 250), 375)
            return

        self.draw_level_image("wizard_castle_takeoff", "village_backdrop", (WIDTH // 2, HEIGHT // 2), HEIGHT)
        self.draw_wizard_particles(-12.0)
        props = scene.get("props", {})
        for index, world_x in enumerate(props.get("broken_houses", [])):
            screen_x = runtime.screen_x(float(world_x))
            self.draw_level_image("wizard_castle_takeoff", "broken_house", (screen_x, 382), 365, -1 if index % 2 else 1)
        for index, world_x in enumerate(props.get("skeletons", [])):
            screen_x = runtime.screen_x(float(world_x))
            skeleton = CHARACTERS_BY_KEY.get("skeleton", CHARACTERS_BY_KEY["barbarian"])
            self.draw_knight((screen_x, 535), .56, skeleton, -1 if index % 2 else 1, False, 0, weapon=None, dead=True, show_shield=False)
        for world_x in props.get("purple_crystals", []):
            self.draw_level_image("wizard_castle_takeoff", "purple_crystal", (runtime.screen_x(float(world_x)), 485), 190)
        well_x = float(props.get("well", 2870))
        self.draw_level_image("wizard_castle_takeoff", "broken_well", (runtime.screen_x(well_x), 495), 205)

        cave_x = float(props.get("crystal_cave", 4620))
        island_offset = self.wizard_island_offset()
        self.draw_level_image("wizard_castle_takeoff", "floating_island_bottom", (runtime.screen_x(cave_x), 650 + island_offset), 420)
        self.draw_level_image("wizard_castle_takeoff", "green_crystal_cave", (runtime.screen_x(cave_x), 350 + island_offset), 505)
        seam_x = runtime.screen_x(float(props.get("takeoff_seam", 3740)))
        pygame.draw.line(self.canvas, INK, (seam_x, 455), (seam_x, 710), 12)
        pygame.draw.line(self.canvas, (151, 83, 190), (seam_x + 6, 455), (seam_x + 6, 710), 4)

    def draw_spinning_wizard_player(self, player, x, y, angle):
        sprite = pygame.Surface((330, 330), pygame.SRCALPHA)
        old_canvas = self.canvas
        self.canvas = sprite
        self.draw_knight((165, 245), .68, player.knight, player.facing, False, self.elapsed * 8, player.slot, player.weapon, show_shield=False)
        self.canvas = old_canvas
        rotated = pygame.transform.rotate(sprite, -float(angle))
        self.canvas.blit(rotated, rotated.get_rect(center=(int(x), int(y))))

    def draw_wizard_takeoff_lineup(self):
        runtime = self.level_runtime
        props = runtime.scene.get("props", {})
        base = float(props.get("boss_line", 4300))
        offset = self.wizard_island_offset()
        cheese = CHARACTERS_BY_KEY.get("cheese_boss", CHARACTERS_BY_KEY["barbarian"])
        necromancer = CHARACTERS_BY_KEY.get("necromancer", CHARACTERS_BY_KEY["barbarian"])
        painter = CHARACTERS_BY_KEY.get("painter_boss", CHARACTERS_BY_KEY["barbarian"])
        cheese_x = runtime.screen_x(base)
        self.draw_knight((cheese_x, 510 + offset), .69, cheese, -1, False, self.wizard_time * 2, weapon="magic_wand", show_shield=False)
        necro_x = runtime.screen_x(base + 155)
        self.draw_knight((necro_x, 390 + offset), .65, necromancer, -1, False, self.wizard_time * 4, weapon=None, show_shield=False)
        cyclops_x = runtime.screen_x(base + 330)
        self.draw_level_image("wizard_castle_takeoff", "giant_coffin", (cyclops_x - 62, 420 + offset), 225, facing=-1, angle=-8)
        self.draw_cyclops_actor((cyclops_x + 28, 520 + offset), .56, -1, crying=False)
        painter_x = runtime.screen_x(base + 565)
        self.draw_knight((painter_x, 520 + offset), .68, painter, -1, False, self.wizard_time * 3, weapon="paintbrush", show_shield=False)
        self.draw_story_character("princess_orange", (painter_x + 82, 380 + offset), 145, -1)

    def draw_wizard_takeoff_action(self):
        runtime, scene = self.level_runtime, self.level_runtime.scene
        if runtime.scene_id == "castle_landing":
            self.draw_level_players()
            self.text("ENTER THE GREEN CRYSTAL GATE", 17, GOLD, (640, 182), True, 3)
            return
        if self.wizard_phase in {"ground", "cutscene"}:
            if self.wizard_phase == "cutscene":
                self.draw_wizard_takeoff_lineup()
            self.draw_level_players()
            return
        if self.wizard_phase != "flight":
            return
        for debris in self.wizard_debris:
            self.draw_level_image(
                "wizard_castle_takeoff", debris["kind"],
                (debris["x"], debris["y"]),
                130 if debris["kind"] == "debris_wheel" else 105,
                angle=debris["angle"],
            )
        entry = min(1.0, self.wizard_time / 2.4)
        for index, player in enumerate(self.players):
            x = float(self.wizard_flight_x.get(player.spec.key, 380 + index * 150))
            target_y = player.y
            y = HEIGHT + 120 + (target_y - HEIGHT - 120) * entry
            angle = float(self.wizard_flight_spin.get(player.spec.key, 0.0))
            self.draw_spinning_wizard_player(player, x, y, angle)
        remaining = max(0, math.ceil(float(scene.get("flight_duration", 30.0)) - self.wizard_time))
        self.text(f"DODGE THE FLYING DEBRIS · {remaining}s", 23, GOLD, (640, 92), True, 3)
        self.text("MOVE LEFT / RIGHT · A / D OR LEFT STICK", 15, CREAM, (640, 125), True, 2)

    def draw_wizard_interior_background(self):
        runtime = self.level_runtime
        key = {
            "crystal_hall": "crystal_hall_backdrop",
            "portal_hub": "portal_hub_backdrop",
            "painter_arena": "painter_arena_backdrop",
            "crystal_room_one": "crystal_room_backdrop",
            "crystal_room_two": "crystal_room_backdrop",
            "crystal_room_three": "crystal_room_backdrop",
            "cyclops_arena": "cyclops_arena_backdrop",
            "necromancer_arena": "necromancer_arena_backdrop",
            "final_approach": "final_approach_backdrop",
            "final_arena": "final_arena_backdrop",
            "final_celebration": "celebration_backdrop",
        }.get(runtime.scene_id, "crystal_hall_backdrop")
        world_width = int(runtime.scene.get("world_width", WIDTH))
        first = int(runtime.camera_x // WIDTH) * WIDTH
        for world_x in range(first - WIDTH, world_width + WIDTH, WIDTH):
            screen_x = runtime.screen_x(world_x + WIDTH / 2)
            self.draw_level_image("wizard_castle_interior", key, (screen_x, HEIGHT // 2), HEIGHT)
        self.draw_wizard_particles(-8.0)

    def draw_wizard_final_background(self):
        runtime = self.level_runtime
        if runtime.scene_id == "castle_barracks":
            self.draw_level_image("wizard_castle_final", "castle_barracks_backdrop", (640, 360), 720)
            return
        if self.final_phase == "approach":
            lift_progress = 0.0
        elif self.final_phase == "lift":
            raw = min(1.0, self.final_time / 8.0)
            lift_progress = raw * raw * (3.0 - 2.0 * raw)
        else:
            lift_progress = 1.0
        # One tall backdrop makes the green lift chamber, dark shaft, and
        # arena a single continuous scene.  Moving it downward is the camera
        # travelling upward with the lift rather than a scene cut.
        backdrop_center_y = -60 + lift_progress * 840
        self.draw_level_image("wizard_castle_final", "vertical_crystal_backdrop", (640, backdrop_center_y), 1560)
        if self.final_phase in {"collapse", "escape"}:
            self.draw_wizard_particles(-18.0)

    def draw_wizard_interior_props(self):
        runtime = self.level_runtime
        if runtime.level_id == "wizard_castle_final":
            if runtime.scene_id == "castle_barracks":
                self.draw_wizard_celebration()
            elif self.final_phase in {"approach", "lift"}:
                self.draw_wizard_final_approach()
            else:
                self.draw_wizard_final_encounter()
            return
        if runtime.level_id != "wizard_castle_interior":
            return
        props = runtime.scene.get("props", {})
        for world_x, world_y, height in props.get("purple_flames", []):
            key = "purple_flame_tall" if float(height) >= 250 else "purple_flame"
            self.draw_level_image("wizard_castle_interior", key, (runtime.screen_x(float(world_x)), float(world_y) - float(height) * .45), int(height))
        if runtime.scene_id == "crystal_hall":
            for world_x in props.get("steel_tables", []):
                self.draw_level_image("wizard_castle_interior", "steel_table", (runtime.screen_x(float(world_x)), 500), 185)
            for world_x, facing in props.get("steel_chairs", []):
                self.draw_level_image("wizard_castle_interior", "steel_chair", (runtime.screen_x(float(world_x)), 520), 145, int(facing))
            for world_x in props.get("wall_skeletons", []):
                self.draw_level_image("wizard_castle_interior", "wall_skeleton", (runtime.screen_x(float(world_x)), 330), 310)
            for world_x in props.get("stairs", []):
                self.draw_level_image("wizard_castle_interior", "blocked_stairs", (runtime.screen_x(float(world_x)), 404), 330)
            house_x = runtime.screen_x(float(props.get("broken_house", 2000)))
            self.draw_level_image("wizard_castle_interior", "floating_house", (house_x, 370), 330)
            for index, (world_x, world_y) in enumerate(props.get("floating_house_pieces", [])):
                self.draw_level_image("wizard_castle_interior", f"floating_plank_{index % 3 + 1}", (runtime.screen_x(float(world_x)), float(world_y)), 95, angle=math.sin(self.elapsed * 1.6 + index) * 9)
            stone_x = runtime.screen_x(float(props.get("floating_stone", 3650)))
            self.draw_level_image("wizard_castle_interior", "floating_stone", (stone_x, 395 + math.sin(self.elapsed * 1.5) * 8), 270)
            for index in range(7):
                angle = self.elapsed * (.35 + index * .025) + index * math.tau / 7
                self.draw_level_image("wizard_castle_interior", "orbit_stone", (stone_x + math.cos(angle) * 170, 390 + math.sin(angle) * 105), 48, angle=self.elapsed * 40 + index * 22)
            sky_start, sky_end = props.get("sky_hole", [4440, 2480])
            sky_x = (float(sky_start) + float(sky_end)) * .5
            sky_width = abs(float(sky_start) - float(sky_end))
            self.draw_level_image("wizard_castle_interior", "sky_hole", (runtime.screen_x(sky_x), 300), max(290, int(sky_width * .5)))
            self.draw_level_image("wizard_castle_interior", "skeleton_crystal", (runtime.screen_x(float(props.get("skeleton_crystal", 5350))), 350), 390)
            self.draw_level_image("wizard_castle_interior", "wood_house", (runtime.screen_x(float(props.get("wood_house", 5840))), 390), 350)
            self.draw_level_image("wizard_castle_interior", "crystal_arch", (runtime.screen_x(float(props.get("arch", 6550))), 345), 510)
        elif runtime.scene_id == "portal_hub":
            unlocked = set(self.saves.wizard_portals())
            for index, (world_x, portal_id) in enumerate(props.get("portals", []), 1):
                open_portal = str(portal_id) in unlocked
                key = "portal_open" if open_portal else "portal_locked"
                x = runtime.screen_x(float(world_x))
                self.draw_level_image("wizard_castle_interior", key, (x, 385), 355)
                self.text(str(index), 24, CREAM if open_portal else MUTED, (int(x), 535), True, 3)
                self.text("OPEN" if open_portal else "LOCKED", 12, GOLD if open_portal else MUTED, (int(x), 565), True, 2)
        elif runtime.scene_id == "painter_arena":
            self.draw_painter_encounter()
        elif runtime.scene_id == "cyclops_arena":
            self.draw_wizard_cyclops_encounter()
        elif runtime.scene_id == "necromancer_arena":
            self.draw_wizard_necromancer_encounter()

    def draw_painter_encounter(self):
        runtime = self.level_runtime
        props = runtime.scene.get("props", {})
        for world_x in range(320, 3340, 390):
            self.draw_level_image("wizard_castle_interior", f"wall_canvas_{world_x // 390 % 4 + 1}", (runtime.screen_x(world_x), 245), 205)
        tv_x = runtime.screen_x(float(props.get("tv", 700)))
        self.draw_level_image("wizard_castle_interior", "paint_tv", (tv_x, 410), 205)
        self.draw_level_image("wizard_castle_interior", "painted_guys", (tv_x, 400), 118, angle=math.sin(self.elapsed * 5) * 3)
        self.draw_level_image("wizard_castle_interior", "purple_rug", (runtime.screen_x(float(props.get("rug", 1780))), 585), 145)
        self.draw_level_image("wizard_castle_interior", "giant_canvas", (runtime.screen_x(float(props.get("canvas", 2050))), 295), 390)
        painter_x = runtime.screen_x(2250)
        if self.painter_phase != "waiting" and self.boss is not None:
            if self.painter_phase == "intro":
                progress = max(0.0, min(1.0, self.painter_time / 3.1))
                painter_y = -60 + progress * 575
            elif self.painter_phase == "paintings":
                painter_y = 165
            else:
                painter_y = 510
            self.draw_level_image("wizard_castle_interior", "painter_lift", (painter_x, painter_y + 48), 180)
            painter = CHARACTERS_BY_KEY.get("painter_boss", CHARACTERS_BY_KEY["barbarian"])
            self.draw_knight(
                (painter_x, painter_y), .82, painter, -1,
                self.painter_phase == "drawing", self.elapsed * 4,
                weapon="paintbrush", dead=self.painter_phase in {"death", "exit"}, show_shield=False,
            )
            if int(self.elapsed * 5) % 2 == 0 and self.painter_phase in {"intro", "drawing", "death"}:
                self.draw_level_image("wizard_castle_interior", "painter_toolbox_open", (painter_x, painter_y - 146), 105)
        for painting in list(self.painter_paintings) + list(self.painter_crossings):
            x = runtime.screen_x(float(painting["x"]))
            if -160 < x < WIDTH + 160:
                bob = math.sin(self.elapsed * 6 + float(painting["x"]) * .01) * 9
                self.draw_level_image("wizard_castle_interior", f"painting_{painting['name']}", (x, float(painting["y"]) - 80 + bob), 190, int(painting.get("facing", 1)))
                if not painting.get("crossing"):
                    ratio = max(0.0, float(painting["health"]) / max(1.0, float(painting["max_health"])))
                    pygame.draw.rect(self.canvas, INK, (int(x - 65), int(painting["y"] + 18), 130, 11), border_radius=5)
                    pygame.draw.rect(self.canvas, ORANGE, (int(x - 61), int(painting["y"] + 22), int(122 * ratio), 4), border_radius=2)
        if self.painter_chest and not self.painter_chest.get("broken"):
            self.draw_level_image("wizard_castle_interior", "painter_chest", (runtime.screen_x(self.painter_chest["x"]), self.painter_chest["y"] - 45), 155)
        for loot in self.painter_loot:
            self.draw_level_image("wizard_castle_interior", f"loot_{loot['kind']}", (runtime.screen_x(loot["x"]), loot["y"] - 25), 62)
        if self.painter_exit_open:
            screens = props.get("screens", [3820, 4070])
            eagle_key = "screen_eagle_open" if int(self.elapsed * 3) % 2 else "screen_eagle_closed"
            worm_key = f"screen_worm_{int(self.elapsed * 3) % 3}"
            self.draw_level_image("wizard_castle_interior", eagle_key, (runtime.screen_x(float(screens[0])), 375), 225)
            self.draw_level_image("wizard_castle_interior", worm_key, (runtime.screen_x(float(screens[1])), 375), 225)
            self.draw_level_image("wizard_castle_interior", "exit_stairs", (runtime.screen_x(float(props.get("stairs", 4400))), 410), 385)
        if self.boss is not None and self.painter_phase not in {"waiting", "death", "exit"}:
            bar = pygame.Rect(340, 624, 600, 34)
            pygame.draw.rect(self.canvas, INK, bar, border_radius=13)
            ratio = max(0.0, self.boss.health / max(1, self.boss.max_health))
            pygame.draw.rect(self.canvas, (111, 39, 102), bar.inflate(-6, -6), border_radius=10)
            pygame.draw.rect(self.canvas, (219, 91, 213), (bar.x + 5, bar.y + 5, int((bar.width - 10) * ratio), bar.height - 10), border_radius=9)
            self.text("PAINTER BOSS", 16, CREAM, bar.center, True, 2)

    def draw_custom_wizard_boss_bar(self, name, color=(211, 74, 80)):
        if not self.boss or self.boss.dead:
            return
        bar = pygame.Rect(330, 624, 620, 34)
        pygame.draw.rect(self.canvas, INK, bar, border_radius=13)
        pygame.draw.rect(self.canvas, (71, 30, 39), bar.inflate(-6, -6), border_radius=10)
        ratio = max(0.0, self.boss.health / max(1, self.boss.max_health))
        pygame.draw.rect(self.canvas, color, (bar.x + 5, bar.y + 5, int((bar.width - 10) * ratio), bar.height - 10), border_radius=9)
        self.text(name, 16, CREAM, bar.center, True, 2)

    def draw_wizard_cyclops_actor(self, world_x, world_y, phase=None, time_value=0.0, ghost=False):
        x = self.level_runtime.screen_x(float(world_x))
        y = float(world_y)
        facing = self.boss.facing if self.boss else -1
        if ghost:
            self.draw_level_image("wizard_castle_interior", "cyclops_ghost", (x, y - 130), 320, facing)
            return
        bounce = abs(math.sin(time_value * 4.2)) * 85 if phase == "buddy" else 0
        swing = math.sin(time_value * 8) * 58 if phase == "chase" else -18
        self.draw_level_image("wizard_castle_interior", "cyclops_body", (x, y - 105 - bounce), 330, facing)
        self.draw_level_image("wizard_castle_interior", "cyclops_head", (x, y - 285 - bounce), 215, facing)
        self.draw_level_image("wizard_castle_interior", "cyclops_arm", (x + facing * 105, y - 115 - bounce), 185, facing, swing * facing)
        coffin_y = y - 105 if phase == "buddy" else y - 75 - bounce
        coffin_angle = 4 if phase == "buddy" else swing * facing
        self.draw_level_image("wizard_castle_interior", "cyclops_coffin", (x - facing * 135, coffin_y), 360, facing, coffin_angle)

    def draw_wizard_cyclops_encounter(self):
        runtime, props = self.level_runtime, self.level_runtime.scene.get("props", {})
        for index, world_x in enumerate(props.get("red_crystals", [])):
            self.draw_level_image("wizard_castle_interior", "red_ground_crystal", (runtime.screen_x(float(world_x)), 515), 210 + index % 2 * 55, -1 if index % 2 else 1)
        for index, world_x in enumerate(props.get("bones", [])):
            self.draw_level_image("wizard_castle_interior", "giant_bones", (runtime.screen_x(float(world_x)), 345), 350, -1 if index % 2 else 1)
        self.draw_level_image("wizard_castle_interior", "golden_entrance", (runtime.screen_x(float(props.get("golden_entrance", 250))), 350), 510, -1)
        hatch_x = runtime.screen_x(float(props.get("hatch", 1720)))
        hatch_open = self.wizard_cyclops_phase not in {"approach"}
        self.draw_level_image("wizard_castle_interior", "brown_hatch_open" if hatch_open else "brown_hatch_closed", (hatch_x, 560), 190)
        if self.wizard_cyclops_exit_open:
            self.draw_level_image("wizard_castle_interior", "golden_exit", (runtime.screen_x(float(props.get("golden_exit", 3570))), 350), 510)
        if self.boss:
            if self.wizard_cyclops_phase == "intro":
                amount = max(0.0, min(1.0, (self.wizard_cyclops_time - .8) / 2.7))
                self.draw_wizard_cyclops_actor(self.boss.x, 750 - amount * 225, "intro", self.wizard_cyclops_time)
            elif self.wizard_cyclops_phase == "death":
                if self.wizard_cyclops_time < 2.6:
                    fall = min(1.0, self.wizard_cyclops_time / 1.5)
                    self.draw_wizard_cyclops_actor(self.boss.x, 520 + fall * 90, "death", self.wizard_cyclops_time)
                if self.wizard_cyclops_time >= 3.0:
                    rise = (self.wizard_cyclops_time - 3.0) * 105
                    self.draw_wizard_cyclops_actor(self.boss.x - 60, 430 - rise, ghost=True)
                    self.draw_level_image("wizard_castle_interior", "buddy_ghost", (runtime.screen_x(self.boss.x + 100), 300 - rise), 210)
            else:
                self.draw_wizard_cyclops_actor(self.boss.x, self.boss.y, self.wizard_cyclops_phase, self.wizard_cyclops_time)
        buddy = self.wizard_cyclops_buddy
        if buddy:
            skeleton = CHARACTERS_BY_KEY.get("skeleton", CHARACTERS_BY_KEY["barbarian"])
            self.draw_knight((runtime.screen_x(buddy["x"]), buddy["y"]), .78, skeleton, int(buddy["facing"]), True, self.elapsed * 7, weapon=None, show_shield=False)
            self.draw_level_image("wizard_castle_interior", "buddy_clothes", (runtime.screen_x(buddy["x"]), buddy["y"] - 65), 155, int(buddy["facing"]))
        if self.wizard_cyclops_chest:
            chest_key = "boss_chest_open" if self.wizard_cyclops_chest.get("broken") else "boss_chest"
            self.draw_level_image("wizard_castle_interior", chest_key, (runtime.screen_x(self.wizard_cyclops_chest["x"]), self.wizard_cyclops_chest["y"] - 48), 175)
        for loot in self.wizard_cyclops_loot:
            if loot.get("picked"):
                continue
            x, y = runtime.screen_x(loot["x"]), loot["y"]
            if loot["kind"] == "coin":
                pygame.draw.circle(self.canvas, INK, (int(x), int(y)), 13)
                pygame.draw.circle(self.canvas, GOLD, (int(x), int(y)), 9)
            elif loot["kind"] == "gold_bag":
                self.draw_gold_bag((x, y), .62)
            else:
                pygame.draw.polygon(self.canvas, INK, [(x, y - 20), (x + 17, y - 5), (x + 10, y + 18), (x - 10, y + 18), (x - 17, y - 5)])
                pygame.draw.polygon(self.canvas, TEAL, [(x, y - 14), (x + 11, y - 3), (x + 7, y + 12), (x - 7, y + 12), (x - 11, y - 3)])
        if self.wizard_cyclops_phase in {"chase", "fire", "buddy"}:
            self.draw_custom_wizard_boss_bar("THE CYCLOPS", (203, 111, 57))

    def draw_wizard_necromancer_encounter(self):
        runtime, props = self.level_runtime, self.level_runtime.scene.get("props", {})
        point = float(props.get("summoning_point", 1720))
        for world_x in range(250, 3300, 245):
            self.draw_level_image("wizard_castle_interior", f"corpse_pile_{world_x // 245 % 3 + 1}", (runtime.screen_x(world_x), 565), 145, -1 if world_x // 245 % 2 else 1)
        if self.necro_exit_open:
            self.draw_level_image("wizard_castle_interior", "golden_exit", (runtime.screen_x(float(props.get("golden_exit", 3210))), 350), 510)
        for laser in self.necro_summon_lasers:
            pulse = 1.0 + math.sin(laser["time"] * 22) * .09
            self.draw_level_image(
                "wizard_castle_interior", "necromancer_summon_laser",
                (runtime.screen_x(laser["x"]), 300), int(650 * pulse),
            )
        necro = CHARACTERS_BY_KEY.get("necromancer", CHARACTERS_BY_KEY["barbarian"])
        if self.necro_phase == "summoning":
            y = 275 + math.sin(self.elapsed * 2.8) * 26
            self.draw_knight((runtime.screen_x(point), y), .9, necro, -1, False, self.elapsed * 4, weapon="necromancer_sword", show_shield=False)
            self.draw_level_image("wizard_castle_interior", "necromancer_wings", (runtime.screen_x(point), y - 80), 310)
            for index in range(10):
                angle = self.elapsed * 3 + index * math.tau / 10
                self.draw_level_image("wizard_castle_interior", "soul_particle", (runtime.screen_x(point) + math.cos(angle) * 125, y - 50 + math.sin(angle) * 80), 38)
        elif self.boss:
            if self.necro_phase == "descent":
                progress = min(1.0, self.necro_time / 2.8)
                y = 250 + progress * 270
            elif self.necro_phase == "death":
                y = 500 - self.necro_time * 185
            else:
                y = self.boss.y
            if self.necro_phase != "death" or y > -220:
                self.draw_knight(
                    (runtime.screen_x(self.boss.x), y), .98, necro, self.boss.facing,
                    self.necro_phase == "duel", self.elapsed * 6,
                    weapon=None if self.necro_phase == "death" else "necromancer_sword",
                    show_shield=False,
                )
            if self.necro_phase == "death":
                for index in range(6):
                    trail_y = y + 105 + index * 42
                    self.draw_level_image("wizard_castle_interior", "fart_cloud", (runtime.screen_x(self.boss.x) + math.sin(index * 4) * 35, trail_y), 95)
                if .55 <= self.necro_time < 3.4:
                    progress = min(1.0, (self.necro_time - .55) / 2.4)
                    sword_y = y + 30 + (535 - (y + 30)) * progress
                    self.draw_item_image("weapons", "necromancer_sword", (runtime.screen_x(self.boss.x), sword_y), 170, 1, 0)
        for hand in self.necro_hands:
            key = "skeleton_hand_warning" if hand["time"] < .72 else "skeleton_hand"
            self.draw_level_image("wizard_castle_interior", key, (runtime.screen_x(hand["x"]), hand["y"] - 45), 165)
        for bomb in self.necro_bombs:
            self.draw_level_image("wizard_castle_interior", "skeleton_bomb", (runtime.screen_x(bomb["x"]), bomb["y"]), 95, angle=bomb["time"] * 260)
        if self.necro_phase == "duel":
            self.draw_custom_wizard_boss_bar("NECROMANCER", (139, 68, 185))
        elif self.necro_phase == "summoning":
            self.text(f"SOUL GAUNTLET  {self.necro_roster_index}/{len(self.necro_roster)}", 17, (220, 130, 255), (640, 190), True, 3)

    def draw_wizard_final_approach(self):
        runtime = self.level_runtime
        pad_x = runtime.screen_x(float(runtime.scene.get("props", {}).get("lift_pad", 930)))
        self.draw_level_image("wizard_castle_interior", "gray_lift_pad", (pad_x, 570), 220)

    def draw_wizard_final_actor(self, x, y, dead=False, weapon=None, reaching=False, attacking=False):
        boss = CHARACTERS_BY_KEY.get("cheese_boss", CHARACTERS_BY_KEY["barbarian"])
        self.draw_knight(
            (x, y), 1.02, boss, self.boss.facing if self.boss else -1,
            attacking, self.elapsed * 7, weapon=weapon, dead=dead,
            raising=reaching, show_shield=False,
        )

    def draw_wizard_final_crystal_throne(self):
        """Draw the stolen, user-painted crystal as the boss's platform."""
        return self.draw_effect_image("story", "crystal", (640, 490), 340, 1, 90)

    def draw_wizard_final_encounter(self):
        phase = self.final_phase
        throne_x = 640
        if phase == "reveal":
            illumination = max(0.0, min(1.0, (self.final_time - .8) / 3.2))
            darkness = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
            darkness.fill((0, 0, 5, int(248 * (1.0 - illumination))))
            self.canvas.blit(darkness, (0, 0))
            glow = pygame.Surface((620, 430), pygame.SRCALPHA)
            glow_alpha = int(45 + 150 * max(0.0, min(1.0, self.final_time / 1.6)))
            pygame.draw.ellipse(glow, (165, 67, 225, glow_alpha), (25, 45, 570, 330))
            self.canvas.blit(glow, glow.get_rect(center=(640, 430)))
            self.draw_wizard_final_crystal_throne()
            particle_count = int(22 * max(0.0, min(1.0, (self.final_time - 1.25) / 2.2)))
            for index in range(particle_count):
                angle = self.elapsed * (.7 + index % 4 * .12) + index * math.tau / 22
                self.draw_level_image(
                    "wizard_castle_interior", "soul_particle",
                    (640 + math.cos(angle) * (170 + index % 3 * 75), 355 + math.sin(angle) * (95 + index % 4 * 28)),
                    34 + index % 3 * 8,
                )
            if self.final_time >= 2.05:
                y = 190 + math.sin(self.elapsed * 2) * 8
                self.draw_wizard_final_actor(throne_x, y)
        elif phase != "escape" and not (phase == "collapse" and self.final_time >= 5.0):
            self.draw_wizard_final_crystal_throne()
        if phase == "crystals":
            y = 190 + math.sin(self.elapsed * 2) * 8
            self.draw_wizard_final_actor(throne_x, y)
        for crystal in self.final_crystals:
            if crystal["health"] <= 0:
                continue
            self.draw_level_image("wizard_castle_interior", "final_red_crystal", (crystal["x"], crystal["y"] - 75), 190, angle=crystal["angle"] * 57.2958)
            if self.final_crystal_state == "landed" and crystal["id"] == self.final_active_crystal_id:
                ratio = crystal["health"] / crystal["max_health"]
                pygame.draw.rect(self.canvas, INK, (int(crystal["x"] - 46), int(crystal["y"] + 22), 92, 9), border_radius=4)
                pygame.draw.rect(self.canvas, RED, (int(crystal["x"] - 43), int(crystal["y"] + 25), int(86 * ratio), 3), border_radius=2)
        if phase in {"shield_transform", "shield", "final_transform", "final_normal", "collapse", "escape"} and self.boss:
            if phase not in {"collapse", "escape"}:
                if phase == "shield":
                    self.draw_wizard_final_actor(
                        self.boss.x, self.boss.y, weapon="magic_wand",
                        attacking=self.final_attack_timer < .28,
                    )
                elif phase == "final_transform":
                    self.draw_wizard_final_actor(self.boss.x, self.boss.y, reaching=True)
                elif phase == "final_normal":
                    meteor_cast = 4.2 <= self.final_time % 11.5 < 7.4
                    self.draw_wizard_final_actor(
                        self.boss.x, self.boss.y,
                        weapon=None if meteor_cast else "moon_blade",
                        reaching=meteor_cast,
                        attacking=not meteor_cast,
                    )
                    if meteor_cast:
                        hand_x = self.boss.x + 30 * self.boss.facing
                        self.draw_item_image("weapons", "moon_blade", (hand_x, self.boss.y - 180), 175, 1, 0)
                else:
                    self.draw_wizard_final_actor(self.boss.x, self.boss.y)
            if phase == "shield":
                key = "bubble_blue" if self.boss.open else "bubble_red"
                self.draw_level_image("wizard_castle_interior", key, (self.boss.x, self.boss.y - 92), 330)
                self.text("PROJECTILES" if self.boss.open else "MELEE", 14, BLUE if self.boss.open else RED, (int(self.boss.x), int(self.boss.y - 270)), True, 2)
            if phase == "final_transform":
                sword_progress = max(0.0, min(1.0, (self.final_time - .55) / 3.6))
                smooth = sword_progress * sword_progress * (3.0 - 2.0 * sword_progress)
                sword_y = -150 + (self.boss.y - 175 + 150) * smooth
                hand_x = self.boss.x + 30 * self.boss.facing
                self.draw_item_image("weapons", "moon_blade", (hand_x, sword_y), 175, 1, 0)
                if self.final_time >= 3.45:
                    self.draw_level_image("wizard_castle_interior", "red_sky_laser", (self.boss.x, 185), 520)
        if phase in {"ball_transform_one", "ball_one", "ball_two"} and self.boss:
            self.draw_level_image("wizard_castle_interior", "final_ball", (self.boss.x, self.boss.y - 110), 265, angle=self.final_time * 260)
        if phase == "chest" and self.boss and (not self.final_chest or self.final_chest["y"] < 440):
            self.draw_wizard_final_actor(self.boss.x, 555, dead=True)
        if self.final_chest and not self.final_chest.get("broken"):
            self.draw_level_image("wizard_castle_interior", "boss_chest", (self.final_chest["x"], self.final_chest["y"] - 48), 175)
        if phase in {"triangle", "triangle_death"} and self.boss:
            x, y = self.boss.x, self.boss.y - 120
            if phase == "triangle_death" and self.final_time >= 2.45:
                self.draw_level_image("wizard_castle_interior", "final_ball_white", (x, y), 265, angle=self.final_time * 280)
            else:
                white = phase == "triangle_death" and int(self.final_time * 8) % 2 == 0
                shake_x = math.sin(self.final_time * 42) * 12 if phase == "triangle_death" else 0
                swing = math.sin((1.0 - self.final_triangle_swing / .52) * math.pi) if self.final_triangle_swing > 0 else 0.0
                for index in range(7):
                    angle = -90 + index * (360 / 7)
                    radians = math.radians(angle)
                    reach = 100 + swing * 72
                    arm_x, arm_y = x + shake_x + math.cos(radians) * reach, y + math.sin(radians) * reach * .72
                    self.draw_level_image(
                        "wizard_castle_interior",
                        "triangle_small_arm_white" if white else "triangle_small_arm",
                        (arm_x, arm_y), 92, angle=angle,
                    )
                self.draw_level_image("wizard_castle_interior", "triangle_core_white" if white else "triangle_core", (x + shake_x, y), 300, angle=math.sin(self.final_time * 3) * 7)
        for orb in self.final_white_orbs:
            self.draw_level_image("wizard_castle_interior", "white_orb_large" if orb["large"] else "white_orb_small", (orb["x"], orb["y"]), 95 if orb["large"] else 45)
        for meteor in self.final_meteors:
            if meteor["time"] < meteor["delay"]:
                self.draw_level_image("wizard_castle_interior", "meteor_target", (meteor["x"], meteor["y"] + 15), 135)
                fall = meteor["time"] / meteor["delay"]
                self.draw_level_image("wizard_castle_interior", "final_meteor", (meteor["x"], -80 + fall * (meteor["y"] + 40)), 145, angle=self.elapsed * 180)
        if phase in {"collapse", "escape"}:
            if phase == "collapse" and self.final_time < 5.0:
                drift_x = 640 + math.sin(self.final_time * 1.5) * 85
                self.draw_wizard_final_actor(drift_x, 510 - self.final_time * 82, dead=True)
                self.draw_level_image("wizard_castle_interior", "crumbling_floor", (640, 625), 270)
            if phase == "collapse" and self.final_time >= 5.0:
                rise = max(0.0, min(1.0, (self.final_time - 5.0) / 1.4))
                smooth = rise * rise * (3.0 - 2.0 * rise)
                crystal_y = 820 + (535 - 820) * smooth
                self.draw_effect_image("story", "crystal", (640, crystal_y), 390)
            elif phase == "escape":
                self.draw_effect_image("story", "crystal", (640, 535), 390)
            if phase == "escape" and self.final_crystal_winner:
                self.draw_story_character("princess_orange", (640, 335), 150, -1)
        if phase not in {"reveal", "shield_transform", "ball_transform_one", "chest", "triangle_death", "final_transform", "collapse", "escape"}:
            label = {
                "crystals": "FINAL BOSS · CRYSTALS", "shield": "FINAL BOSS · SHIELD",
                "ball_one": "FINAL BOSS · CHAOS BALL", "triangle": "FINAL BOSS · TRIANGLE",
                "ball_two": "FINAL BOSS · CHAOS BALL", "final_normal": "FINAL BOSS · SWORD",
            }.get(phase, "FINAL BOSS")
            self.draw_custom_wizard_boss_bar(label, (198, 47, 71))

    def draw_wizard_celebration(self):
        phase = self.final_celebration_phase
        if phase in {"funny", "end_fade", "end_card"}:
            # Once the kiss fades to white, the barracks, players, and HUD do
            # not return.  The gag reel lives entirely on this white stage.
            self.canvas.fill((255, 255, 255))
        if phase == "funny":
            for index in range(9):
                x = ((index * 165 + self.final_celebration_time * 240) % 1540) - 130
                y = 205 if index % 2 else 600
                self.draw_level_image("wizard_castle_interior", "party_penguin", (x, y), 105, 1 if index % 2 else -1)
            for index in range(5):
                x = ((index * 290 - self.final_celebration_time * 330) % 1600) - 160
                y = 250 + abs(math.sin(self.final_celebration_time * 2 + index)) * 250
                self.draw_item_image("pets", "cat", (x, y), 125, -1, self.final_celebration_time * 280 + index * 35)
            return
        if phase == "end_fade":
            progress = min(1.0, self.final_celebration_time / 2.4)
            color = tuple(int(255 + (INK[index] - 255) * progress) for index in range(3))
            self.text("THE END", 72, color, (640, 330), True, 0)
            pygame.draw.line(self.canvas, color, (470, 390), (810, 390), 9)
            return
        if phase == "end_card":
            self.text("THE END", 72, INK, (640, 330), True, 0)
            pygame.draw.line(self.canvas, INK, (470, 390), (810, 390), 9)
            return
        crowd = ["barbarian", "thief", "conehead", "fire_demon", "skeleton", "snakey", "cult_minion", "pirate"]
        for index, key in enumerate(crowd):
            knight = CHARACTERS_BY_KEY.get(key, CHARACTERS_BY_KEY["barbarian"])
            x = 95 + index * 150
            self.draw_knight((x, 365 + index % 2 * 35), .48, knight, 1 if index < 4 else -1, False, self.elapsed * 5 + index, weapon=None, show_shield=False)
        king = CHARACTERS_BY_KEY.get("king", CHARACTERS_BY_KEY["royal_guard"])
        descent = min(1.0, self.final_celebration_time / 1.8) if self.final_celebration_phase == "party" else 1.0
        king_y = -170 + (470 + 170) * descent
        princess_y = -190 + (405 + 190) * descent
        self.draw_knight((760, king_y), .78, king, 1, False, self.elapsed * 2, weapon=None, show_shield=False)
        self.draw_story_character("princess_orange", (850, princess_y), 165, -1)
        if self.final_celebration_phase == "party":
            self.text("THE KINGDOM CELEBRATES", 24, GOLD, (640, 190), True, 3)
        elif self.final_celebration_phase == "duel":
            self.text("LAST KNIGHT STANDING KISSES THE ORANGE PRINCESS", 18, GOLD, (640, 190), True, 3)
        elif self.final_celebration_phase == "kiss":
            self.text("TOUCH THE ORANGE PRINCESS", 20, GOLD, (640, 190), True, 3)

    def draw_wizard_final_white_fade(self):
        alpha = int(255 * min(1.0, self.final_celebration_time / 1.6))
        white = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
        white.fill((255, 255, 255, alpha))
        self.canvas.blit(white, (0, 0))

    def draw_catapult(self, world_x, world_y=540, loaded=False, arm_angle=-38):
        x = int(self.level_runtime.screen_x(world_x))
        y = int(self.world_screen_y(world_x, world_y))
        if x < -180 or x > WIDTH + 180:
            return
        frame = max(0, min(7, int(round((float(arm_angle) + 80.0) / 100.0 * 7))))
        loaded_key = "loaded" if loaded else "empty"
        if self.draw_art_image(f"props/catapult_{loaded_key}_{frame}", (x, y), 640):
            return
        for wheel_x in (-55, 55):
            pygame.draw.circle(self.canvas, INK, (x + wheel_x, y), 37)
            pygame.draw.circle(self.canvas, (111, 70, 39), (x + wheel_x, y), 29)
            pygame.draw.circle(self.canvas, INK, (x + wheel_x, y), 9)
        pygame.draw.rect(self.canvas, INK, (x - 92, y - 38, 184, 40), border_radius=8)
        pygame.draw.rect(self.canvas, (138, 88, 44), (x - 84, y - 30, 168, 25), border_radius=6)
        angle = math.radians(arm_angle)
        end = (x + int(math.cos(angle) * 155), y - 20 + int(math.sin(angle) * 155))
        pygame.draw.line(self.canvas, INK, (x - 35, y - 25), end, 21)
        pygame.draw.line(self.canvas, (157, 99, 48), (x - 35, y - 25), end, 12)
        pygame.draw.circle(self.canvas, INK, end, 31)
        pygame.draw.circle(self.canvas, (91, 58, 39), end, 23)
        if loaded:
            pygame.draw.circle(self.canvas, (66, 67, 70), end, 17)

    def draw_white_princess(self, center, scale=1.0, happy=False, facing=-1, crying=False):
        art_key = "actors/white_princess_happy" if happy else ("actors/white_princess_crying" if crying else "actors/white_princess")
        if self.draw_art_image(art_key, center, 640 * scale, facing):
            return
        x, y = int(center[0]), int(center[1])
        pygame.draw.polygon(self.canvas, INK, [(x, y - int(52 * scale)), (x - int(58 * scale), y + int(70 * scale)), (x + int(58 * scale), y + int(70 * scale))])
        pygame.draw.polygon(self.canvas, (240, 237, 224), [(x, y - int(43 * scale)), (x - int(48 * scale), y + int(61 * scale)), (x + int(48 * scale), y + int(61 * scale))])
        pygame.draw.circle(self.canvas, INK, (x, y - int(86 * scale)), max(20, int(36 * scale)))
        pygame.draw.circle(self.canvas, (239, 199, 158), (x, y - int(86 * scale)), max(16, int(29 * scale)))
        pygame.draw.arc(self.canvas, (237, 226, 208), (x - int(39 * scale), y - int(128 * scale), int(78 * scale), int(62 * scale)), math.pi, math.tau, max(8, int(13 * scale)))
        eye_x = x + facing * int(8 * scale)
        pygame.draw.circle(self.canvas, INK, (eye_x, y - int(91 * scale)), max(2, int(4 * scale)))
        mouth_rect = (x - int(10 * scale), y - int(80 * scale), int(20 * scale), int(12 * scale))
        pygame.draw.arc(self.canvas, (116, 47, 54), mouth_rect, 0 if happy else math.pi, math.pi if happy else math.tau, max(2, int(3 * scale)))
        if crying:
            pygame.draw.line(self.canvas, (78, 180, 231), (eye_x, y - int(84 * scale)), (eye_x, y - int(65 * scale)), max(2, int(4 * scale)))
        pygame.draw.circle(self.canvas, GOLD, (x, y - int(128 * scale)), max(6, int(10 * scale)))

    def draw_cyclops_actor(self, center, scale=1.0, facing=1, carrying_guard=False, carrying_princess=False, crying=True):
        if not carrying_guard and not carrying_princess:
            art_key = "actors/cyclops_crying" if crying else "actors/cyclops_angry"
            if self.draw_art_image(art_key, center, 640 * scale, facing):
                return
        x, y = int(center[0]), int(center[1])
        pygame.draw.ellipse(self.canvas, (5, 10, 15, 90), (x - int(90 * scale), y + int(45 * scale), int(180 * scale), int(28 * scale)))
        pygame.draw.ellipse(self.canvas, INK, (x - int(92 * scale), y - int(180 * scale), int(184 * scale), int(235 * scale)))
        pygame.draw.ellipse(self.canvas, (97, 77, 66), (x - int(82 * scale), y - int(170 * scale), int(164 * scale), int(215 * scale)))
        pygame.draw.circle(self.canvas, CREAM, (x + facing * int(15 * scale), y - int(105 * scale)), max(20, int(35 * scale)))
        pygame.draw.circle(self.canvas, INK, (x + facing * int(20 * scale), y - int(105 * scale)), max(8, int(13 * scale)))
        if crying:
            pygame.draw.line(self.canvas, (77, 172, 225), (x + facing * int(18 * scale), y - int(73 * scale)), (x + facing * int(28 * scale), y - int(36 * scale)), max(4, int(7 * scale)))
        for side in (-1, 1):
            arm_x = x + side * int(74 * scale)
            pygame.draw.line(self.canvas, INK, (arm_x, y - int(65 * scale)), (arm_x + side * int(65 * scale), y + int(4 * scale)), max(22, int(38 * scale)))
            pygame.draw.line(self.canvas, (97, 77, 66), (arm_x, y - int(65 * scale)), (arm_x + side * int(65 * scale), y + int(4 * scale)), max(14, int(25 * scale)))
        if carrying_guard:
            knight = CHARACTERS_BY_KEY.get("conehead", CHARACTERS_BY_KEY["royal_guard"])
            self.draw_knight((x - facing * int(105 * scale), y - int(125 * scale)), .55 * scale, knight, facing, False, 0, weapon="lightsaber", dead=True)
        if carrying_princess:
            self.draw_white_princess((x + facing * int(110 * scale), y - int(85 * scale)), .7 * scale, False, -facing)

    def draw_cyclops_lava_revival(self, pool_x, cyclops_x, elapsed):
        """Animate the Cyclops visibly climbing out of the sealed lava pool."""
        pool_y = 572
        # Two hands punch through the surface before the head is visible.
        hand_progress = max(0.0, min(1.0, elapsed / .45))
        if hand_progress > 0:
            hand_ease = hand_progress * hand_progress * (3.0 - 2.0 * hand_progress)
            hand_clip = self.canvas.get_clip()
            self.canvas.set_clip(pygame.Rect(int(pool_x - 215), 0, 430, pool_y + 18))
            for side in (-1, 1):
                hand_x = pool_x + side * (76 + hand_ease * 25)
                hand_y = pool_y + 58 - hand_ease * 93
                wrist_y = hand_y + 75
                pygame.draw.line(
                    self.canvas, INK,
                    (hand_x, wrist_y), (hand_x + side * 9, hand_y + 10), 34,
                )
                pygame.draw.line(
                    self.canvas, (97, 77, 66),
                    (hand_x, wrist_y), (hand_x + side * 9, hand_y + 10), 23,
                )
                pygame.draw.circle(self.canvas, INK, (int(hand_x + side * 9), int(hand_y)), 30)
                pygame.draw.circle(self.canvas, (97, 77, 66), (int(hand_x + side * 9), int(hand_y)), 21)
                # Fingers curl over the pool lip.
                for finger in range(3):
                    finger_x = hand_x + side * (1 + finger * 10)
                    pygame.draw.line(
                        self.canvas, (56, 43, 41),
                        (finger_x, hand_y - 9),
                        (finger_x + side * 5, hand_y + 15), 5,
                    )
            self.canvas.set_clip(hand_clip)

        body_progress = max(0.0, min(1.0, (elapsed - .58) / 2.35))
        if body_progress > 0:
            body_ease = body_progress * body_progress * (3.0 - 2.0 * body_progress)
            cyclops_y = 775 - body_ease * 258
            # Clip the actor at the lava surface while it is still submerged.
            old_clip = self.canvas.get_clip()
            self.canvas.set_clip(pygame.Rect(int(pool_x - 215), 250, 430, pool_y - 250 + 18))
            self.draw_cyclops_actor((cyclops_x, cyclops_y), .92, -1, crying=False)
            self.canvas.set_clip(old_clip)

            # The single eye starts dead, then fills with molten light.
            eye_x = cyclops_x - 14
            eye_y = cyclops_y - 97
            pygame.draw.ellipse(self.canvas, INK, (eye_x - 50, eye_y - 27, 100, 55))
            ignition = max(0.0, min(1.0, (elapsed - 2.15) / 1.0))
            dead_color = (75, 67, 62)
            hot_color = (255, 75, 18)
            eye_color = tuple(int(dead_color[i] + (hot_color[i] - dead_color[i]) * ignition) for i in range(3))
            pygame.draw.ellipse(self.canvas, eye_color, (eye_x - 39, eye_y - 17, 78, 35))
            if ignition > 0:
                glow = pygame.Surface((160, 105), pygame.SRCALPHA)
                pygame.draw.ellipse(glow, (255, 77, 22, int(110 * ignition)), (8, 9, 144, 84))
                self.canvas.blit(glow, glow.get_rect(center=(int(eye_x), int(eye_y))), special_flags=pygame.BLEND_RGBA_ADD)
                pygame.draw.circle(self.canvas, GOLD, (int(eye_x), int(eye_y)), max(3, int(11 * ignition)))

        # Lava sheets and droplets sell each stage of the body displacing the
        # pool. They remain particles, while the character and scenery are art.
        splash_strength = max(0.0, min(1.0, elapsed / 1.8))
        if splash_strength > 0 and elapsed < 3.8:
            for index in range(14):
                angle = index / 13 * math.pi
                travel = min(1.0, elapsed * (1.15 + index % 3 * .13))
                arc = math.sin(travel * math.pi)
                drop_x = pool_x + math.cos(angle) * (52 + travel * 165)
                drop_y = pool_y - arc * (70 + index % 4 * 25) + travel * 13
                radius = max(3, 10 - index % 5)
                pygame.draw.circle(self.canvas, ORANGE, (int(drop_x), int(drop_y)), radius + 3)
                pygame.draw.circle(self.canvas, GOLD, (int(drop_x), int(drop_y)), radius)

        # Redraw the near lava lip over the submerged body and hands.
        pygame.draw.ellipse(self.canvas, INK, (pool_x - 208, pool_y - 24, 416, 91), 10)
        pygame.draw.arc(self.canvas, (242, 66, 23), (pool_x - 197, pool_y - 18, 394, 74), 0, math.pi, 16)
        pygame.draw.arc(self.canvas, GOLD, (pool_x - 178, pool_y - 12, 356, 55), 0, math.pi, 7)

    def draw_flowery_props(self):
        runtime = self.level_runtime
        if runtime.level_id != "flowery_field":
            return
        props = runtime.scene.get("props", {})
        if runtime.scene_id == "flower_road":
            cave_x = runtime.screen_x(float(props.get("cave_exit", 120)))
            if -180 < cave_x < WIDTH + 180:
                pygame.draw.ellipse(self.canvas, INK, (cave_x - 105, 280, 210, 285))
                pygame.draw.ellipse(self.canvas, (42, 39, 45), (cave_x - 84, 305, 168, 245))
            march_x = min(5650.0, 400 + self.flowery_time * 105)
            if march_x < 5700:
                sx = runtime.screen_x(march_x)
                sy = self.world_screen_y(march_x, 540)
                self.draw_horse_actor((sx, sy), .88, 1, self.flowery_time * 9)
                self.draw_knight((sx, sy - 122), .53, CHARACTERS_BY_KEY["king"], 1, False, self.flowery_time * 7, weapon=None, pointing=True, show_shield=False)
                for index in range(4):
                    guard_x = march_x - 170 - index * 100
                    self.draw_knight((runtime.screen_x(guard_x), self.world_screen_y(guard_x, 520 + index % 2 * 42) - 58), .58, CHARACTERS_BY_KEY["royal_guard"], 1, False, self.flowery_time * 9 + index, weapon="royal_spear")
            if self.flowery_catapult_ready or self.story_event and self.story_event.get("id") == "catapult_assault":
                for index, catapult_x in enumerate(props.get("catapults", [])):
                    occupied = any(int(state.get("catapult", -1)) == index and state.get("phase") == "power" for state in self.flowery_catapult_states.values())
                    self.draw_catapult(float(catapult_x), 540, occupied)
        else:
            ladder_x = float(props.get("metal_ladder", 760))
            x = runtime.screen_x(ladder_x)
            bottom = self.world_screen_y(ladder_x, 625)
            top = bottom - 320
            if -100 < x < WIDTH + 100:
                for side in (-28, 28):
                    pygame.draw.line(self.canvas, INK, (x + side, top), (x + side, bottom), 13)
                    pygame.draw.line(self.canvas, (139, 145, 149), (x + side, top), (x + side, bottom), 6)
                for y in range(int(top + 25), int(bottom), 38):
                    pygame.draw.line(self.canvas, (166, 172, 173), (x - 28, y), (x + 28, y), 6)
            for tower_key in ("tower_one", "tower_two"):
                world_x = float(props.get(tower_key, -9999))
                tx = runtime.screen_x(world_x)
                ty = self.world_screen_y(world_x, 625)
                if -150 < tx < WIDTH + 150:
                    pygame.draw.rect(self.canvas, INK, (tx - 63, ty - 275, 126, 290))
                    pygame.draw.rect(self.canvas, (93, 88, 90), (tx - 53, ty - 264, 106, 270))
                    pygame.draw.polygon(self.canvas, INK, [(tx - 78, ty - 268), (tx, ty - 345), (tx + 78, ty - 268)])
                    if tower_key == "tower_one":
                        event_t = self.story_event_time if self.story_event and self.story_event.get("id") == "village_bombardment" else (9 if ("flowery_field", "village_bombardment") in self.story_events_seen else 0)
                        if event_t >= 1.5:
                            pygame.draw.lines(self.canvas, (35, 32, 36), False, [(tx - 42, ty - 230), (tx - 8, ty - 180), (tx - 31, ty - 126)], 9)
                        if event_t >= 2.8:
                            pygame.draw.polygon(self.canvas, (24, 26, 30), [(tx + 12, ty - 260), (tx + 53, ty - 241), (tx + 48, ty - 167), (tx + 6, ty - 190)])
                            for debris in range(5):
                                pygame.draw.rect(self.canvas, (106, 101, 101), (tx + 65 + debris * 17, ty - 240 + debris % 2 * 35, 12, 12))
            roof_range = props.get("roof", [])
            if len(roof_range) == 2:
                left = runtime.screen_x(float(roof_range[0]))
                right = runtime.screen_x(float(roof_range[1]))
                if right > -100 and left < WIDTH + 100:
                    pygame.draw.rect(self.canvas, INK, (left, 210, right - left, 35))
                    for beam_x in range(int(left), int(right) + 1, 145):
                        pygame.draw.line(self.canvas, (74, 57, 49), (beam_x, 225), (beam_x, 595), 20)
                    pygame.draw.rect(self.canvas, (91, 68, 54), (left, 218, right - left, 18))
            for world_x in props.get("pillars", []):
                px = runtime.screen_x(float(world_x))
                py = self.world_screen_y(float(world_x), 625)
                if -90 < px < WIDTH + 90:
                    pygame.draw.rect(self.canvas, INK, (px - 35, py - 290, 70, 305))
                    pygame.draw.rect(self.canvas, (116, 111, 109), (px - 27, py - 282, 54, 288))
                    pygame.draw.rect(self.canvas, (146, 140, 134), (px - 45, py - 300, 90, 27))
            for house_index, world_x in enumerate(props.get("burning_houses", [])):
                hx = runtime.screen_x(float(world_x))
                hy = 410
                if -160 < hx < WIDTH + 160:
                    pygame.draw.rect(self.canvas, (113, 82, 69), (hx - 82, hy - 108, 164, 118))
                    pygame.draw.polygon(self.canvas, (75, 54, 58), [(hx - 98, hy - 105), (hx, hy - 185), (hx + 98, hy - 105)])
                    event_t = self.story_event_time if self.story_event and self.story_event.get("id") == "village_bombardment" else (9 if ("flowery_field", "village_bombardment") in self.story_events_seen else 0)
                    if event_t >= 4.3 + house_index * 1.4:
                        for flame in range(5):
                            fx = hx - 60 + flame * 30
                            pygame.draw.polygon(self.canvas, ORANGE, [(fx - 13, hy - 94), (fx, hy - 175 - flame % 2 * 25), (fx + 14, hy - 94)])
                            pygame.draw.polygon(self.canvas, GOLD, [(fx - 7, hy - 96), (fx, hy - 138), (fx + 7, hy - 96)])
            if "breakable:church_window" in self.scene_flags:
                wx = runtime.screen_x(float(props.get("window", 8900)))
                wy = self.world_screen_y(float(props.get("window", 8900)), 520)
                pygame.draw.rect(self.canvas, INK, (wx - 76, wy - 188, 152, 199), border_radius=8)
                pygame.draw.rect(self.canvas, (30, 32, 38), (wx - 65, wy - 176, 130, 177), border_radius=6)

