    def draw_giant_stone_arch(self, x, y, show_label=True):
        """Draw the Castle Keep entrance as a massive stone gateway."""
        key = "props/giant_stone_arch_label" if show_label else "props/giant_stone_arch"
        if self.draw_art_image(key, (x, y), 1024):
            return
        outer = (x - 194, y - 415, 388, 458)
        pygame.draw.ellipse(self.canvas, INK, (outer[0], outer[1], outer[2], 344))
        pygame.draw.rect(self.canvas, INK, (outer[0], y - 245, outer[2], 288))
        pygame.draw.ellipse(self.canvas, (113, 116, 118), (x - 181, y - 402, 362, 319))
        pygame.draw.rect(self.canvas, (113, 116, 118), (x - 181, y - 244, 362, 274))

        # Large masonry blocks and wedge stones around the arch crown.
        for row, block_y in enumerate(range(y - 228, y + 18, 64)):
            offset = -49 if row % 2 else 0
            for block_x in range(x - 178 + offset, x + 180, 98):
                pygame.draw.rect(self.canvas, (72, 78, 82), (block_x, block_y, 91, 57), 4)
        pygame.draw.arc(self.canvas, (63, 69, 73), (x - 166, y - 385, 332, 292), math.pi, math.tau, 12)
        pygame.draw.arc(self.canvas, (151, 153, 151), (x - 148, y - 367, 296, 260), math.pi, math.tau, 8)

        # Deep opening, broad enough for the entire kidnapping procession.
        pygame.draw.ellipse(self.canvas, INK, (x - 116, y - 326, 232, 274))
        pygame.draw.rect(self.canvas, INK, (x - 116, y - 190, 232, 225))
        pygame.draw.ellipse(self.canvas, (29, 28, 33), (x - 101, y - 309, 202, 245))
        pygame.draw.rect(self.canvas, (29, 28, 33), (x - 101, y - 188, 202, 211))
        for side in (-1, 1):
            pillar_x = x + side * 146
            pygame.draw.rect(self.canvas, INK, (pillar_x - 28, y - 250, 56, 286), border_radius=7)
            pygame.draw.rect(self.canvas, (132, 134, 133), (pillar_x - 20, y - 241, 40, 269), border_radius=5)
        if show_label:
            self.text("CASTLE KEEP", 20, CREAM, (x, y - 432), True, 3)

